window.GEPT_BASIC_SENTENCES = {"1": {"title": "Part 1 句子改寫 Rewriting", "blocks": [{"name": "時態改寫（現在簡單／現在進行／過去／未來）", "subs": [{"name": "進行式 be + V-ing", "sets": [{"id": "R001", "src": "附件1 Q1", "q": {"orig": "Did the children take a nap just now?", "stem": "Were ___ a nap while their mom was cooking at 4:30 yesterday afternoon?"}, "ans": "Were **the children taking** a nap while their mom was cooking at 4:30 yesterday afternoon?", "variants": [{"tag": "單數主詞＋過去進行式", "orig": "Did Amy take a shower just now?", "stem": "Was ___ a shower when her mom came home last night?", "ans": "Was **Amy taking** a shower when her mom came home last night?"}, {"tag": "第二人稱＋過去進行式", "orig": "Did you watch TV at eight last night?", "stem": "Were ___ TV at eight last night?", "ans": "Were **you watching** TV at eight last night?"}, {"tag": "第三人稱單數＋現在進行式", "orig": "Does Ben do his homework after dinner?", "stem": "Is ___ his homework right now?", "ans": "Is **Ben doing** his homework right now?"}], "expl": ["句型：Was/Were + S + V-ing ...?（過去進行式問句）", "時間詞要配合時態：過去進行式要有明確的過去時間點或 while/when 子句（while their mom was cooking at 4:30 yesterday afternoon），不能用 just now；just now 只配過去簡單式（Did ... just now?）。", "主詞 the children 複數 → Were ... taking。Amy 單數 → Was；you → Were；right now → 現在進行式 Is Ben doing。", "易錯：寫成 Were the children take，be 動詞後的動詞一定要用 V-ing。"]}, {"id": "R022", "src": "附件5 Q2", "q": {"orig": "Jack wears a school uniform on weekdays.", "stem": "Jack ___ now."}, "ans": "Jack **is wearing a school uniform** now.", "variants": [{"tag": "複數主詞＋現在進行式", "orig": "The kids play dodgeball after school.", "stem": "The kids ___ now.", "ans": "The kids **are playing dodgeball** now."}, {"tag": "第一人稱＋現在進行式", "orig": "I take a shower before bed.", "stem": "I ___ now.", "ans": "I **am taking a shower** now."}, {"tag": "第三人稱單數＋過去進行式", "orig": "Lucy studies in the library on Mondays.", "stem": "Lucy ___ at 3 p.m. yesterday.", "ans": "Lucy **was studying in the library** at 3 p.m. yesterday."}], "expl": ["句型：S + am/is/are + V-ing（現在進行式）；S + was/were + V-ing（過去進行式）", "時間詞要配合時態：now 配現在進行式（is wearing）；過去進行式要有明確過去時間點（at 3 p.m. yesterday），不能只寫 yesterday 或 just now。on weekdays / on Mondays 是現在簡單式的時間詞，改寫時要拿掉。", "Jack 單數 → is wearing；the kids → are；I → am taking（去 e 加 ing）；Lucy → was studying。易錯：Jack is wear 或 Jack wearing。"]}, {"id": "R031", "src": "附件7 Q1", "q": {"orig": "John washes his new car outside his home.", "stem": "John ___ outside his home right now."}, "ans": "John **is washing his new car** outside his home right now.", "variants": [{"tag": "複數主詞＋現在進行式", "orig": "The boys play basketball in the park.", "stem": "The boys ___ in the park right now.", "ans": "The boys **are playing basketball** in the park right now."}, {"tag": "第一人稱＋現在進行式", "orig": "I do my homework in my room.", "stem": "I ___ in my room right now.", "ans": "I **am doing my homework** in my room right now."}, {"tag": "第三人稱單數＋過去進行式", "orig": "Grandma cooks dinner in the kitchen.", "stem": "Grandma ___ in the kitchen at six last night.", "ans": "Grandma **was cooking dinner** in the kitchen at six last night."}], "expl": ["句型：S + am/is/are + V-ing（現在進行式）；S + was/were + V-ing（過去進行式）", "時間詞要配合時態：right now 配現在進行式；過去進行式要有明確過去時間點（at six last night）。", "John 單數 → is washing；the boys → are playing；I → am doing；Grandma → was cooking。易錯：John is washes 或 John washing。"]}, {"id": "R057", "src": "附件17 Q1", "q": {"orig": "I was walking my dog when it started to rain.", "stem": "I am ___ and it is ___."}, "ans": "I am **walking my dog** and it is **raining**.", "variants": [{"tag": "第三人稱單數", "orig": "Mia was doing her homework when the phone started to ring.", "stem": "Mia is ___ and the phone is ___.", "ans": "Mia is **doing her homework** and the phone is **ringing**."}, {"tag": "第一人稱複數", "orig": "We were eating at the night market when it started to rain.", "stem": "We are ___ and it is ___.", "ans": "We are **eating at the night market** and it is **raining**."}, {"tag": "複數主詞＋改回過去進行式", "orig": "My parents are watching TV and the baby is crying.", "stem": "My parents were ___ when the baby started ___.", "ans": "My parents were **watching TV** when the baby started **to cry**."}], "expl": ["句型：現在進行式 S + am/is/are + V-ing；過去進行式 S + was/were + V-ing。", "題目已給 am / is，所以兩邊都用 V-ing：walking、raining。類似題：Mia → is；We、My parents → are/were；start 後接 to V（started to cry）。", "易錯：I am walk my dog（漏 -ing）；it is rain（rain 也要變 raining）。", "時間詞要配合時態：現在進行式表「正在」（可加 now）；過去進行式要有明確的過去時間點或 when/while 子句（when the baby started to cry），不能只寫 just now。"]}, {"id": "R077", "src": "模擬試題第3回 Q1", "q": {"orig": "David studies at the library every night.", "stem": "David ___ right now."}, "ans": "David **is studying at the library** right now.", "variants": [{"tag": "複數主詞＋現在進行式", "orig": "My classmates play volleyball every afternoon.", "stem": "My classmates ___ right now.", "ans": "My classmates **are playing volleyball** right now."}, {"tag": "第一人稱＋現在進行式", "orig": "I take a shower every night.", "stem": "I ___ right now.", "ans": "I **am taking a shower** right now."}, {"tag": "第三人稱單數＋過去進行式", "orig": "Sam rides his bike every evening.", "stem": "Sam ___ at seven last night.", "ans": "Sam **was riding his bike** at seven last night."}], "expl": ["句型：right now → S + am/is/are + V-ing；過去某時間點 → was/were + V-ing。David 單數 → is studying；類似題：複數 are、I am、過去 was；take → taking、ride → riding（去 e 加 ing）。", "原題題幹「David studies ___ right now.」與 right now 矛盾，依句意更正為「David ___ right now.」。", "易錯：David is studies / is study（be 後要 V-ing）。", "時間詞要配合時態：right now → 現在進行式；過去進行式要有明確的過去時間點（at seven last night），不能用 just now 或只寫 yesterday。"]}, {"id": "R082", "src": "模擬試題第4回 Q1", "q": {"orig": "Anna swam in the ocean yesterday.", "stem": "Anna ___ in the ocean now."}, "ans": "Anna **is swimming** in the ocean now.", "variants": [{"tag": "複數主詞＋現在進行式", "orig": "The children ran in the park yesterday.", "stem": "The children ___ in the park now.", "ans": "The children **are running** in the park now."}, {"tag": "第一人稱＋現在進行式", "orig": "I sat on the bench yesterday.", "stem": "I ___ on the bench now.", "ans": "I **am sitting** on the bench now."}, {"tag": "第三人稱單數＋未來式", "orig": "Ted shopped at the mall yesterday.", "stem": "Ted ___ at the mall tomorrow.", "ans": "Ted **will shop** at the mall tomorrow."}], "expl": ["句型：now → S + am/is/are + V-ing；tomorrow → will + 原形V。", "swam 原形 swim，短母音結尾要重複子音 → swimming。類似題：ran → run → running；sat → sit → sitting；shopped → will shop。", "易錯：is swiming（少一個 m）；is swam（be 後不能接過去式）。", "時間詞要配合時態：yesterday → 過去式；now → be + V-ing；tomorrow → will + 原形。不可寫 Anna is swimming yesterday。"]}]}, {"name": "未來 will／had to 變化", "sets": [{"id": "R013", "src": "附件3 Q3", "q": {"orig": "Those managers considered the situation more carefully.（用had to）", "stem": "___."}, "ans": "**Those managers had to consider the situation more carefully**.", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Amy cleans her room every Sunday.（用has to）", "stem": "___.", "ans": "**Amy has to clean her room every Sunday**."}, {"tag": "第一人稱複數＋未來式", "orig": "We will wear raincoats tomorrow.（用will have to）", "stem": "___.", "ans": "**We will have to wear raincoats tomorrow**."}, {"tag": "複數主詞＋現在式", "orig": "The students take the MRT to school.（用have to）", "stem": "___.", "ans": "**The students have to take the MRT to school**."}], "expl": ["句型：S + have to / has to / had to / will have to + 原形V（必須）", "原句過去式 → had to，後面的 considered 還原成 consider。have to 本身隨時態、人稱變化：has to（第三人稱單數現在）、will have to（未來）。", "易錯：寫成 had to considered（have to 後只能接原形動詞）。"]}, {"id": "R092", "src": "模擬試題第6回 Q1", "q": {"orig": "Leo left the city yesterday morning.", "stem": "Leo ___ the city tomorrow morning."}, "ans": "Leo **will leave** the city tomorrow morning.", "variants": [{"tag": "複數主詞＋未來式", "orig": "My cousins visited Taipei last week.", "stem": "My cousins ___ Taipei next week.", "ans": "My cousins **will visit** Taipei next week."}, {"tag": "第一人稱＋be going to", "orig": "I wrote a card to my teacher yesterday.", "stem": "I ___ a card to my teacher tomorrow.", "ans": "I **am going to write** a card to my teacher tomorrow."}, {"tag": "第三人稱單數＋現在簡單式", "orig": "Sue caught the bus at seven yesterday.", "stem": "Sue ___ the bus at seven every day.", "ans": "Sue **catches** the bus at seven every day."}], "expl": ["句型：tomorrow → will + 原形V ／ be going to + 原形V；every day → 現在簡單式。", "left 原形是 leave → will leave（也可寫 is going to leave）。類似題：wrote → am going to write（I 用 am）；caught → catches（ch 結尾加 es）。", "易錯：will left（will 後要原形）；Sue catchs。", "時間詞要配合時態：tomorrow / next week → will 或 be going to；every day → 現在簡單式；yesterday、last week 只能配過去式。"]}]}, {"name": "現在簡單式 every day", "sets": [{"id": "R016", "src": "附件4 Q1", "q": {"orig": "Gina drove to school yesterday.", "stem": "Gina ___ every day."}, "ans": "Gina **drives to school** every day.", "variants": [{"tag": "複數主詞＋現在式", "orig": "My parents walked to the park yesterday.", "stem": "My parents ___ every day.", "ans": "My parents **walk to the park** every day."}, {"tag": "第一人稱＋未來式", "orig": "I took the MRT to work yesterday.", "stem": "I ___ tomorrow.", "ans": "I **will take the MRT to work** tomorrow."}, {"tag": "第三人稱單數＋現在進行式", "orig": "Ben rode his bike to school yesterday.", "stem": "Ben ___ now.", "ans": "Ben **is riding his bike to school** now."}], "expl": ["句型：every day → 現在簡單式；tomorrow → will + 原形V；now → be + V-ing", "時間詞要配合時態：yesterday 配過去式（drove），換成 every day 就要用現在簡單式，換成 tomorrow 用 will，換成 now 用現在進行式；不能出現 drove ... every day。", "Gina 第三人稱單數 → drives；my parents → walk；tomorrow → will take；now → is riding（ride 去 e 加 ing）。易錯：仍寫 drove，或寫成 Gina drive。"]}, {"id": "R036", "src": "附件8 Q1", "q": {"orig": "Sam took a bus to school this morning.（用 every day）", "stem": "Sam ___."}, "ans": "Sam **takes a bus to school every day**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "My brothers walked to school this morning.（用 every day）", "stem": "My brothers ___.", "ans": "My brothers **walk to school every day**."}, {"tag": "第三人稱單數＋未來式", "orig": "Lisa had milk for breakfast this morning.（用 tomorrow）", "stem": "Lisa ___.", "ans": "Lisa **will have milk for breakfast tomorrow**."}, {"tag": "第一人稱＋現在進行式", "orig": "I waited for the bus this morning.（用 now）", "stem": "I ___.", "ans": "I **am waiting for the bus now**."}], "expl": ["句型：every day → 現在簡單式；tomorrow → will + 原形V；now → be + V-ing", "時間詞要配合時態：this morning（已過去）配過去式，換成 every day 用現在簡單式，tomorrow 用 will，now 用現在進行式；改寫時原句的 this morning 要拿掉。", "Sam 單數 → takes；my brothers → walk；Lisa → will have；I → am waiting。易錯：Sam take / Sam took a bus to school every day。"]}, {"id": "R050", "src": "附件10 Q5", "q": {"orig": "John played tennis yesterday.", "stem": "John ___ every day."}, "ans": "John **plays tennis** every day.", "variants": [{"tag": "複數主詞＋現在簡單式", "orig": "My brothers watched TV last night.", "stem": "My brothers ___ every night.", "ans": "My brothers **watch TV** every night."}, {"tag": "第一人稱＋過去式", "orig": "I take the MRT to school every day.", "stem": "I ___ yesterday.", "ans": "I **took the MRT to school** yesterday."}, {"tag": "第三人稱單數＋未來式", "orig": "Amy studied English last night.", "stem": "Amy ___ tomorrow.", "ans": "Amy **will study English** tomorrow."}], "expl": ["句型：every day → 現在簡單式；yesterday → 過去式；tomorrow → will + 原形V。", "John 是第三人稱單數，現在式 play 要加 s → plays。類似題：My brothers 是複數 → watch 不加 s；take 過去式為不規則 took；will 後接原形 study。", "易錯：寫成 John play tennis every day（漏 s）或 Amy will studies（will 後要用原形）。", "時間詞要配合時態：every day / every night → 現在簡單式；yesterday / last night → 過去式；tomorrow → 未來式。不可寫 John played tennis every day。"]}, {"id": "R072", "src": "模擬試題第2回 Q1", "q": {"orig": "Peter is jogging in the park now.", "stem": "Peter ___ every morning."}, "ans": "Peter **jogs in the park** every morning.", "variants": [{"tag": "複數主詞＋現在簡單式", "orig": "The girls are dancing in the gym now.", "stem": "The girls ___ every afternoon.", "ans": "The girls **dance in the gym** every afternoon."}, {"tag": "第三人稱單數＋過去式", "orig": "Grandpa is reading the newspaper now.", "stem": "Grandpa ___ yesterday morning.", "ans": "Grandpa **read the newspaper** yesterday morning."}, {"tag": "第一人稱＋未來式", "orig": "I am practicing the piano now.", "stem": "I ___ tomorrow.", "ans": "I **will practice the piano** tomorrow."}], "expl": ["句型：now → 現在進行式；every morning（習慣）→ 現在簡單式。", "Peter 第三人稱單數 → jogs。類似題：The girls 複數 → dance 不加 s；read 過去式拼字相同（發音 /rɛd/）；tomorrow → will practice。", "易錯：Peter is jogs / Peter jog（be 與 V-s 不並用；單數要加 s）。", "時間詞要配合時態：now → 現在進行式；every morning / every afternoon → 現在簡單式；yesterday morning → 過去式；tomorrow → will。不可寫 Peter is jogging every morning。"]}]}, {"name": "過去式 yesterday／last", "sets": [{"id": "R027", "src": "附件6 Q2", "q": {"orig": "She is buying the singer's album now.", "stem": "She ___ the singer's album yesterday."}, "ans": "She **bought** the singer's album yesterday.", "variants": [{"tag": "複數主詞＋過去式", "orig": "They are watching the baseball game now.", "stem": "They ___ the baseball game yesterday.", "ans": "They **watched** the baseball game yesterday."}, {"tag": "第一人稱＋未來式", "orig": "I am cleaning my room now.", "stem": "I ___ my room tomorrow.", "ans": "I **will clean** my room tomorrow."}, {"tag": "第三人稱單數＋現在簡單式", "orig": "He is eating stinky tofu now.", "stem": "He ___ stinky tofu every weekend.", "ans": "He **eats** stinky tofu every weekend."}], "expl": ["句型：yesterday → 過去式；tomorrow → will + 原形V；every weekend → 現在簡單式", "時間詞要配合時態：now 配現在進行式，題幹換成 yesterday 就要改過去式，tomorrow 改 will，every weekend 改現在簡單式；不能寫 was buying ... yesterday（只有 yesterday 沒有時間點，不用進行式）。", "buy → bought（不規則）；watch → watched；will clean；he + every weekend → eats。易錯：buyed，或寫成 She was bought（變被動）。"]}, {"id": "R041", "src": "附件10 Q1", "q": {"orig": "I go to school every night.", "stem": "I ___ last week."}, "ans": "I **went to school every night** last week.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Amy plays the piano every afternoon.", "stem": "Amy ___ last week.", "ans": "Amy **played the piano every afternoon** last week."}, {"tag": "複數主詞＋未來式", "orig": "They study in the library every evening.", "stem": "They ___ next week.", "ans": "They **will study in the library every evening** next week."}, {"tag": "第三人稱單數＋過去式（規則）", "orig": "My dad works late every day.", "stem": "My dad ___ last month.", "ans": "My dad **worked late every day** last month."}], "expl": ["句型：last week → 過去式；next week → will + 原形V", "時間詞要配合時態：every night 本身是頻率詞，加上 last week 就要用過去式（went），加上 next week 用 will；只有 every night 時才用現在簡單式。", "go → went（不規則）；plays → played；will study；works → worked，過去式不論人稱都一樣。易錯：I goed，或 playsed。"]}, {"id": "R062", "src": "附件19 Q1", "q": {"orig": "Jessica is going to come home late today.", "stem": "Jessica ___ yesterday."}, "ans": "Jessica **came home late** yesterday.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My parents are going to visit Grandma this weekend.", "stem": "My parents ___ last weekend.", "ans": "My parents **visited Grandma** last weekend."}, {"tag": "第一人稱＋過去式", "orig": "I am going to take a bus to school tomorrow.", "stem": "I ___ yesterday.", "ans": "I **took a bus to school** yesterday."}, {"tag": "第三人稱單數＋現在式→未來式", "orig": "Ken buys bubble tea every afternoon.", "stem": "Ken ___ tomorrow afternoon.", "ans": "Ken **is going to buy bubble tea** tomorrow afternoon."}], "expl": ["句型：be going to + 原形V（未來）→ yesterday 用過去式 V-ed / 不規則變化。", "come 的過去式是不規則的 came。類似題：visit → visited（規則）；take → took（不規則）；tomorrow → is going to buy（Ken 單數用 is，也可寫 will buy）。", "易錯：Jessica comed / was came home late（came 不加 -ed、不加 be 動詞）。", "時間詞要配合時態：yesterday / last weekend → 過去式；tomorrow afternoon → be going to / will；today、this weekend 可用於未來，但改成 yesterday 就必須用過去式。"]}, {"id": "R067", "src": "模擬試題第1回 Q1", "q": {"orig": "Nick goes swimming every night.", "stem": "Nick ___ last night."}, "ans": "Nick **went swimming** last night.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The boys play basketball every afternoon.", "stem": "The boys ___ yesterday afternoon.", "ans": "The boys **played basketball** yesterday afternoon."}, {"tag": "第三人稱單數＋未來式", "orig": "Mary goes shopping every Sunday.", "stem": "Mary ___ next Sunday.", "ans": "Mary **will go shopping** next Sunday."}, {"tag": "第一人稱複數＋現在進行式", "orig": "We take a walk every evening.", "stem": "We ___ right now.", "ans": "We **are taking a walk** right now."}], "expl": ["句型：last night → 過去式；next Sunday → will + 原形V；right now → be + V-ing。", "go 的過去式是不規則的 went，swimming 不變。類似題：play → played；will 後 go 用原形；We → are taking（take 去 e 加 ing）。", "易錯：Nick goed / was went swimming；Mary will goes shopping。", "時間詞要配合時態：last night / yesterday afternoon → 過去式；next Sunday → will + 原形；right now → be + V-ing；every night → 現在簡單式。"]}, {"id": "R087", "src": "模擬試題第5回 Q1", "q": {"orig": "Mike wears a suit to his office every day.", "stem": "Mike ___ a suit to his office yesterday."}, "ans": "Mike **wore** a suit to his office yesterday.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My parents bring lunch to work every day.", "stem": "My parents ___ lunch to work yesterday.", "ans": "My parents **brought** lunch to work yesterday."}, {"tag": "第一人稱＋未來式", "orig": "I ride my bike to school every day.", "stem": "I ___ my bike to school tomorrow.", "ans": "I **will ride** my bike to school tomorrow."}, {"tag": "第三人稱單數＋現在進行式", "orig": "Lily wears a raincoat on rainy days.", "stem": "Lily ___ a raincoat now.", "ans": "Lily **is wearing** a raincoat now."}], "expl": ["句型：yesterday → 過去式；tomorrow → will + 原形V；now → be + V-ing。", "wear 的過去式是不規則的 wore。類似題：bring → brought；will ride（原形）；Lily 單數 → is wearing。", "易錯：weared / bringed（不規則動詞）；will rides。", "時間詞要配合時態：yesterday → 過去式；tomorrow → will；now → is wearing；every day / on rainy days → 現在簡單式。"]}]}]}, {"name": "疑問句改寫（Yes/No 問句與 Wh- 問句）", "subs": [{"name": "Yes/No 問句 (Be/助動詞)", "sets": [{"id": "R009", "src": "附件2 Q4", "q": {"orig": "Cindy is good at singing.", "stem": "Is ___?"}, "ans": "Is **Cindy good at singing**?", "variants": [{"tag": "複數主詞＋現在式", "orig": "Tom and Ken are good at drawing.", "stem": "Are ___?", "ans": "Are **Tom and Ken good at drawing**?"}, {"tag": "第三人稱單數＋過去式", "orig": "Your sister was afraid of dogs.", "stem": "Was ___?", "ans": "Was **your sister afraid of dogs**?"}, {"tag": "第二人稱＋過去式", "orig": "You were late for school yesterday.", "stem": "Were ___?", "ans": "Were **you late for school yesterday**?"}], "expl": ["句型：Be + S + adj + ...?（be 動詞 Yes/No 問句）", "把 is 移到句首，其餘照抄：Is Cindy good at singing? 複數主詞 → Are；過去式單數 → Was；you 無論單複數都用 Were。", "易錯：寫成 Does Cindy good at singing?（有 be 動詞時不用 do/does）。"]}, {"id": "R032", "src": "附件7 Q2", "q": {"orig": "Helen will go to the movies on Saturday night.", "stem": "Will ___ on Saturday night?"}, "ans": "Will **Helen go to the movies** on Saturday night?", "variants": [{"tag": "複數主詞＋未來式", "orig": "Your parents will visit Hualien next week.", "stem": "Will ___ next week?", "ans": "Will **your parents visit Hualien** next week?"}, {"tag": "第三人稱單數＋現在式", "orig": "Kevin goes swimming on Sunday mornings.", "stem": "Does ___ on Sunday mornings?", "ans": "Does **Kevin go swimming** on Sunday mornings?"}, {"tag": "第二人稱＋過去式", "orig": "You went to the night market on Friday night.", "stem": "Did ___ on Friday night?", "ans": "Did **you go to the night market** on Friday night?"}], "expl": ["句型：Will/Does/Did + S + 原形V ...?", "把 will 移到句首，其餘照抄。現在式第三人稱單數 → Does + go；過去式 → Did + go（went 還原）。", "易錯：寫成 Will Helen goes...，或 Does Kevin goes...。"]}, {"id": "R063", "src": "附件19 Q2", "q": {"orig": "It is important to be on time.", "stem": "Is ___?"}, "ans": "Is **it important to be on time**?", "variants": [{"tag": "過去式", "orig": "It was hard to find a seat on the MRT.", "stem": "Was ___?", "ans": "Was **it hard to find a seat on the MRT**?"}, {"tag": "未來式", "orig": "It will be fun to go to the night market.", "stem": "Will ___?", "ans": "Will **it be fun to go to the night market**?"}, {"tag": "複數主詞＋一般動詞", "orig": "The students like to play basketball.", "stem": "Do ___?", "ans": "Do **the students like to play basketball**?"}], "expl": ["句型：be 動詞問句：Be + S + …?；助動詞問句：Will/Do + S + 原形V…?", "把 is 移到句首，其餘照抄：Is it important to be on time?。類似題：was → Was it…；will 移前、be 留下；一般動詞 like 要借助動詞 Do（複數主詞用 Do）。", "易錯：Is important to be on time?（漏虛主詞 it）；Do the students likes…（Do 後動詞用原形）。", "時間詞要配合時態：本題無時間詞，問句的 be 動詞／助動詞照原句時態（Is / Was / Will / Do）。"]}, {"id": "R079", "src": "模擬試題第3回 Q3", "q": {"orig": "Nancy should talk to her teacher immediately.", "stem": "Should ___ her teacher immediately?"}, "ans": "Should **Nancy talk to** her teacher immediately?", "variants": [{"tag": "複數主詞＋should", "orig": "The boys should say sorry to their mom.", "stem": "Should ___ their mom?", "ans": "Should **the boys say sorry to** their mom?"}, {"tag": "第三人稱單數＋can", "orig": "Peter can ride a bike to school.", "stem": "Can ___ to school?", "ans": "Can **Peter ride a bike** to school?"}, {"tag": "第一人稱複數＋未來式", "orig": "We will visit our grandparents this weekend.", "stem": "Will ___ this weekend?", "ans": "Will **we visit our grandparents** this weekend?"}], "expl": ["句型：助動詞問句：Should/Can/Will + S + 原形V…?", "把 should 移到句首，主詞 Nancy 接在後，talk to 不變。類似題：can、will 用法相同；助動詞後動詞一律原形，不因主詞單複數改變。", "易錯：Should Nancy talks to…；漏掉介系詞 to。", "時間詞要配合時態：should / can 不隨時間詞改變；this weekend 表未來 → Will。"]}]}, {"name": "Yes/No 問句 (Do/Does)", "sets": [{"id": "R010", "src": "附件2 Q5", "q": {"orig": "Ryan has a toy robot.", "stem": "Does ___ ___?"}, "ans": "Does **Ryan have** **a toy robot**?", "variants": [{"tag": "複數主詞＋現在式", "orig": "My cousins have a big dog.", "stem": "Do ___ ___?", "ans": "Do **my cousins have** **a big dog**?"}, {"tag": "第三人稱單數＋過去式", "orig": "Lisa had a cold last week.", "stem": "Did ___ ___?", "ans": "Did **Lisa have** **a cold last week**?"}, {"tag": "第三人稱單數＋一般動詞", "orig": "Kevin rides a bike to school.", "stem": "Does ___ ___?", "ans": "Does **Kevin ride** **a bike to school**?"}], "expl": ["句型：Does + S + 原形V + ...?", "原題題幹被浮水印（三民網路書店）遮住，依句意兩空分別填 Ryan have／a toy robot。用 Does 開頭後，has 要還原成 have。", "類似題：複數主詞 → Do；過去式 → Did + 原形 have；rides → ride。易錯：Does Ryan has a toy robot?"]}, {"id": "R026", "src": "附件6 Q1", "q": {"orig": "Alex usually goes to school late.", "stem": "Does ___ late?"}, "ans": "Does **Alex usually go to school** late?", "variants": [{"tag": "複數主詞＋現在式", "orig": "The twins often get up late.", "stem": "Do ___ late?", "ans": "Do **the twins often get up** late?"}, {"tag": "第三人稱單數＋過去式", "orig": "Mike came home late last night.", "stem": "Did ___ late last night?", "ans": "Did **Mike come home** late last night?"}, {"tag": "第二人稱＋現在式", "orig": "You always go to bed late.", "stem": "Do ___ late?", "ans": "Do **you always go to bed** late?"}], "expl": ["句型：Does/Do/Did + S + (頻率副詞) + 原形V ...?", "Does 開頭後 goes 還原為 go；頻率副詞 usually 放在主詞與動詞之間。複數主詞、you → Do；過去式 → Did + come。", "易錯：寫成 Does Alex usually goes...（助動詞後要原形）。"]}]}, {"name": "Wh- 問句 (過去式 did)", "sets": [{"id": "R017", "src": "附件4 Q2", "q": {"orig": "Tom went shopping with his mom yesterday.", "stem": "When ___?"}, "ans": "When **did Tom go shopping with his mom**?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Amy plays the piano after dinner.", "stem": "When ___?", "ans": "When **does Amy play the piano**?"}, {"tag": "複數主詞＋過去式", "orig": "The students visited the museum last Friday.", "stem": "When ___?", "ans": "When **did the students visit the museum**?"}, {"tag": "複數主詞＋未來式", "orig": "They will go to the night market tonight.", "stem": "When ___?", "ans": "When **will they go to the night market**?"}], "expl": ["句型：When + did/does/do/will + S + 原形V ...?", "問時間 → 把 yesterday 拿掉，過去式用 did，went 還原為 go。現在式第三人稱單數 → does + play；未來式 → will + go。", "易錯：寫成 When did Tom went...（did 後要用原形）。"]}, {"id": "R021", "src": "附件5 Q1", "q": {"orig": "Peter gave a present to Carol.", "stem": "What ___ to Carol?"}, "ans": "What **did Peter give** to Carol?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Ms. Wu teaches English to the kids.", "stem": "What ___ to the kids?", "ans": "What **does Ms. Wu teach** to the kids?"}, {"tag": "複數主詞＋過去式", "orig": "The students sent cards to their teacher.", "stem": "What ___ to their teacher?", "ans": "What **did the students send** to their teacher?"}, {"tag": "第三人稱單數＋未來式", "orig": "Amy will show her photos to us.", "stem": "What ___ to us?", "ans": "What **will Amy show** to us?"}], "expl": ["句型：What + did/does/will + S + 原形V + to + 人?", "問「送了什麼」→ What 取代 a present，過去式用 did，gave 還原為 give。現在式第三人稱單數 → does teach；未來式 → will show。", "易錯：寫成 What Peter gave to Carol? 或 What did Peter gave...?"]}, {"id": "R028", "src": "附件6 Q3", "q": {"orig": "Tina brushed her teeth at seven o'clock this morning.", "stem": "What time ___ this morning?"}, "ans": "What time **did Tina brush her teeth** this morning?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Sam gets up at six every day.", "stem": "What time ___ every day?", "ans": "What time **does Sam get up** every day?"}, {"tag": "複數主詞＋過去式", "orig": "The kids went to bed at ten last night.", "stem": "What time ___ last night?", "ans": "What time **did the kids go to bed** last night?"}, {"tag": "單數主詞＋未來式", "orig": "The train will leave at 3:30 this afternoon.", "stem": "What time ___ this afternoon?", "ans": "What time **will the train leave** this afternoon?"}], "expl": ["句型：What time + did/does/will + S + 原形V ...?", "問時刻 → 去掉 at seven o'clock，用 did，brushed 還原為 brush。gets → does + get；went → did + go；will leave → will the train leave。", "易錯：寫成 What time did Tina brushed...。"]}, {"id": "R039", "src": "附件8 Q4", "q": {"orig": "I paid twenty thousand dollars for this smartphone.", "stem": "How much ___ cost ___?"}, "ans": "How much **did this smartphone** cost **you**?", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Amy paid five hundred dollars for the shoes.", "stem": "How much ___ cost ___?", "ans": "How much **did the shoes** cost **Amy**?"}, {"tag": "第一人稱複數＋現在式", "orig": "We pay sixty dollars for a cup of bubble tea.", "stem": "How much ___ cost ___?", "ans": "How much **does a cup of bubble tea** cost **you**?"}, {"tag": "第三人稱單數＋未來式", "orig": "Ken will pay two thousand dollars for the concert ticket.", "stem": "How much ___ cost ___?", "ans": "How much **will the concert ticket** cost **Ken**?"}], "expl": ["句型：人 + pay + 錢 + for + 物 ＝ 物 + cost + 人 + 錢 → How much + did/does/will + 物 + cost + 人?", "主詞變成物 this smartphone；問對方 → I 改成 you。單數物品現在式 → does；複數 the shoes 過去式仍用 did；未來式 → will。", "易錯：寫成 did ... costed（did 後用原形 cost），或忘了把 I 改為 you。"]}, {"id": "R047", "src": "附件10 Q2", "q": {"orig": "Jane bought a new dress yesterday.", "stem": "What ___?"}, "ans": "What **did Jane buy yesterday**?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Ben buys a newspaper every morning.", "stem": "What ___?", "ans": "What **does Ben buy every morning**?"}, {"tag": "複數主詞＋過去式", "orig": "The kids ate fried chicken at the night market.", "stem": "What ___?", "ans": "What **did the kids eat at the night market**?"}, {"tag": "單數主詞＋未來式", "orig": "Mom will cook beef noodles tonight.", "stem": "What ___?", "ans": "What **will Mom cook tonight**?"}], "expl": ["句型：What + did/does/will + S + 原形V ...?", "問「買什麼」→ What 取代 a new dress，bought → did + buy。buys → does + buy；ate → did + eat；will cook → will Mom cook。", "易錯：寫成 What did Jane bought? 或 What Jane bought?"]}, {"id": "R078", "src": "模擬試題第3回 Q2", "q": {"orig": "Mark called at five this morning.", "stem": "Why ___ at five this morning?"}, "ans": "Why **did Mark call** at five this morning?", "variants": [{"tag": "複數主詞＋過去式", "orig": "The students left early yesterday.", "stem": "Why ___ early yesterday?", "ans": "Why **did the students leave** early yesterday?"}, {"tag": "第三人稱單數＋現在式", "orig": "Helen gets up at six every day.", "stem": "Why ___ at six every day?", "ans": "Why **does Helen get up** at six every day?"}, {"tag": "複數主詞＋未來式", "orig": "They will close the store at noon tomorrow.", "stem": "Why ___ at noon tomorrow?", "ans": "Why **will they close the store** at noon tomorrow?"}], "expl": ["句型：Why + did/does/do/will + S + 原形V…?", "called 是過去式 → 借 did，動詞還原 call。類似題：left → did … leave（不規則）；gets → does … get；will 移到主詞前。", "易錯：Why did Mark called（did 後原形）；Why Mark called（未加助動詞）。", "時間詞要配合時態：this morning（已過去）/ yesterday → did；every day → does；tomorrow → will。"]}]}, {"name": "Wh- 問句 (現在／未來)", "sets": [{"id": "R037", "src": "附件8 Q2", "q": {"orig": "Mr. Wang will leave for Japan next week.", "stem": "When ___ Japan?"}, "ans": "When **will Mr. Wang leave for** Japan?", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Ms. Lin left for Korea last month.", "stem": "When ___ Korea?", "ans": "When **did Ms. Lin leave for** Korea?"}, {"tag": "複數主詞＋現在式", "orig": "The Lees usually leave for Kenting in July.", "stem": "When ___ Kenting?", "ans": "When **do the Lees usually leave for** Kenting?"}, {"tag": "第一人稱→第二人稱＋be going to", "orig": "I am going to leave for Tainan tomorrow.", "stem": "When ___ Tainan?", "ans": "When **are you going to leave for** Tainan?"}], "expl": ["句型：When + will/did/do + S + 原形V + ...?", "問時間 → 去掉 next week，will 移到主詞前。left → did + leave；複數現在式 → do；I am going to → 問對方 are you going to。", "易錯：漏掉 for（leave for 前往），或寫成 When Mr. Wang will leave...。"]}, {"id": "R045", "src": "附件10 Q5", "q": {"orig": "I want to go to Italy next spring.", "stem": "Where ___ next spring?"}, "ans": "Where **do you want to go** next spring?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Amy wants to go to Japan this summer.", "stem": "Where ___ this summer?", "ans": "Where **does Amy want to go** this summer?"}, {"tag": "複數主詞＋過去式", "orig": "The Wangs wanted to go to Hualien last winter.", "stem": "Where ___ last winter?", "ans": "Where **did the Wangs want to go** last winter?"}, {"tag": "第三人稱單數＋未來式", "orig": "Tom will go to Kenting next weekend.", "stem": "Where ___ next weekend?", "ans": "Where **will Tom go** next weekend?"}], "expl": ["句型：Where + do/does/did/will + S + 原形V ...?", "問地點 → 去掉 to Italy；問對方 → I 改成 you，用 do。Amy → does + want；wanted → did + want；will go → will Tom go。", "易錯：寫成 Where do I want to go（人稱沒改），或 Where does Amy wants...。"]}, {"id": "R068", "src": "模擬試題第1回 Q2", "q": {"orig": "Michael will go to Japan next month.", "stem": "Where ___ next month?"}, "ans": "Where **will Michael go** next month?", "variants": [{"tag": "複數主詞＋be going to", "orig": "My cousins are going to travel to Tainan next week.", "stem": "Where ___ next week?", "ans": "Where **are my cousins going to travel** next week?"}, {"tag": "過去式", "orig": "Sandy went to Kenting last summer.", "stem": "Where ___ last summer?", "ans": "Where **did Sandy go** last summer?"}, {"tag": "第三人稱單數＋現在式", "orig": "Mr. Huang works in Taichung.", "stem": "Where ___?", "ans": "Where **does Mr. Huang work**?"}], "expl": ["句型：Wh- 問句：疑問詞 + 助動詞/be + S + V…?", "will 移到主詞前，go 用原形；to Japan 是被問的部分要刪掉。類似題：be going to 問句把 are 移前；過去式借 did、go 回原形；現在式單數借 does。", "易錯：Where Michael will go…（未倒裝）；Where did Sandy went（did 後要原形）。", "時間詞要配合時態：next month / next week → will 或 be going to；last summer → did；無時間詞的現況（works in Taichung）→ does。時間詞照抄在句尾。"]}, {"id": "R073", "src": "模擬試題第2回 Q2", "q": {"orig": "Amy is going to go camping this weekend.", "stem": "What ___ this weekend?"}, "ans": "What **is Amy going to do** this weekend?", "variants": [{"tag": "複數主詞＋be going to", "orig": "Her parents are going to go hiking this Sunday.", "stem": "What ___ this Sunday?", "ans": "What **are her parents going to do** this Sunday?"}, {"tag": "過去式", "orig": "Tim went fishing last weekend.", "stem": "What ___ last weekend?", "ans": "What **did Tim do** last weekend?"}, {"tag": "第三人稱單數＋現在式", "orig": "Joy plays the violin after school.", "stem": "What ___ after school?", "ans": "What **does Joy do** after school?"}], "expl": ["句型：What + be + S + going to do…? / What + did/does + S + do…?（問「做什麼」用 do）。", "go camping 是被問的活動 → 用 do 代替。類似題：複數 → are；過去式 → did + do；現在式單數 → does + do。", "易錯：What is Amy going to go…（要用 do）；What did Tim did（did 後原形 do）。", "時間詞要配合時態：this weekend / this Sunday（未來）→ be going to；last weekend → did；after school（習慣）→ does。"]}, {"id": "R083", "src": "模擬試題第4回 Q2", "q": {"orig": "Tom will meet us at the bank tomorrow.", "stem": "Where ___ us tomorrow?"}, "ans": "Where **will Tom meet** us tomorrow?", "variants": [{"tag": "複數主詞＋未來式", "orig": "Our friends will pick us up at the station tonight.", "stem": "Where ___ us up tonight?", "ans": "Where **will our friends pick** us up tonight?"}, {"tag": "過去式", "orig": "Linda met her friends at the MRT station yesterday.", "stem": "Where ___ her friends yesterday?", "ans": "Where **did Linda meet** her friends yesterday?"}, {"tag": "第三人稱單數＋現在式", "orig": "Mr. Chang meets his students in the library every Friday.", "stem": "Where ___ his students every Friday?", "ans": "Where **does Mr. Chang meet** his students every Friday?"}], "expl": ["句型：Where + will/did/does + S + 原形V…?（地點 at the bank 被問掉）。", "will 移到 Tom 前，meet 原形。類似題：met → did … meet；meets → does … meet；複數主詞未來式一樣 will + S。", "易錯：Where Tom will meet（未倒裝）；Where did Linda met。", "時間詞要配合時態：tomorrow / tonight → will；yesterday → did；every Friday → does。"]}, {"id": "R088", "src": "模擬試題第5回 Q2", "q": {"orig": "Nancy will study in the library next weekend.", "stem": "Where ___ next weekend?"}, "ans": "Where **will Nancy study** next weekend?", "variants": [{"tag": "複數主詞＋未來式", "orig": "Her friends will eat at the night market tonight.", "stem": "Where ___ tonight?", "ans": "Where **will her friends eat** tonight?"}, {"tag": "過去式", "orig": "Joe studied in the library last weekend.", "stem": "Where ___ last weekend?", "ans": "Where **did Joe study** last weekend?"}, {"tag": "複數主詞＋現在進行式", "orig": "The kids are playing in the park now.", "stem": "Where ___ now?", "ans": "Where **are the kids playing** now?"}], "expl": ["句型：Where + 助動詞/be + S + V…?（地點 in the library 被問掉）。", "will 移到 Nancy 前，study 原形。類似題：studied → did … study；進行式把 are 移前，playing 保留。", "易錯：Where Nancy will study；Where did Joe studied。", "時間詞要配合時態：next weekend / tonight → will；last weekend → did；now → are…playing。"]}, {"id": "R096", "src": "模擬試題第6回 Q5", "q": {"orig": "They exercise twice a week in the park.", "stem": "How often ___ in the park?"}, "ans": "How often **do they exercise** in the park?", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Ruby goes swimming three times a week at school.", "stem": "How often ___ at school?", "ans": "How often **does Ruby go swimming** at school?"}, {"tag": "複數主詞＋過去式", "orig": "The Lins visited Grandma once a month last year.", "stem": "How often ___ last year?", "ans": "How often **did the Lins visit Grandma** last year?"}, {"tag": "第三人稱單數＋未來式", "orig": "Ted will take the MRT twice a day next semester.", "stem": "How often ___ next semester?", "ans": "How often **will Ted take the MRT** next semester?"}], "expl": ["句型：How often + do/does/did/will + S + 原形V…?（問頻率，twice a week 被問掉）。", "They 複數現在式 → do they exercise。類似題：Ruby 單數 → does … go（goes 還原）；過去式 → did … visit；未來式 → will … take。", "易錯：How often they exercise（未加助動詞）；How often does Ruby goes。", "時間詞要配合時態：twice a week（現在習慣）→ do/does；last year → did；next semester → will。"]}]}]}, {"name": "主詞人稱與單複數改寫", "subs": [{"name": "主詞單複數與動詞一致", "sets": [{"id": "R006", "src": "附件2 Q1", "q": {"orig": "My teacher is from America.", "stem": "My teachers ___."}, "ans": "My teachers **are from America**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My friend was in Tainan last week.", "stem": "My friends ___.", "ans": "My friends **were in Tainan last week**."}, {"tag": "第一人稱→第三人稱單數", "orig": "I am from Kaohsiung.", "stem": "He ___.", "ans": "He **is from Kaohsiung**."}, {"tag": "複數主詞＋未來式", "orig": "My cousin will be at the night market tonight.", "stem": "My cousins ___.", "ans": "My cousins **will be at the night market tonight**."}], "expl": ["句型：S + be + from + 地方", "主詞 my teachers 為複數 → is 改 are。過去式複數 was → were；he 用 is；未來式 will be 不受人稱影響。", "易錯：寫成 My teachers is from America，主詞變複數 be 動詞忘了改。"]}, {"id": "R007", "src": "附件2 Q2", "q": {"orig": "Peter is a good student.", "stem": "Peter and Amy ___."}, "ans": "Peter and Amy **are good students**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The boy was a fast runner.", "stem": "The boys ___.", "ans": "The boys **were fast runners**."}, {"tag": "複數→第三人稱單數", "orig": "They are new teachers.", "stem": "Ms. Lin ___.", "ans": "Ms. Lin **is a new teacher**."}, {"tag": "第一人稱複數＋未來式", "orig": "I will be a nurse.", "stem": "My sister and I ___.", "ans": "My sister and I **will be nurses**."}], "expl": ["句型：S + be + (a) + adj + N", "主詞 Peter and Amy 是兩個人 → be 動詞用 are，補語名詞也要變複數 good students，並去掉 a。單數主詞則相反：is a new teacher。", "易錯：寫成 are a good students（a 與複數名詞不可並用）。"]}, {"id": "R008", "src": "附件2 Q3", "q": {"orig": "The students have a lot of homework.", "stem": "Johnny ___."}, "ans": "Johnny **has a lot of homework**.", "variants": [{"tag": "複數→第三人稱單數", "orig": "My classmates go to school by MRT.", "stem": "Mary ___.", "ans": "Mary **goes to school by MRT**."}, {"tag": "第一人稱複數→第三人稱單數", "orig": "We watch TV after dinner.", "stem": "My brother ___.", "ans": "My brother **watches TV after dinner**."}, {"tag": "複數→第三人稱單數＋否定句", "orig": "The children don't eat breakfast at home.", "stem": "Tim ___.", "ans": "Tim **doesn't eat breakfast at home**."}], "expl": ["句型：第三人稱單數現在式 → 動詞 + s/es（have → has）", "主詞 Johnny 為第三人稱單數 → have 改 has。go → goes、watch → watches；否定句 don't → doesn't，後面動詞維持原形 eat。", "易錯：寫成 Johnny have，或寫成 Tim doesn't eats。"]}, {"id": "R094", "src": "模擬試題第6回 Q3", "q": {"orig": "The man is laughing, and so is the woman.", "stem": "___ the man and the woman are laughing."}, "ans": "**Both** the man and the woman are laughing.", "variants": [{"tag": "過去式", "orig": "Tom was late, and so was Amy.", "stem": "___ Tom and Amy were late.", "ans": "**Both** Tom and Amy were late."}, {"tag": "一般動詞現在式", "orig": "My dad likes stinky tofu, and so does my mom.", "stem": "___ my dad and my mom like stinky tofu.", "ans": "**Both** my dad and my mom like stinky tofu."}, {"tag": "未來式", "orig": "Kevin will join the club, and so will his sister.", "stem": "___ Kevin and his sister will join the club.", "ans": "**Both** Kevin and his sister will join the club."}], "expl": ["句型：A …, and so + be/助動詞 + B ＝ Both A and B + 複數動詞。", "Both A and B 視為複數主詞 → are laughing。類似題：was → were；likes → like（複數不加 s）；未來式 will 不變。", "易錯：Both the man and the woman is laughing（要用複數動詞）；用 Either（意思不同）。", "時間詞要配合時態：本題無時間詞，Both A and B 後的動詞時態照原句（are / were / like / will join）。"]}]}, {"name": "所有格代名詞 hers／mine", "sets": [{"id": "R093", "src": "模擬試題第6回 Q2", "q": {"orig": "These are her toys.", "stem": "These toys are ___."}, "ans": "These toys are **hers**.", "variants": [{"tag": "第三人稱單數（男）", "orig": "This is his bike.", "stem": "This bike is ___.", "ans": "This bike is **his**."}, {"tag": "第三人稱複數＋過去式", "orig": "Those were their books.", "stem": "Those books were ___.", "ans": "Those books were **theirs**."}, {"tag": "第一人稱複數", "orig": "That is our classroom.", "stem": "That classroom is ___.", "ans": "That classroom is **ours**."}], "expl": ["句型：所有格 + N ＝ 所有格代名詞（mine / yours / his / hers / ours / theirs）。", "her toys → hers（her + s，不加撇號）。類似題：his 不變；their → theirs；our → ours；be 動詞依主詞單複數與時態（is / were）。", "易錯：her's / their's（所有格代名詞沒有 's）；These toys are her（缺 s）。", "時間詞要配合時態：本題無時間詞，be 動詞照原句時態（are / is / were）。"]}]}]}, {"name": "被動語態", "subs": [{"name": "過去式被動 was/were + Vpp", "sets": [{"id": "R012", "src": "附件3 Q2", "q": {"orig": "Jeff broke the vase.", "stem": "The vase ___."}, "ans": "The vase **was broken by Jeff**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The kids broke the windows.", "stem": "The windows ___.", "ans": "The windows **were broken by the kids**."}, {"tag": "第三人稱單數＋現在式", "orig": "Mom cleans the kitchen every day.", "stem": "The kitchen ___.", "ans": "The kitchen **is cleaned by Mom every day**."}, {"tag": "複數主詞＋未來式", "orig": "Mr. Chen will fix the bikes.", "stem": "The bikes ___.", "ans": "The bikes **will be fixed by Mr. Chen**."}], "expl": ["句型：S + be + Vpp + by + O（被動語態）", "過去式、主詞 the vase 單數 → was broken。break-broke-broken。類似題：the windows 複數 → were；現在式 → is cleaned；未來式 → will be fixed。", "易錯：寫成 was broke（要用過去分詞 broken）。"]}, {"id": "R020", "src": "附件4 Q5", "q": {"orig": "My grandfather built this house in 1955.", "stem": "This house ___."}, "ans": "This house **was built by my grandfather in 1955**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The workers built these bridges in 2010.", "stem": "These bridges ___.", "ans": "These bridges **were built by the workers in 2010**."}, {"tag": "單數主詞＋現在式", "orig": "Mrs. Lee cooks dinner every evening.", "stem": "Dinner ___.", "ans": "Dinner **is cooked by Mrs. Lee every evening**."}, {"tag": "複數主詞＋未來式", "orig": "The students will plant the trees next week.", "stem": "The trees ___.", "ans": "The trees **will be planted by the students next week**."}], "expl": ["句型：S + be + Vpp + by + O + 時間", "過去式、this house 單數 → was built（build-built-built）。these bridges 複數 → were；現在式 → is cooked；未來式 → will be planted。", "易錯：漏掉 be 動詞寫成 This house built by...。"]}, {"id": "R029", "src": "附件6 Q4", "q": {"orig": "My father sang the famous song.", "stem": "The famous song ___ by my father."}, "ans": "The famous song **was sung** by my father.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My mom wrote these letters.", "stem": "These letters ___ by my mom.", "ans": "These letters **were written** by my mom."}, {"tag": "第三人稱單數＋現在式", "orig": "Ken washes the car every Sunday.", "stem": "The car ___ by Ken every Sunday.", "ans": "The car **is washed** by Ken every Sunday."}, {"tag": "單數主詞＋未來式", "orig": "Amy will sing the song tomorrow.", "stem": "The song ___ by Amy tomorrow.", "ans": "The song **will be sung** by Amy tomorrow."}], "expl": ["句型：S + be + Vpp + by + O", "sing-sang-sung → 過去式被動 was sung。these letters 複數 → were written；現在式 → is washed；未來式 → will be sung。", "易錯：寫成 was sang（被動要用過去分詞）。"]}, {"id": "R035", "src": "附件7 Q5", "q": {"orig": "The thief stole the man's wallet and phone.", "stem": "The man's wallet and phone ___."}, "ans": "The man's wallet and phone **were stolen by the thief**.", "variants": [{"tag": "單數主詞＋過去式", "orig": "The dog ate my sandwich.", "stem": "My sandwich ___.", "ans": "My sandwich **was eaten by the dog**."}, {"tag": "複數主詞＋現在式", "orig": "The students clean the classrooms every afternoon.", "stem": "The classrooms ___.", "ans": "The classrooms **are cleaned by the students every afternoon**."}, {"tag": "複數主詞＋未來式", "orig": "Workers will repair the roads after the typhoon.", "stem": "The roads ___.", "ans": "The roads **will be repaired by workers after the typhoon**."}], "expl": ["句型：S + be + Vpp + by + O", "wallet and phone 兩樣東西 → 複數 were；steal-stole-stolen。my sandwich 單數 → was eaten；現在式 → are cleaned；未來式 → will be repaired。", "易錯：寫成 was stolen（忽略 and 連接成複數主詞）或 were stole。"]}, {"id": "R040", "src": "附件8 Q5", "q": {"orig": "A writer called John Grisham wrote this book.", "stem": "This book was ___ John Grisham."}, "ans": "This book was **written by a writer called** John Grisham.", "variants": [{"tag": "複數主詞＋過去式", "orig": "An artist called Mr. Lin drew these pictures.", "stem": "These pictures were ___ Mr. Lin.", "ans": "These pictures were **drawn by an artist called** Mr. Lin."}, {"tag": "複數主詞＋現在式", "orig": "A cook called Ah-Ming makes the beef noodles here.", "stem": "The beef noodles here are ___ Ah-Ming.", "ans": "The beef noodles here are **made by a cook called** Ah-Ming."}, {"tag": "單數主詞＋未來式", "orig": "A singer called Jay will sing the theme song.", "stem": "The theme song will be ___ Jay.", "ans": "The theme song will be **sung by a singer called** Jay."}], "expl": ["句型：S + be + Vpp + by + O（O = a writer called ...）", "write-wrote-written；by 後接完整的行為者 a writer called John Grisham。draw → drawn；make → made；sing → sung。", "易錯：寫成 was wrote，或漏掉 a writer called。"]}, {"id": "R046", "src": "附件10 Q1", "q": {"orig": "My mom made this cake yesterday.", "stem": "This cake ___."}, "ans": "This cake **was made by my mom yesterday**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My dad made these cookies last night.", "stem": "These cookies ___.", "ans": "These cookies **were made by my dad last night**."}, {"tag": "複數主詞＋現在式", "orig": "Grandma makes the dumplings every New Year.", "stem": "The dumplings ___.", "ans": "The dumplings **are made by Grandma every New Year**."}, {"tag": "單數主詞＋未來式", "orig": "My sister will make the salad tomorrow.", "stem": "The salad ___.", "ans": "The salad **will be made by my sister tomorrow**."}], "expl": ["句型：S + be + Vpp + by + O + 時間", "this cake 單數、過去式 → was made。these cookies → were；現在式複數 → are made；未來式 → will be made。", "易錯：寫成 This cake made by my mom（漏 be 動詞）。"]}, {"id": "R084", "src": "模擬試題第4回 Q3", "q": {"orig": "Lisa drew the picture on the wall.", "stem": "The picture on the wall ___ by Lisa."}, "ans": "The picture on the wall **was drawn** by Lisa.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The students drew these pictures.", "stem": "These pictures ___ by the students.", "ans": "These pictures **were drawn** by the students."}, {"tag": "現在簡單式", "orig": "Mom makes our lunch every day.", "stem": "Our lunch ___ by Mom every day.", "ans": "Our lunch **is made** by Mom every day."}, {"tag": "未來式", "orig": "Mr. Wang will write the letter tomorrow.", "stem": "The letter ___ by Mr. Wang tomorrow.", "ans": "The letter **will be written** by Mr. Wang tomorrow."}], "expl": ["句型：S + be + Vpp + by + O。", "drew 是過去式，主詞 the picture 單數 → was drawn（draw-drew-drawn）。類似題：these pictures 複數 → were；現在式單數 → is made；未來式 → will be written。", "易錯：was drew（要用過去分詞）；These pictures was drawn（複數要用 were）。", "時間詞要配合時態：every day → is/are + Vpp；tomorrow → will be + Vpp；過去事件 → was/were + Vpp。"]}, {"id": "R090", "src": "模擬試題第5回 Q4", "q": {"orig": "A midnight phone call bothered my parents.", "stem": "My parents ___ by a midnight phone call."}, "ans": "My parents **were bothered** by a midnight phone call.", "variants": [{"tag": "單數主詞＋過去式", "orig": "The loud music bothered my grandma.", "stem": "My grandma ___ by the loud music.", "ans": "My grandma **was bothered** by the loud music."}, {"tag": "現在簡單式", "orig": "Many tourists visit the night market every day.", "stem": "The night market ___ by many tourists every day.", "ans": "The night market **is visited** by many tourists every day."}, {"tag": "未來式", "orig": "The teacher will check our homework tomorrow.", "stem": "Our homework ___ by the teacher tomorrow.", "ans": "Our homework **will be checked** by the teacher tomorrow."}], "expl": ["句型：S + be + Vpp + by + O。", "bothered 是過去式，主詞 My parents 複數 → were bothered。類似題：my grandma 單數 → was；現在式單數 → is visited；未來式 → will be checked。", "易錯：My parents was bothered（複數用 were）；will be check（要用過去分詞）。", "時間詞要配合時態：every day → is + Vpp；tomorrow → will be + Vpp；過去事件 → was/were + Vpp。"]}, {"id": "R095", "src": "模擬試題第6回 Q4", "q": {"orig": "A famous artist painted the pictures.", "stem": "The pictures ___ by a famous artist."}, "ans": "The pictures **were painted** by a famous artist.", "variants": [{"tag": "單數主詞＋過去式", "orig": "My uncle built the house.", "stem": "The house ___ by my uncle.", "ans": "The house **was built** by my uncle."}, {"tag": "現在簡單式", "orig": "Kids love the cartoon.", "stem": "The cartoon ___ by kids.", "ans": "The cartoon **is loved** by kids."}, {"tag": "複數主詞＋未來式", "orig": "The workers will fix the roads next week.", "stem": "The roads ___ by the workers next week.", "ans": "The roads **will be fixed** by the workers next week."}], "expl": ["句型：S + be + Vpp + by + O。", "painted 是過去式，主詞 The pictures 複數 → were painted。類似題：The house 單數 → was built（build-built-built）；現在式單數 → is loved；未來式 → will be fixed。", "易錯：The pictures was painted；were paint（要用過去分詞）。", "時間詞要配合時態：next week → will be fixed；無時間詞的過去事件 → was/were；現在式（love）→ is loved。"]}]}, {"name": "現在式被動 is/are + Vpp", "sets": [{"id": "R015", "src": "附件3 Q5", "q": {"orig": "Everybody in this town knows the museum.", "stem": "The museum ___."}, "ans": "The museum **is known to everybody in this town**.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Everyone in the school knew the old teacher.", "stem": "The old teacher ___.", "ans": "The old teacher **was known to everyone in the school**."}, {"tag": "複數主詞＋現在式", "orig": "All the students know these songs.", "stem": "These songs ___.", "ans": "These songs **are known to all the students**."}, {"tag": "單數主詞＋未來式", "orig": "Everyone will know the news soon.", "stem": "The news ___.", "ans": "The news **will be known to everyone soon**."}], "expl": ["句型：S + be + known to + 人（為…所熟知）", "know 的被動常用 be known to，不用 by。現在式單數 → is known；過去式 → was；複數 → are；未來式 → will be known。", "易錯：寫成 is knew 或 is know（要用過去分詞 known）。"]}]}, {"name": "被動疑問句 Was + S + Vpp", "sets": [{"id": "R058", "src": "附件17 Q2", "q": {"orig": "The car was driven by my dad's friend.", "stem": "Was ___ by my dad's friend?"}, "ans": "Was **the car driven** by my dad's friend?", "variants": [{"tag": "複數主詞＋過去式", "orig": "The cookies were made by my grandma.", "stem": "Were ___ by my grandma?", "ans": "Were **the cookies made** by my grandma?"}, {"tag": "現在簡單式", "orig": "The classroom is cleaned by the students every day.", "stem": "Is ___ by the students every day?", "ans": "Is **the classroom cleaned** by the students every day?"}, {"tag": "複數主詞＋未來式", "orig": "The letters will be sent by Mr. Lee tomorrow.", "stem": "Will ___ by Mr. Lee tomorrow?", "ans": "Will **the letters be sent** by Mr. Lee tomorrow?"}], "expl": ["句型：被動語態 Yes/No 問句：Be + S + Vpp + by + O?；未來式：Will + S + be + Vpp + by + O?", "把 was 移到句首，主詞 the car 放 be 之後，過去分詞 driven 跟著主詞。類似題：複數 cookies → Were；現在式單數 → Is；未來式 will 移到句首、be 留在主詞後。", "易錯：Was driven the car...（主詞要放在 be 與 Vpp 中間）；Will the letters are sent（will 後要用 be）。", "時間詞要配合時態：every day → 現在式 Is…cleaned；tomorrow → Will…be sent；無時間詞的過去事件 → Was/Were。時間詞照抄在句尾。"]}]}]}, {"name": "間接問句與直接／間接引述", "subs": [{"name": "間接問句 疑問詞 + S + V", "sets": [{"id": "R018", "src": "附件4 Q3", "q": {"orig": "Why did Jack do this?", "stem": "I don't know ___."}, "ans": "I don't know **why Jack did this**.", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Where does Kelly live?", "stem": "I don't know ___.", "ans": "I don't know **where Kelly lives**."}, {"tag": "複數主詞＋過去式", "orig": "What did the boys eat?", "stem": "I don't know ___.", "ans": "I don't know **what the boys ate**."}, {"tag": "單數主詞＋未來式", "orig": "When will the typhoon come?", "stem": "I don't know ___.", "ans": "I don't know **when the typhoon will come**."}], "expl": ["句型：I don't know + 疑問詞 + S + V（間接問句用直述句語序）", "去掉助動詞 did，動詞改過去式 → why Jack did this。does 去掉 → lives；will 移到主詞後 → the typhoon will come。", "易錯：寫成 I don't know why did Jack do this（間接問句不可倒裝）。"]}, {"id": "R024", "src": "附件5 Q4", "q": {"orig": "What does the food taste like?", "stem": "I would like to know ___."}, "ans": "I would like to know **what the food tastes like**.", "variants": [{"tag": "單數主詞＋過去式", "orig": "What did the house look like?", "stem": "I would like to know ___.", "ans": "I would like to know **what the house looked like**."}, {"tag": "複數主詞＋現在式", "orig": "What do the new students look like?", "stem": "I would like to know ___.", "ans": "I would like to know **what the new students look like**."}, {"tag": "單數主詞＋未來式", "orig": "What will the weather be like tomorrow?", "stem": "I would like to know ___.", "ans": "I would like to know **what the weather will be like tomorrow**."}], "expl": ["句型：I would like to know + 疑問詞 + S + V（直述句語序）", "去掉 does，the food 第三人稱單數現在式 → tastes。did → 動詞改過去式 looked；do + 複數主詞 → look；will 放主詞後。", "易錯：寫成 what does the food taste like（間接問句不可保留問句語序）。"]}, {"id": "R049", "src": "附件10 Q4", "q": {"orig": "Why did Susan cry?", "stem": "I don't know ___."}, "ans": "I don't know **why Susan cried**.", "variants": [{"tag": "現在式＋第三人稱單數", "orig": "Where does Kevin live?", "stem": "I don't know ___.", "ans": "I don't know **where Kevin lives**."}, {"tag": "複數主詞＋過去式", "orig": "When did the twins get home?", "stem": "I don't know ___.", "ans": "I don't know **when the twins got home**."}, {"tag": "未來式＋第一人稱複數", "orig": "What will we eat at the night market?", "stem": "I don't know ___.", "ans": "I don't know **what we will eat at the night market**."}], "expl": ["句型：S + know + 疑問詞 + S + V（間接問句用直述句語序）。", "原句 did 要拿掉，動詞改回過去式 cry → cried。類似題：does live → lives（第三人稱單數加 s）；did get → got；will 放回主詞後面 we will eat。", "易錯：不可寫成 I don't know why did Susan cry.（間接問句不倒裝、不留助動詞 do/does/did）。", "時間詞：本題原句無時間詞，時態看助動詞：does → 現在式、did → 過去式、will → 未來式；若原句有時間詞（如 yesterday），要照抄到間接問句裡，時態不變。"]}, {"id": "R064", "src": "附件19 Q3", "q": {"orig": "How much does this watch cost?", "stem": "The man wants to know ___."}, "ans": "The man wants to know **how much this watch costs**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "How much do these shoes cost?", "stem": "The woman wants to know ___.", "ans": "The woman wants to know **how much these shoes cost**."}, {"tag": "過去式", "orig": "How much did the bike cost?", "stem": "My sister wants to know ___.", "ans": "My sister wants to know **how much the bike cost**."}, {"tag": "未來式", "orig": "When will the train arrive?", "stem": "The students want to know ___.", "ans": "The students want to know **when the train will arrive**."}], "expl": ["句型：S + want to know + 疑問詞 + S + V（間接問句用直述句語序）。", "拿掉 does，this watch 是單數 → costs 加 s。類似題：these shoes 複數 → cost；did 拿掉後改過去式 cost（cost 三態同形）；will 放回主詞後。", "易錯：how much does this watch cost（不可倒裝）；how much this watch cost（現在式單數漏 s）。", "時間詞要配合時態：本題無時間詞，時態看原句助動詞：does/do → 現在式、did → 過去式、will → will + 原形。"]}, {"id": "R076", "src": "模擬試題第2回 Q5", "q": {"orig": "Where does he live?", "stem": "Do you know where ___?"}, "ans": "Do you know where **he lives**?", "variants": [{"tag": "複數主詞＋現在式", "orig": "Where do they work?", "stem": "Do you know where ___?", "ans": "Do you know where **they work**?"}, {"tag": "過去式", "orig": "Where did she go yesterday?", "stem": "Do you know where ___?", "ans": "Do you know where **she went yesterday**?"}, {"tag": "第一人稱複數＋未來式", "orig": "Where will we meet tomorrow?", "stem": "Do you know where ___?", "ans": "Do you know where **we will meet tomorrow**?"}], "expl": ["句型：Do you know + 疑問詞 + S + V?（間接問句用直述句語序）。", "拿掉 does，he 第三人稱單數 → lives。類似題：they → work（不加 s）；did 拿掉改過去式 went；will 放到主詞後 we will meet。", "易錯：Do you know where does he live?（不可倒裝）；where he live（漏 s）。", "時間詞要配合時態：yesterday → 過去式 went；tomorrow → will meet；時間詞照抄到間接問句句尾。"]}, {"id": "R081", "src": "模擬試題第3回 Q5", "q": {"orig": "What does he need?", "stem": "Tell me what ___."}, "ans": "Tell me what **he needs**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "What do they want?", "stem": "Tell me what ___.", "ans": "Tell me what **they want**."}, {"tag": "過去式", "orig": "What did she buy at the night market?", "stem": "Tell me what ___.", "ans": "Tell me what **she bought at the night market**."}, {"tag": "未來式", "orig": "What will you do this weekend?", "stem": "Tell me what ___.", "ans": "Tell me what **you will do this weekend**."}], "expl": ["句型：Tell me + 疑問詞 + S + V（間接問句用直述句語序）。", "拿掉 does，he → needs。類似題：they → want；did 拿掉改過去式 bought；will 放回主詞後。", "易錯：Tell me what does he need.（不可倒裝）；what he need（漏 s）。", "時間詞要配合時態：did → 過去式 bought；this weekend（未來）→ will do；時間詞照抄。"]}]}, {"name": "Yes/No 引述 asked (if)", "sets": [{"id": "R043", "src": "附件10 Q3", "q": {"orig": "The teacher asked the students if they understood the assignment.", "stem": "The teacher asked the students, \"___?\""}, "ans": "The teacher asked the students, \"**Do you understand the assignment**?\"", "variants": [{"tag": "第一人稱受詞＋be 動詞", "orig": "Mom asked me if I was hungry.", "stem": "Mom asked me, \"___?\"", "ans": "Mom asked me, \"**Are you hungry**?\""}, {"tag": "第三人稱單數＋一般動詞", "orig": "Ken asked Amy if she liked bubble tea.", "stem": "Ken asked Amy, \"___?\"", "ans": "Ken asked Amy, \"**Do you like bubble tea**?\""}, {"tag": "複數受詞＋未來式", "orig": "The coach asked the players if they would come to practice.", "stem": "The coach asked the players, \"___?\"", "ans": "The coach asked the players, \"**Will you come to practice**?\""}], "expl": ["句型：S asked + 人 + if + S + V（過去式）＝ S asked + 人, \"Yes/No 問句?\"", "原題 understand 已改為 understood（asked 是過去式，間接引述要退一格）；改直接引述時 they → you，時態退回現在 → Do you understand ...?", "類似題：was → Are you；liked → Do you like；would → Will you。易錯：寫成 Do they understand（人稱沒改回 you）。"]}, {"id": "R071", "src": "模擬試題第1回 Q5", "q": {"orig": "Lisa asked me, \"Could you water my plants?\"", "stem": "Lisa asked me if ___ water her plants."}, "ans": "Lisa asked me if **I could** water her plants.", "variants": [{"tag": "第一人稱複數＋過去式", "orig": "My brother asked us, \"Can you help me with my homework?\"", "stem": "My brother asked us if ___ help him with his homework.", "ans": "My brother asked us if **we could** help him with his homework."}, {"tag": "第三人稱單數＋現在式", "orig": "Mom asks Tom, \"Will you clean your room?\"", "stem": "Mom asks Tom if ___ clean his room.", "ans": "Mom asks Tom if **he will** clean his room."}, {"tag": "複數受詞＋過去式", "orig": "The teacher asked the students, \"Can you finish the test?\"", "stem": "The teacher asked the students if ___ finish the test.", "ans": "The teacher asked the students if **they could** finish the test."}], "expl": ["句型：S + asked + 人 + if + S + V（Yes/No 問句的間接引述，用直述句語序）。", "you 指「我」→ 改 I；could 放在主詞後；my → her。類似題：you 指 us → we；can 因 asked 過去式改 could；主要動詞是現在式 asks 時不必改時態 → he will。", "易錯：if could I water（不可倒裝）；人稱沒跟著改（if you could）。", "時間詞要配合時態：主要動詞 asked（過去）→ can 改 could；asks（現在）→ will 不必改。"]}]}]}, {"name": "比較級・最高級・同級比較", "subs": [{"name": "比較級 -er／more than", "sets": [{"id": "R011", "src": "附件3 Q1", "q": {"orig": "Rebecca is not so old as she looks.（用younger）", "stem": "___."}, "ans": "**Rebecca is younger than she looks**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "My grandparents were not so old as they looked.（用younger）", "stem": "___.", "ans": "**My grandparents were younger than they looked**."}, {"tag": "第一人稱＋現在式", "orig": "I am not so tall as my brother.（用shorter）", "stem": "___.", "ans": "**I am shorter than my brother**."}, {"tag": "第三人稱單數＋過去式", "orig": "This bag was not so expensive as that one.（用cheaper）", "stem": "___.", "ans": "**This bag was cheaper than that one**."}], "expl": ["句型：A + be + not so/as + adj + as B ＝ A + be + 相反詞比較級 + than B", "not so old as（沒那麼老）＝ younger than（比較年輕）；she looks 照抄。類似題的 be 動詞與 look 的時態要跟原句一致（were / looked）。", "易錯：寫成 younger as she looks 或 more younger。"]}, {"id": "R019", "src": "附件4 Q4", "q": {"orig": "Ray is not as tall as Mark.", "stem": "___ taller ___."}, "ans": "**Mark is** taller **than Ray**.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "My sister was not as tall as my cousin last year.", "stem": "___ taller ___ last year.", "ans": "**My cousin was** taller **than my sister** last year."}, {"tag": "複數主詞＋現在式", "orig": "The boys are not as strong as the girls.", "stem": "___ stronger ___.", "ans": "**The girls are** stronger **than the boys**."}, {"tag": "第一人稱＋一般動詞", "orig": "I don't run as fast as Kevin.", "stem": "___ faster ___.", "ans": "**Kevin runs** faster **than I do**."}], "expl": ["句型：A + not as + adj + as B ＝ B + 比較級 + than A", "Ray 沒有 Mark 高 → Mark 比 Ray 高，主詞要對調。be 動詞跟著新主詞與時態：was（last year 過去式）/ are；一般動詞 Kevin → runs，句尾 than I do。", "易錯：主詞沒對調寫成 Ray is taller than Mark，意思完全相反。"]}, {"id": "R048", "src": "附件10 Q3", "q": {"orig": "Tom is not as handsome as Peter.", "stem": "___ more handsome ___."}, "ans": "**Peter is** more handsome **than Tom**.", "variants": [{"tag": "單數主詞＋過去式", "orig": "This movie was not as interesting as the book.", "stem": "___ more interesting ___.", "ans": "**The book was** more interesting **than this movie**."}, {"tag": "複數主詞＋現在式", "orig": "These questions are not as difficult as those questions.", "stem": "___ more difficult ___.", "ans": "**Those questions are** more difficult **than these questions**."}, {"tag": "單數主詞＋未來式", "orig": "The bus will not be as expensive as the taxi.", "stem": "___ more expensive ___.", "ans": "**The taxi will be** more expensive **than the bus**."}], "expl": ["句型：A + not as + adj + as B ＝ B + more + adj + than A", "Tom 沒有 Peter 帥 → Peter 比 Tom 帥，主詞對調。be 動詞隨新主詞與時態：was / are / will be。", "易錯：主詞沒對調，或寫成 more handsomer。"]}, {"id": "R080", "src": "模擬試題第3回 Q4", "q": {"orig": "Ann doesn't drive as carefully as her husband.", "stem": "Ann's husband drives ___ than Ann."}, "ans": "Ann's husband drives **more carefully** than Ann.", "variants": [{"tag": "過去式", "orig": "Tom didn't run as fast as his brother.", "stem": "Tom's brother ran ___ than Tom.", "ans": "Tom's brother ran **faster** than Tom."}, {"tag": "複數主詞", "orig": "The boys don't sing as well as the girls.", "stem": "The girls sing ___ than the boys.", "ans": "The girls sing **better** than the boys."}, {"tag": "未來式", "orig": "Kevin won't finish the test as quickly as Amy.", "stem": "Amy will finish the test ___ than Kevin.", "ans": "Amy will finish the test **more quickly** than Kevin."}], "expl": ["句型：A not + V + as + adv. + as B ＝ B + V + 比較級副詞 + than A。", "carefully 是 -ly 副詞 → more carefully。類似題：fast → faster；well → better（不規則）；quickly → more quickly。", "易錯：more careful（修飾動詞要用副詞）；carefullier、more faster（比較級寫法錯誤）。", "時間詞要配合時態：本題時態照原句助動詞：doesn't/don't → 現在式；didn't → 過去式 ran；won't → will。"]}]}, {"name": "同級 as…as／different", "sets": [{"id": "R030", "src": "附件6 Q5", "q": {"orig": "Harry's jacket and Ron's are not the same.", "stem": "Harry's jacket ___ from Ron's."}, "ans": "Harry's jacket **is different** from Ron's.", "variants": [{"tag": "複數主詞＋現在式", "orig": "My shoes and Amy's are not the same.", "stem": "My shoes ___ from Amy's.", "ans": "My shoes **are different** from Amy's."}, {"tag": "單數主詞＋過去式", "orig": "Ben's answer and mine were not the same.", "stem": "Ben's answer ___ from mine.", "ans": "Ben's answer **was different** from mine."}, {"tag": "單數主詞＋未來式", "orig": "Next year's school trip and this year's will not be the same.", "stem": "Next year's school trip ___ from this year's.", "ans": "Next year's school trip **will be different** from this year's."}], "expl": ["句型：A and B are not the same ＝ A + be + different from + B", "新主詞只有 Harry's jacket（單數）→ is different。my shoes 複數 → are；過去式 → was；未來式 → will be。", "易錯：沿用原句的 are，或寫成 is difference from（要用形容詞 different）。"]}, {"id": "R061", "src": "附件17 Q5", "q": {"orig": "Betsy is trying as hard as she can to answer the question.", "stem": "Betsy is trying ___ possible to answer the question."}, "ans": "Betsy is trying **as hard as** possible to answer the question.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The students ran as fast as they could to catch the bus.", "stem": "The students ran ___ possible to catch the bus.", "ans": "The students ran **as fast as** possible to catch the bus."}, {"tag": "第一人稱＋未來式", "orig": "I will study as hard as I can for the exam.", "stem": "I will study ___ possible for the exam.", "ans": "I will study **as hard as** possible for the exam."}, {"tag": "第三人稱單數＋現在式", "orig": "Tom always speaks as slowly as he can in English class.", "stem": "Tom always speaks ___ possible in English class.", "ans": "Tom always speaks **as slowly as** possible in English class."}], "expl": ["句型：as + 原級 + as + S + can/could ＝ as + 原級 + as possible（盡可能地…）。", "as she can 改成 as possible，前面 as hard as 保留。類似題：過去式原句用 could，改寫後一樣是 as possible；修飾動詞 speaks 要用副詞 slowly。", "易錯：as hard as she possible（不需再加主詞）；as slow as possible（修飾動詞要用副詞）。", "時間詞要配合時態：always → 現在簡單式 speaks；未來 will study；過去 ran。as…as possible 本身不隨時態改變。"]}, {"id": "R086", "src": "模擬試題第4回 Q5", "q": {"orig": "Your sweater and my sweater are not the same.", "stem": "Your sweater ___ from mine."}, "ans": "Your sweater **is different** from mine.", "variants": [{"tag": "複數主詞", "orig": "Her shoes and my shoes are not the same.", "stem": "Her shoes ___ from mine.", "ans": "Her shoes **are different** from mine."}, {"tag": "過去式", "orig": "His idea and our idea were not the same.", "stem": "His idea ___ from ours.", "ans": "His idea **was different** from ours."}, {"tag": "第三人稱所有格名詞", "orig": "Tom's answer and Ken's answer are not the same.", "stem": "Tom's answer ___ from Ken's.", "ans": "Tom's answer **is different** from Ken's."}], "expl": ["句型：A and B are not the same ＝ A + be + different from + B。", "主詞只剩 Your sweater（單數）→ is different；mine ＝ my sweater。類似題：Her shoes 複數 → are；過去式 → was；ours ＝ our idea、Ken's ＝ Ken's answer。", "易錯：Your sweater are different（主詞已變單數）；different than / different to（考試用 different from）。", "時間詞要配合時態：本題無時間詞，be 動詞照原句時態（are not → is/are；were not → was）。"]}]}, {"name": "最高級與 No other", "sets": [{"id": "R044", "src": "附件10 Q4", "q": {"orig": "Richard is faster than any other runner in the contest.", "stem": "Richard ___ the fastest ___ in the contest."}, "ans": "Richard **is** the fastest **runner** in the contest.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Amy was taller than any other girl in her class.", "stem": "Amy ___ the tallest ___ in her class.", "ans": "Amy **was** the tallest **girl** in her class."}, {"tag": "複數主詞＋現在式", "orig": "These two boys are taller than any other boy in the class.", "stem": "These two boys ___ the tallest ___ in the class.", "ans": "These two boys **are** the tallest **boys** in the class."}, {"tag": "單數主詞＋未來式", "orig": "This new MRT station will be bigger than any other station in the city.", "stem": "This new MRT station ___ the biggest ___ in the city.", "ans": "This new MRT station **will be** the biggest **station** in the city."}], "expl": ["句型：A + 比較級 + than any other + 單數N ＝ A + the + 最高級 + N", "Richard is faster than any other runner → Richard is the fastest runner。be 動詞照原句時態：was / are / will be；主詞 these two boys 複數 → the tallest boys；big → biggest（重複字尾 g）。", "易錯：any other 後誤用複數 runners；最高級前漏掉 the。"]}, {"id": "R060", "src": "附件17 Q4", "q": {"orig": "Jack is the best player on the team.", "stem": "No other player is as ___ on the team."}, "ans": "No other player is as **good as Jack** on the team.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Linda was the tallest girl in the class.", "stem": "No other girl was as ___ in the class.", "ans": "No other girl was as **tall as Linda** in the class."}, {"tag": "複數主詞", "orig": "My brothers are the fastest runners at our school.", "stem": "No other runners are as ___ at our school.", "ans": "No other runners are as **fast as my brothers** at our school."}, {"tag": "多音節形容詞（most → as…as）", "orig": "Grandpa's noodle shop is the most popular shop on this street.", "stem": "No other shop is as ___ on this street.", "ans": "No other shop is as **popular as Grandpa's noodle shop** on this street."}], "expl": ["句型：S + is the 最高級 ＝ No other + N + is as + 原級 + as + S。", "best 的原級是 good，所以寫 as good as Jack。類似題：過去式用 was；複數 runners → are；most popular 改回原級 popular。", "易錯：as best as / as better as（as…as 中間只能用原級）。", "時間詞要配合時態：本題無時間詞，be 動詞時態照原句（is / was / are）。"]}, {"id": "R070", "src": "模擬試題第1回 Q4", "q": {"orig": "Jane is more beautiful than all the other girls in her class.", "stem": "Jane ___ most beautiful ___ in her class."}, "ans": "Jane **is the** most beautiful **girl** in her class.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Mr. Lee was more popular than all the other teachers in our school.", "stem": "Mr. Lee ___ most popular ___ in our school.", "ans": "Mr. Lee **was the** most popular **teacher** in our school."}, {"tag": "複數主詞", "orig": "These shoes are more expensive than all the other shoes in the store.", "stem": "These shoes ___ most expensive ___ in the store.", "ans": "These shoes **are the** most expensive **shoes** in the store."}, {"tag": "未來式", "orig": "This test will be more difficult than all the other tests this year.", "stem": "This test ___ most difficult ___ this year.", "ans": "This test **will be the** most difficult **test** this year."}], "expl": ["句型：比較級 + than all the other + 複數N ＝ the + 最高級 + 單數N（範圍內）。", "最高級前要加 the，後面名詞用單數 girl（Jane 只有一個人）。類似題：過去式 was the；複數主詞 are the … shoes（名詞跟主詞一致）；未來式 will be the。", "易錯：Jane is most beautiful girls（漏 the；名詞誤用複數）。", "時間詞要配合時態：this year 搭配 will be 表未來；原句 was → 過去式 was the；現在式 is/are the。"]}]}]}, {"name": "虛主詞 It 與動名詞主詞", "subs": [{"name": "It seems that 子句", "sets": [{"id": "R014", "src": "附件3 Q4", "q": {"orig": "The teacher seems to have been ill.", "stem": "It seems that ___."}, "ans": "It seems that **the teacher was ill**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "The boys seem to be tired.", "stem": "It seems that ___.", "ans": "It seems that **the boys are tired**."}, {"tag": "第三人稱單數＋過去式", "orig": "Lily seemed to be angry.", "stem": "It seemed that ___.", "ans": "It seemed that **Lily was angry**."}, {"tag": "複數主詞＋完成式不定詞", "orig": "They seem to have lost the key.", "stem": "It seems that ___.", "ans": "It seems that **they lost the key**."}], "expl": ["句型：S + seem(s) to V ＝ It seems that + S + V", "to have been 表示比 seems 更早發生 → that 子句用過去式 was ill（寫 has been ill 也可）。to be → 與 seem 同時：are / was。", "易錯：寫成 It seems that the teacher to have been ill（that 後要接完整子句）。"]}]}, {"name": "虛主詞 It + adj + to V", "sets": [{"id": "R023", "src": "附件5 Q3", "q": {"orig": "Getting up at 5:00 a.m. every day is painful.", "stem": "It ___."}, "ans": "It **is painful to get up at 5:00 a.m. every day**.", "variants": [{"tag": "過去式", "orig": "Riding a bike in the rain was dangerous.", "stem": "It ___.", "ans": "It **was dangerous to ride a bike in the rain**."}, {"tag": "未來式", "orig": "Finishing the project in one day will be hard.", "stem": "It ___.", "ans": "It **will be hard to finish the project in one day**."}, {"tag": "現在式＋for 人", "orig": "Taking the MRT is easy for tourists.", "stem": "It ___.", "ans": "It **is easy for tourists to take the MRT**."}], "expl": ["句型：V-ing ... + be + adj ＝ It + be + adj + (for 人) + to V ...", "虛主詞 It 放句首，真正主詞改成 to get up 移到句尾。be 動詞保持原句時態：was / will be；for 人 放在 to V 前面。", "易錯：寫成 It is painful to getting up（to 後接原形）。"]}, {"id": "R065", "src": "附件19 Q4", "q": {"orig": "Having a barbecue with friends is so fun.", "stem": "It is fun ___."}, "ans": "It is fun **to have a barbecue with friends**.", "variants": [{"tag": "過去式", "orig": "Riding bikes along the river was relaxing.", "stem": "It was relaxing ___.", "ans": "It was relaxing **to ride bikes along the river**."}, {"tag": "未來式", "orig": "Climbing Yangmingshan will be tiring.", "stem": "It will be tiring ___.", "ans": "It will be tiring **to climb Yangmingshan**."}, {"tag": "加 for + 人", "orig": "Learning English is easy for my brother.", "stem": "It is easy ___.", "ans": "It is easy **for my brother to learn English**."}], "expl": ["句型：V-ing（動名詞主詞）+ be + adj. ＝ It + be + adj. + (for 人) + to V。", "Having 改成 to have，放到句尾；題幹已省略 so。類似題：was / will be 由題幹決定，to 後一律用原形（to ride、to climb）；有對象時 for my brother 放在 to V 前。", "易錯：It is fun having…/ to having…（to 後要原形）；for my brother 位置放錯。", "時間詞要配合時態：本題無時間詞，時態由題幹 is / was / will be 決定，to V 不隨時態改變。"]}, {"id": "R089", "src": "模擬試題第5回 Q3", "q": {"orig": "Being honest is important.", "stem": "It's ___ honest."}, "ans": "It's **important to be** honest.", "variants": [{"tag": "過去式", "orig": "Being quiet in the library was necessary.", "stem": "It was ___ quiet in the library.", "ans": "It was **necessary to be** quiet in the library."}, {"tag": "未來式", "orig": "Being careful during the typhoon will be important.", "stem": "It will be ___ careful during the typhoon.", "ans": "It will be **important to be** careful during the typhoon."}, {"tag": "換形容詞＋現在式", "orig": "Being polite to old people is good.", "stem": "It's ___ polite to old people.", "ans": "It's **good to be** polite to old people."}], "expl": ["句型：V-ing + be + adj. ＝ It + be + adj. + to V。", "Being honest → to be honest，important 移到 It's 後。類似題：時態由題幹 was / will be 決定；to 後一律用原形 be。", "易錯：It's important being honest / to being honest（應用 to be）。", "時間詞要配合時態：本題無時間詞，時態由題幹 is / was / will be 決定，to be 不變。"]}]}, {"name": "動名詞主詞 V-ing + be", "sets": [{"id": "R034", "src": "附件7 Q4", "q": {"orig": "It is very important to wash your hands before a meal.", "stem": "Washing ___ very important."}, "ans": "Washing **your hands before a meal is** very important.", "variants": [{"tag": "過去式", "orig": "It was fun to play in the snow on Hehuan Mountain.", "stem": "Playing ___ fun.", "ans": "Playing **in the snow on Hehuan Mountain was** fun."}, {"tag": "未來式", "orig": "It will be hard to finish the homework tonight.", "stem": "Finishing ___ hard.", "ans": "Finishing **the homework tonight will be** hard."}, {"tag": "現在式＋複數名詞受詞", "orig": "It is good for us to eat fruits and vegetables.", "stem": "Eating ___ good for us.", "ans": "Eating **fruits and vegetables is** good for us."}], "expl": ["句型：It + be + adj + to V ＝ V-ing + be + adj", "動名詞片語當主詞視為單數 → is。過去式 → was；未來式 → will be。", "易錯：Eating fruits and vegetables are good（受詞是複數，但主詞 Eating 仍是單數）。"]}]}]}, {"name": "授與動詞與五大句型轉換", "subs": [{"name": "授與動詞 V + 人 + 物", "sets": [{"id": "R004", "src": "附件1 Q4", "q": {"orig": "My friend sent me a birthday card.", "stem": "My friend ___ to me."}, "ans": "My friend **sent a birthday card** to me.", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Grandma gives us red envelopes every Chinese New Year.", "stem": "Grandma ___ to us every Chinese New Year.", "ans": "Grandma **gives red envelopes** to us every Chinese New Year."}, {"tag": "第一人稱＋未來式", "orig": "I will show you my new photos.", "stem": "I ___ to you.", "ans": "I **will show my new photos** to you."}, {"tag": "複數主詞＋過去式", "orig": "My classmates lent Jenny their notes.", "stem": "My classmates ___ to Jenny.", "ans": "My classmates **lent their notes** to Jenny."}], "expl": ["句型：S + V + 人 + 物 ＝ S + V + 物 + to + 人（send, give, show, lend, tell 用 to）", "把「物」a birthday card 移到動詞後，人前面加 to。Grandma 第三人稱單數現在式 → gives；未來式 → will show；過去式 lend → lent。", "易錯：寫成 sent to me a birthday card，或 buy/make 類動詞誤用 to（應用 for）。"]}, {"id": "R025", "src": "附件5 Q5", "q": {"orig": "Tom gave his girlfriend a diamond ring.", "stem": "Tom ___ his girlfriend."}, "ans": "Tom **gave a diamond ring to** his girlfriend.", "variants": [{"tag": "第三人稱單數＋現在式（for）", "orig": "Mom buys me a new bag every year.", "stem": "Mom ___ me every year.", "ans": "Mom **buys a new bag for** me every year."}, {"tag": "複數主詞＋過去式（for）", "orig": "The kids made their mother a card.", "stem": "The kids ___ their mother.", "ans": "The kids **made a card for** their mother."}, {"tag": "第一人稱＋未來式（to）", "orig": "I will send my pen pal a postcard.", "stem": "I ___ my pen pal.", "ans": "I **will send a postcard to** my pen pal."}], "expl": ["句型：S + V + 人 + 物 ＝ S + V + 物 + to/for + 人", "give, send 用 to；buy, make 用 for。Tom gave → gave a diamond ring to；第三人稱單數現在式 → buys；未來式 → will send。", "易錯：buy/make 誤用 to，或漏掉介系詞寫成 gave a diamond ring his girlfriend。"]}, {"id": "R053", "src": "附件16 Q3", "q": {"orig": "I borrowed NT$1,000 from my mother yesterday.", "stem": "My mother lent ___."}, "ans": "My mother lent **me NT$1,000 yesterday**.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Tom borrowed a pen from his classmate this morning.", "stem": "His classmate lent ___.", "ans": "His classmate lent **Tom a pen this morning**."}, {"tag": "現在式＋複數間接受詞（often 保留）", "orig": "The students often borrow books from Ms. Wang.", "stem": "Ms. Wang often lends ___.", "ans": "Ms. Wang often lends **the students books**."}, {"tag": "第一人稱複數＋未來式", "orig": "We will borrow an umbrella from our neighbor tomorrow.", "stem": "Our neighbor will lend ___.", "ans": "Our neighbor will lend **us an umbrella tomorrow**."}], "expl": ["句型：A borrow 物 from B ＝ B lend + 人 + 物（＝ B lend 物 to 人）。", "lend 的過去式是 lent；I 當受詞要改成 me。類似題：Ms. Wang 第三人稱單數現在式 → lends；will 後接原形 lend；We 當受詞 → us。", "易錯：My mother lent I...（受詞要用受格）；把 borrow 和 lend 方向搞反。", "時間詞要配合時態：yesterday / this morning（已過去）→ lent；often → 現在式 lends；tomorrow → will lend。時間詞要照抄到句尾。"]}, {"id": "R054", "src": "附件16 Q4", "q": {"orig": "Gina made me some chocolate cake.（加入介系詞 for 改寫，注意不能加其他字）", "stem": "Gina ___."}, "ans": "Gina **made some chocolate cake for me**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "My grandparents often cook us dinner.（加入介系詞 for 改寫，注意不能加其他字）", "stem": "My grandparents ___.", "ans": "My grandparents **often cook dinner for us**."}, {"tag": "第一人稱＋未來式", "orig": "I will buy my sister a birthday gift.（加入介系詞 for 改寫，注意不能加其他字）", "stem": "I ___.", "ans": "I **will buy a birthday gift for my sister**."}, {"tag": "改用 to＋過去式", "orig": "Mr. Chen gave the students some candy.（加入介系詞 to 改寫，注意不能加其他字）", "stem": "Mr. Chen ___.", "ans": "Mr. Chen **gave some candy to the students**."}], "expl": ["句型：S + V + 人 + 物 ＝ S + V + 物 + for/to + 人。make、cook、buy 用 for；give、send、lend 用 to。", "原句過去式 made 保持不變，只把 me 移到後面並加 for。類似題：複數主詞 → cook 不加 s；未來式 will buy。", "易錯：Gina made for me some cake（介系詞片語要放在物之後）；give 誤用 for。", "時間詞要配合時態：本題時態跟原句一致（made / often cook / will buy / gave），頻率副詞 often 保留在動詞前。"]}, {"id": "R056", "src": "附件16 Q6", "q": {"orig": "Allen asked his neighbor to help him.（用 ask 和 favor 改寫）", "stem": "Allen ___."}, "ans": "Allen **asked his neighbor a favor**.", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Lisa often asks her brother to help her.（用 ask 和 favor 改寫）", "stem": "Lisa ___.", "ans": "Lisa **often asks her brother a favor**."}, {"tag": "第一人稱複數＋未來式", "orig": "We will ask our teacher to help us.（用 ask 和 favor 改寫）", "stem": "We ___.", "ans": "We **will ask our teacher a favor**."}, {"tag": "複數主詞＋過去式", "orig": "The kids asked their father to help them.（用 ask 和 favor 改寫）", "stem": "The kids ___.", "ans": "The kids **asked their father a favor**."}], "expl": ["句型：ask + 人 + a favor ＝ ask a favor of + 人（請某人幫忙）；ask sb. to help sb. 可改寫成此句型。", "過去式 asked 不變；也可寫 Allen asked a favor of his neighbor.。類似題：Lisa 第三人稱單數現在式 → asks；will 後接原形 ask；複數過去式 asked。", "易錯：asked his neighbor a favor of him（多加字）；ask a favor to his neighbor（介系詞要用 of）。", "時間詞要配合時態：often → 現在簡單式 asks；will → will ask；原句過去式 → asked。often 要保留在動詞前。"]}]}, {"name": "S + be + N／S + Vi", "sets": [{"id": "R051", "src": "附件16 Q1", "q": {"orig": "Jimmy teaches at a senior high school.（用「主詞+連綴動詞+名詞」的句型改寫）", "stem": "Jimmy is ___."}, "ans": "Jimmy is **a senior high school teacher**.", "variants": [{"tag": "複數主詞＋現在式", "orig": "My parents teach at an elementary school.（用「主詞+連綴動詞+名詞」的句型改寫）", "stem": "My parents are ___.", "ans": "My parents are **elementary school teachers**."}, {"tag": "第三人稱單數＋過去式", "orig": "Mr. Lin drove a taxi in Taipei ten years ago.（用「主詞+連綴動詞+名詞」的句型改寫）", "stem": "Mr. Lin was ___ ten years ago.", "ans": "Mr. Lin was **a taxi driver in Taipei** ten years ago."}, {"tag": "第一人稱＋未來式", "orig": "I will sing in a band next year.（用「主詞+連綴動詞+名詞」的句型改寫）", "stem": "I will be ___ next year.", "ans": "I will be **a singer in a band** next year."}], "expl": ["句型：S + be（連綴動詞）+ N（主詞補語）。把動作動詞 teach 改成表身分的名詞 teacher。", "單數主詞要加 a；類似題 My parents 是複數 → are + teachers（名詞也要複數）；過去式用 was；未來式用 will be。", "易錯：Jimmy is teach...（be 動詞後不可接原形動詞）；複數主詞後忘了名詞加 s。", "時間詞要配合時態：無時間詞的現在習慣 → is/are；ten years ago → was；next year → will be。時間詞照抄在句尾。"]}, {"id": "R052", "src": "附件16 Q2", "q": {"orig": "It was rainy in London two weeks ago.（用「主詞+不及物動詞」的句型改寫）", "stem": "It ___."}, "ans": "It **rained in London two weeks ago**.", "variants": [{"tag": "現在簡單式（換天氣）", "orig": "It is snowy on Hehuan Mountain every winter.（用「主詞+不及物動詞」的句型改寫）", "stem": "It ___.", "ans": "It **snows on Hehuan Mountain every winter**."}, {"tag": "未來式", "orig": "It will be rainy in Taipei tomorrow.（用「主詞+不及物動詞」的句型改寫）", "stem": "It ___.", "ans": "It **will rain in Taipei tomorrow**."}, {"tag": "現在進行式", "orig": "It is rainy in Kaohsiung now.（用「主詞+不及物動詞」的句型改寫）", "stem": "It ___.", "ans": "It **is raining in Kaohsiung now**."}], "expl": ["句型：S + Vi（不及物動詞）：It + rain/snow。形容詞 rainy、snowy 改為動詞 rain、snow。", "two weeks ago → 過去式 rained。類似題：every winter → 現在式 snows（It 為第三人稱單數加 s）；tomorrow → will rain；now → is raining。", "易錯：It was rained（rain 是不及物動詞，不能用被動）；It will rains（will 後接原形）。", "時間詞要配合時態：two weeks ago → 過去式 rained；every winter → 現在簡單式 snows；tomorrow → will rain；now → is raining。"]}]}, {"name": "受詞補語 make + O + adj", "sets": [{"id": "R055", "src": "附件16 Q5", "q": {"orig": "She was depressed by her husband's death.（用 make，及「主詞+及物動詞+受詞+受詞補語」的句型改寫）", "stem": "Her husband's death ___."}, "ans": "Her husband's death **made her depressed**.", "variants": [{"tag": "複數受詞＋過去式", "orig": "The students were excited by the good news.（用 make，及「主詞+及物動詞+受詞+受詞補語」的句型改寫）", "stem": "The good news ___.", "ans": "The good news **made the students excited**."}, {"tag": "第一人稱受詞＋現在式", "orig": "I am always bored by math class.（用 make，及「主詞+及物動詞+受詞+受詞補語」的句型改寫）", "stem": "Math class always ___.", "ans": "Math class always **makes me bored**."}, {"tag": "未來式", "orig": "Tim will be surprised by the gift.（用 make，及「主詞+及物動詞+受詞+受詞補語」的句型改寫）", "stem": "The gift ___.", "ans": "The gift **will make Tim surprised**."}], "expl": ["句型：S + make + O + adj.（受詞補語）：某事使某人感到…。", "原句 was → 過去式 made；she 當受詞 → her。類似題：Math class 為單數主詞現在式 → makes；I → me；未來式 will make（原形）。", "易錯：made she depressed（受詞要用受格）；made her depress（補語要用 -ed 形容詞）。", "時間詞要配合時態：本題時態由原句 be 動詞決定：was/were → made；am always（習慣）→ always makes；will be → will make。"]}]}]}, {"name": "使役動詞與感官動詞", "subs": [{"name": "使役 have + 人 + 原形V", "sets": [{"id": "R003", "src": "附件1 Q3", "q": {"orig": "My mom asked me to take out the trash.", "stem": "My mom had me ___ the trash."}, "ans": "My mom had me **take out** the trash.", "variants": [{"tag": "現在式＋複數受詞", "orig": "My dad always asks us to clean the living room.", "stem": "My dad always has us ___ the living room.", "ans": "My dad always has us **clean** the living room."}, {"tag": "未來式", "orig": "The teacher will ask Tom to close the windows.", "stem": "The teacher will have Tom ___ the windows.", "ans": "The teacher will have Tom **close** the windows."}, {"tag": "複數主詞＋過去式", "orig": "Our parents asked my sister to wash the dishes.", "stem": "Our parents had my sister ___ the dishes.", "ans": "Our parents had my sister **wash** the dishes."}], "expl": ["句型：S + ask + 人 + to V ＝ S + have/has/had + 人 + 原形V（使役動詞）", "使役動詞 have 後的受詞接原形動詞 take out。時態與人稱只影響 have 本身：has（第三人稱單數現在式）、had（過去式）、will have（未來式）。", "易錯：寫成 had me to take out，使役動詞後不可加 to。"]}]}]}, {"name": "形容詞↔副詞・慣用句型轉換（unless／instead of／by oneself 等）", "subs": [{"name": "形容詞↔副詞／情緒形容詞", "sets": [{"id": "R002", "src": "附件1 Q2", "q": {"orig": "He is excited about the good news.", "stem": "The good news is ___."}, "ans": "The good news is **exciting to him**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "They were surprised at the result.", "stem": "The result was ___.", "ans": "The result was **surprising to them**."}, {"tag": "第一人稱＋現在式", "orig": "I am bored with the movie.", "stem": "The movie is ___.", "ans": "The movie is **boring to me**."}, {"tag": "第三人稱單數（she）＋過去式", "orig": "She was interested in the story.", "stem": "The story was ___.", "ans": "The story was **interesting to her**."}], "expl": ["句型：人 + be + V-ed（感到…）＝ 事物 + be + V-ing + to + 人（令人…）", "主詞換成 the good news（事物）→ 用 exciting；介系詞 to 後接受格 him。類似題 they → them、I → me、she → her，be 動詞跟著新主詞的時態（was/is）。", "易錯：寫成 The good news is excited（事物不會「感到興奮」）。"]}, {"id": "R066", "src": "附件19 Q5", "q": {"orig": "Marco is a careful driver.", "stem": "Marco drives ___."}, "ans": "Marco drives **carefully**.", "variants": [{"tag": "複數主詞", "orig": "My sisters are fast runners.", "stem": "My sisters run ___.", "ans": "My sisters run **fast**."}, {"tag": "過去式", "orig": "Ms. Lin was a good singer.", "stem": "Ms. Lin sang ___.", "ans": "Ms. Lin sang **well**."}, {"tag": "第一人稱", "orig": "I am a slow eater.", "stem": "I eat ___.", "ans": "I eat **slowly**."}], "expl": ["句型：S + be + a + adj. + N ＝ S + V + adv.（形容詞修飾名詞，副詞修飾動詞）。", "careful driver → drives carefully。類似題：fast 形副同形；good 的副詞是 well；過去式 sang、複數 run 由題幹決定。", "易錯：Marco drives careful（動詞後要用副詞）；sang good（應為 well）。", "時間詞要配合時態：本題無時間詞，動詞時態照原句 be 動詞（is/are → 現在式；was → 過去式 sang）。"]}]}, {"name": "因果條件 because／unless", "sets": [{"id": "R005", "src": "附件1 Q5", "q": {"orig": "We can go out if it stops raining.", "stem": "We ___ unless ___."}, "ans": "We **can't go out** unless **it stops raining**.", "variants": [{"tag": "第三人稱單數＋現在式", "orig": "Ken can pass the test if he studies hard.", "stem": "Ken ___ unless ___.", "ans": "Ken **can't pass the test** unless **he studies hard**."}, {"tag": "複數主詞＋未來式", "orig": "They will go to the beach if the typhoon goes away.", "stem": "They ___ unless ___.", "ans": "They **won't go to the beach** unless **the typhoon goes away**."}, {"tag": "第一人稱＋過去式", "orig": "When I was a child, I could watch TV if I finished my homework.", "stem": "When I was a child, I ___ unless ___.", "ans": "When I was a child, I **couldn't watch TV** unless **I finished my homework**."}], "expl": ["句型：unless ＝ if ... not（除非）", "原句是「如果雨停就能出去」，改用 unless 後主要子句要變否定：can't go out unless it stops raining。未來式 will → won't；過去習慣（When I was a child）could → couldn't。", "時間詞要配合時態：過去的 could 要有過去時間（When I was a child）；unless/if 子句表未來時仍用現在式（unless the typhoon goes away）。易錯：unless it doesn't stop，或 unless the typhoon will go away。"]}, {"id": "R042", "src": "附件10 Q2", "q": {"orig": "Her test was not good enough, so the teacher failed her.", "stem": "The teacher ___ because ___."}, "ans": "The teacher **failed her** because **her test was not good enough**.", "variants": [{"tag": "複數主詞＋過去式", "orig": "The boys were too tired, so they went to bed early.", "stem": "The boys ___ because ___.", "ans": "The boys **went to bed early** because **they were too tired**."}, {"tag": "第三人稱單數＋現在式", "orig": "Grandpa feels tired every afternoon, so he takes a nap after lunch.", "stem": "Grandpa ___ because ___.", "ans": "Grandpa **takes a nap after lunch** because **he feels tired every afternoon**."}, {"tag": "第一人稱複數＋未來式", "orig": "The typhoon will come tomorrow, so we will have a day off.", "stem": "We ___ because ___.", "ans": "We **will have a day off** because **the typhoon will come tomorrow**."}], "expl": ["句型：原因, so 結果 ＝ 結果 + because + 原因", "so 後面是結果 → 放前面；so 前面是原因 → 放在 because 後。各子句的時態與時間詞照原句：takes（every afternoon，現在簡單式）、will have（tomorrow，未來式）。", "易錯：because 與 so 同時使用（Because..., so...）。"]}, {"id": "R069", "src": "模擬試題第1回 Q3", "q": {"orig": "Jenny was not hungry, so she did not eat anything.", "stem": "Jenny ___ because ___ not hungry."}, "ans": "Jenny **did not eat anything** because **she was** not hungry.", "variants": [{"tag": "複數主詞＋現在式", "orig": "The kids are not sleepy, so they do not want to go to bed.", "stem": "The kids ___ because ___ not sleepy.", "ans": "The kids **do not want to go to bed** because **they are** not sleepy."}, {"tag": "第一人稱＋過去式", "orig": "I was not well yesterday, so I did not go to school.", "stem": "I ___ because ___ not well yesterday.", "ans": "I **did not go to school** because **I was** not well yesterday."}, {"tag": "第三人稱單數＋未來式", "orig": "Ben will not be free tomorrow, so he will not join the party.", "stem": "Ben ___ because ___ not be free tomorrow.", "ans": "Ben **will not join the party** because **he will** not be free tomorrow."}], "expl": ["句型：原因, so 結果 ＝ 結果 + because + 原因（so 與 because 不可同時用）。", "結果「沒吃東西」放前面，原因「不餓」放 because 後，要補主詞 she 與 was。類似題：they are（複數現在式）、I was（過去式，配 yesterday）、he will（未來式），時態照原句。", "易錯：because not hungry（because 後要有完整子句 S + V）；Because…, so…（不可連用）。", "時間詞要配合時態：yesterday → 過去式（did not go / was）；tomorrow → will；無時間詞的現況 → 現在式（are / do）。because 子句的時態要和原句一致。"]}]}, {"name": "反身代名詞 by oneself", "sets": [{"id": "R033", "src": "附件7 Q3", "q": {"orig": "Brian lives on his own in an apartment by the river.", "stem": "Brian lives by ___ by the river."}, "ans": "Brian lives by **himself in an apartment** by the river.", "variants": [{"tag": "第一人稱＋過去式", "orig": "I traveled to Japan on my own last summer.", "stem": "I traveled by ___ last summer.", "ans": "I traveled by **myself to Japan** last summer."}, {"tag": "複數主詞＋過去式", "orig": "The kids made dinner on their own last night.", "stem": "The kids made dinner by ___ last night.", "ans": "The kids made dinner by **themselves** last night."}, {"tag": "第三人稱單數（she）＋未來式", "orig": "Amy will finish the project on her own.", "stem": "Amy will finish the project by ___.", "ans": "Amy will finish the project by **herself**."}], "expl": ["句型：on one's own ＝ by oneself（獨自）", "Brian → himself，並補上 in an apartment。I → myself；the kids → themselves；Amy → herself。", "易錯：寫成 hisself、themself，或 by him。"]}, {"id": "R085", "src": "模擬試題第4回 Q4", "q": {"orig": "Nobody helped my brother clean the floor.", "stem": "My brother ___ the floor by ___."}, "ans": "My brother **cleaned** the floor by **himself**.", "variants": [{"tag": "第三人稱單數（女）＋過去式", "orig": "Nobody helped my sister do her homework.", "stem": "My sister ___ her homework by ___.", "ans": "My sister **did** her homework by **herself**."}, {"tag": "複數主詞＋現在式", "orig": "Nobody helps the kids make their beds every morning.", "stem": "The kids ___ their beds by ___ every morning.", "ans": "The kids **make** their beds by **themselves** every morning."}, {"tag": "第一人稱＋未來式", "orig": "Nobody will help me cook dinner tomorrow.", "stem": "I ___ dinner by ___ tomorrow.", "ans": "I **will cook** dinner by **myself** tomorrow."}], "expl": ["句型：by oneself（獨自、靠自己）：反身代名詞要和主詞一致。", "主詞 my brother → himself；原句過去式 → cleaned。類似題：my sister → herself、did；the kids → themselves、make；I → myself、will cook。", "易錯：by hisself / by themself（拼法錯）；反身代名詞與主詞不一致。", "時間詞要配合時態：every morning → 現在式 make；tomorrow → will cook；原句過去式 helped → cleaned / did。"]}]}, {"name": "動詞片語 borrow／instead of", "sets": [{"id": "R038", "src": "附件8 Q3", "q": {"orig": "Can you lend your bike to me tomorrow?", "stem": "May I ___ tomorrow?"}, "ans": "May I **borrow your bike** tomorrow?", "variants": [{"tag": "第三人稱單數", "orig": "Can you lend your umbrella to Amy?", "stem": "Can Amy ___?", "ans": "Can Amy **borrow your umbrella**?"}, {"tag": "第一人稱複數＋過去式", "orig": "Mr. Wu lent his car to us last week.", "stem": "We ___ from Mr. Wu last week.", "ans": "We **borrowed his car** from Mr. Wu last week."}, {"tag": "第一人稱複數", "orig": "Will you lend your comic books to us?", "stem": "Can we ___?", "ans": "Can we **borrow your comic books**?"}], "expl": ["句型：A lend + 物 + to B ＝ B borrow + 物 + from A", "lend 是「借出」，borrow 是「借入」；主詞換成借東西的人 I → May I borrow your bike。Amy → Can Amy borrow；過去式 lent ↔ borrowed，借出的人放在 from 後面。", "易錯：寫成 May I lend your bike（借入要用 borrow），或 borrowed his car to Mr. Wu。"]}, {"id": "R059", "src": "附件17 Q3", "q": {"orig": "Rather than go out for a meal, we decided to order in.", "stem": "Instead of ___, we decided to order in."}, "ans": "Instead of **going out for a meal**, we decided to order in.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Rather than take a taxi, Ben took the MRT.", "stem": "Instead of ___, Ben took the MRT.", "ans": "Instead of **taking a taxi**, Ben took the MRT."}, {"tag": "第三人稱單數＋現在式", "orig": "Rather than watch TV, my sister reads books every night.", "stem": "Instead of ___, my sister reads books every night.", "ans": "Instead of **watching TV**, my sister reads books every night."}, {"tag": "複數主詞＋未來式", "orig": "Rather than stay home, they will go to the night market tonight.", "stem": "Instead of ___, they will go to the night market tonight.", "ans": "Instead of **staying home**, they will go to the night market tonight."}], "expl": ["句型：Rather than + 原形V ＝ Instead of + V-ing（不…而改…）。", "of 是介系詞，後面動詞一律用 V-ing：going out。不論主句是過去、現在或未來式（took / reads / will go），instead of 後都用 V-ing，不跟著變時態。", "易錯：Instead of go out / Instead of went out（介系詞後要接動名詞）。", "時間詞要配合時態：時間詞（every night / tonight）只決定主句時態（reads / will go），instead of 後面一律 V-ing。"]}, {"id": "R075", "src": "模擬試題第2回 Q4", "q": {"orig": "Chris took care of his mother at the hospital.", "stem": "Chris had to ___ at the hospital."}, "ans": "Chris had to **take care of his mother** at the hospital.", "variants": [{"tag": "複數主詞＋現在式", "orig": "The nurses look after the patients at night.", "stem": "The nurses have to ___ at night.", "ans": "The nurses have to **look after the patients** at night."}, {"tag": "第三人稱單數＋現在式", "orig": "My sister walks the dog every morning.", "stem": "My sister has to ___ every morning.", "ans": "My sister has to **walk the dog** every morning."}, {"tag": "第一人稱＋未來式", "orig": "I will clean the classroom tomorrow.", "stem": "I will have to ___ tomorrow.", "ans": "I will have to **clean the classroom** tomorrow."}], "expl": ["句型：S + have/has/had to + 原形V（必須…）。", "had to 已表過去，後面動詞改回原形 take（不可寫 took）。類似題：複數現在式 have to；單數 has to（walks → walk）；未來式 will have to。", "易錯：had to took care of（to 後一律原形）；My sister has to walks。", "時間詞要配合時態：had to 表過去；every morning / at night（習慣）→ have/has to；tomorrow → will have to。"]}]}, {"name": "too…to／enough to", "sets": [{"id": "R074", "src": "模擬試題第2回 Q3", "q": {"orig": "Cindy is too young to learn how to drive.", "stem": "Cindy isn't ___ enough ___ drive."}, "ans": "Cindy isn't **old** enough **to learn how to** drive.", "variants": [{"tag": "複數主詞", "orig": "The kids are too short to ride the roller coaster.", "stem": "The kids aren't ___ enough ___ ride the roller coaster.", "ans": "The kids aren't **tall** enough **to** ride the roller coaster."}, {"tag": "第三人稱單數＋過去式", "orig": "Leo was too weak to carry the box.", "stem": "Leo wasn't ___ enough ___ carry the box.", "ans": "Leo wasn't **strong** enough **to** carry the box."}, {"tag": "第一人稱", "orig": "I am too slow to catch the bus.", "stem": "I'm not ___ enough ___ catch the bus.", "ans": "I'm not **fast** enough **to** catch the bus."}], "expl": ["句型：too + adj. + to V ＝ not + 反義adj. + enough + to V。", "too young → not old enough；第二格補 to learn how to（保留原句意思）。類似題：short ↔ tall、weak ↔ strong、slow ↔ fast；be 動詞依主詞與時態用 aren't / wasn't / am not。", "易錯：isn't enough old（enough 要放在形容詞後面）；漏掉 to。", "時間詞要配合時態：本題無時間詞，be 動詞照原句時態（isn't / aren't / wasn't / am not）。"]}, {"id": "R091", "src": "模擬試題第5回 Q5", "q": {"orig": "The cat is so fat that it can't move quickly.", "stem": "The cat is too ___ quickly."}, "ans": "The cat is too **fat to move** quickly.", "variants": [{"tag": "第三人稱單數＋過去式", "orig": "Tim was so tired that he couldn't walk home.", "stem": "Tim was too ___ home.", "ans": "Tim was too **tired to walk** home."}, {"tag": "複數主詞＋for 人", "orig": "The boxes are so heavy that we can't carry them.", "stem": "The boxes are too ___.", "ans": "The boxes are too **heavy for us to carry**."}, {"tag": "第一人稱", "orig": "I am so sick that I can't go to school today.", "stem": "I am too ___ to school today.", "ans": "I am too **sick to go** to school today."}], "expl": ["句型：S + be + so + adj. + that + S + can't + V ＝ S + be + too + adj. + to V。", "主詞相同時直接 too fat to move；時態由前面 be 動詞表示（was too…），to 後一律原形。類似題：主詞不同時加 for us，句尾受詞 them 要刪掉（指的就是主詞 the boxes）。", "易錯：too fat to can't move（too…to 已含否定）；too heavy for us to carry them（多了 them）。", "時間詞要配合時態：today 保留在句尾；時態由前面 be 動詞（am / are / was）表示，too…to 後一律原形。"]}]}]}]}, "2": {"title": "Part 2 句子合併 Combining", "blocks": [{"name": "對等連接詞（and／but／too／either／both／neither…nor）", "subs": [{"name": "Both…and／Neither…nor", "sets": [{"id": "C001", "src": "附件1 Q6", "q": {"sents": ["Derek can't swim.", "Eric can't swim, either."], "stem": "Neither ___ nor ___ swim."}, "ans": "Neither **Derek** nor **Eric can** swim.", "variants": [{"tag": "過去式＋一般動詞", "sents": ["Tom didn't go to the night market.", "Jerry didn't go to the night market, either."], "stem": "Neither ___ nor ___ to the night market.", "ans": "Neither **Tom** nor **Jerry went** to the night market."}, {"tag": "複數＋單數主詞（就近原則）", "sents": ["My parents don't eat meat.", "My brother doesn't eat meat, either."], "stem": "Neither ___ nor ___ meat.", "ans": "Neither **my parents** nor **my brother eats** meat."}, {"tag": "第一人稱＋未來式", "sents": ["I won't take the MRT tomorrow.", "My sister won't take the MRT tomorrow, either."], "stem": "Neither ___ nor ___ the MRT tomorrow.", "ans": "Neither **I** nor **my sister will take** the MRT tomorrow."}], "expl": ["句型：Neither A nor B + V（動詞與最靠近的 B 一致）。", "Neither…nor 本身已是否定，所以用 can swim，不可再寫 can't。類似題：my brother 為單數 → eats；過去式用 went；未來式用 will take。", "易錯：Neither Derek nor Eric can't swim.（雙重否定）"]}, {"id": "C008", "src": "附件2 Q8", "q": {"sents": ["Peter is a cook.", "John is a cook, too."], "stem": "Both ___."}, "ans": "Both **Peter and John are cooks**.", "variants": [{"tag": "過去式", "sents": ["Linda was a nurse.", "Mary was a nurse, too."], "stem": "Both ___.", "ans": "Both **Linda and Mary were nurses**."}, {"tag": "一般動詞現在式", "sents": ["My brother plays basketball.", "My cousin plays basketball, too."], "stem": "Both ___.", "ans": "Both **my brother and my cousin play basketball**."}, {"tag": "未來式", "sents": ["Kevin will join the English club.", "Jack will join the English club, too."], "stem": "Both ___.", "ans": "Both **Kevin and Jack will join the English club**."}], "expl": ["句型：Both A and B + 複數動詞。", "Both A and B 是複數主詞：is → are、was → were、plays → play；名詞也要變複數 cooks／nurses。", "易錯：Both Peter and John is a cook.（動詞、名詞都沒改複數）"]}, {"id": "C027", "src": "附件8 Q7", "q": {"sents": ["Mary didn't wash the clothes.", "Susan didn't wash the clothes."], "stem": "Neither ___."}, "ans": "Neither **Mary nor Susan washed the clothes**.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Tom doesn't like carrots.", "Ben doesn't like carrots."], "stem": "Neither ___.", "ans": "Neither **Tom nor Ben likes carrots**."}, {"tag": "複數＋單數主詞＋過去式", "sents": ["The students weren't late.", "The teacher wasn't late."], "stem": "Neither ___.", "ans": "Neither **the students nor the teacher was late**."}, {"tag": "未來式", "sents": ["Amy won't go to the party.", "Her parents won't go to the party."], "stem": "Neither ___.", "ans": "Neither **Amy nor her parents will go to the party**."}], "expl": ["句型：Neither A nor B + 肯定動詞（動詞依 B，就近原則）。", "Neither 已含否定，didn't wash 改成 washed；Ben 單數 → likes；the teacher 單數 → was。", "易錯：Neither Mary nor Susan didn't wash…（雙重否定）"]}, {"id": "C043", "src": "附件18 Q7", "q": {"sents": ["Jennifer loves jogging.", "Leon loves jogging, too."], "stem": "Both ___."}, "ans": "Both **Jennifer and Leon love jogging**.", "variants": [{"tag": "過去式", "sents": ["Amy went to the night market last night.", "Her brother went to the night market last night, too."], "stem": "Both ___.", "ans": "Both **Amy and her brother went to the night market last night**."}, {"tag": "未來式", "sents": ["Ken will join the basketball team.", "Tim will join the basketball team, too."], "stem": "Both ___.", "ans": "Both **Ken and Tim will join the basketball team**."}, {"tag": "現在進行式（be 動詞變 are）", "sents": ["My father is cooking dinner.", "My mother is cooking dinner, too."], "stem": "Both ___.", "ans": "Both **my father and my mother are cooking dinner**."}], "expl": ["句型：Both A and B + 複數動詞。", "兩人都喜歡慢跑，Both Jennifer and Leon 是複數主詞，動詞用 love（不加 s）。", "類似題：過去式 went、未來式 will join 不受單複數影響；進行式 is 要改成 are。", "易錯：寫成 Both Jennifer and Leon loves（動詞誤用單數）或漏掉 and。"]}, {"id": "C052", "src": "模擬試題第2回 Q6", "q": {"sents": ["Jane talked to Mrs. Lee this morning.", "Bruce talked to Mrs. Lee this morning, too."], "stem": "Both ___ Mrs. Lee this morning."}, "ans": "Both **Jane and Bruce talked to** Mrs. Lee this morning.", "variants": [{"tag": "現在式（複數動詞）", "sents": ["Amy helps Grandma every Sunday.", "Tom helps Grandma every Sunday, too."], "stem": "Both ___ Grandma every Sunday.", "ans": "Both **Amy and Tom help** Grandma every Sunday."}, {"tag": "未來式", "sents": ["Ken will meet Mr. Wang tomorrow.", "Lisa will meet Mr. Wang tomorrow, too."], "stem": "Both ___ Mr. Wang tomorrow.", "ans": "Both **Ken and Lisa will meet** Mr. Wang tomorrow."}, {"tag": "現在完成式", "sents": ["My father has been to Japan.", "My mother has been to Japan, too."], "stem": "Both ___ Japan.", "ans": "Both **my father and my mother have been to** Japan."}], "expl": ["句型：Both A and B + 複數動詞。", "兩人都在今天早上和李太太談過，過去式 talked to 單複數同形。", "類似題：現在式 helps → help；現在完成式 has been → have been（主詞變複數）。", "易錯：漏掉介系詞 to（talked Mrs. Lee）或動詞用單數。"]}]}, {"name": "附和句 too／so did", "sets": [{"id": "C006", "src": "附件2 Q6", "q": {"sents": ["Amy is tall.", "Her sister is tall."], "stem": "___, and ___, too."}, "ans": "**Amy is tall**, and **her sister is**, too.", "variants": [{"tag": "過去式", "sents": ["Tom was sick.", "His brother was sick."], "stem": "___, and ___, too.", "ans": "**Tom was sick**, and **his brother was**, too."}, {"tag": "複數主詞", "sents": ["My parents are busy.", "My teachers are busy."], "stem": "___, and ___, too.", "ans": "**My parents are busy**, and **my teachers are**, too."}, {"tag": "未來式", "sents": ["Kevin will be late.", "Lisa will be late."], "stem": "___, and ___, too.", "ans": "**Kevin will be late**, and **Lisa will**, too."}], "expl": ["句型：肯定句, and + S + be／助動詞, too.（…也是）", "後半句省略重複的形容詞，只留 be 動詞；主詞改變動詞跟著變：過去 was、複數 are、未來用 will。", "易錯：her sister is too tall（意思變成「太高」）；her sister does, too（be 動詞句不可用 does）。"]}, {"id": "C007", "src": "附件2 Q7", "q": {"sents": ["Daniel walks to school.", "Diana walks to school."], "stem": "___, and ___, too."}, "ans": "**Daniel walks to school**, and **Diana does**, too.", "variants": [{"tag": "過去式", "sents": ["Ben watched TV last night.", "Amy watched TV last night."], "stem": "___, and ___, too.", "ans": "**Ben watched TV last night**, and **Amy did**, too."}, {"tag": "複數主詞＋現在式", "sents": ["I like bubble tea.", "My friends like bubble tea."], "stem": "___, and ___, too.", "ans": "**I like bubble tea**, and **my friends do**, too."}, {"tag": "未來式", "sents": ["My dad will take the MRT.", "My mom will take the MRT."], "stem": "___, and ___, too.", "ans": "**My dad will take the MRT**, and **my mom will**, too."}], "expl": ["句型：S1 + 一般動詞…, and + S2 + do／does／did, too.", "一般動詞的附和要用助動詞代替：Diana（單數現在）→ does；過去 → did；複數 → do；未來 → will。", "易錯：Diana walks, too 雖可，但本題考助動詞代換；勿寫 Diana is, too。"]}, {"id": "C069", "src": "模擬試題第5回 Q8", "q": {"sents": ["Jean ordered an apple pie.", "Sue also ordered an apple pie."], "stem": "Jean ordered an apple pie, and ___ Sue."}, "ans": "Jean ordered an apple pie, and **so did** Sue.", "variants": [{"tag": "現在式＋第三人稱單數", "sents": ["Tom likes bubble tea.", "Amy also likes bubble tea."], "stem": "Tom likes bubble tea, and ___ Amy.", "ans": "Tom likes bubble tea, and **so does** Amy."}, {"tag": "be 動詞＋複數主詞", "sents": ["I am a student.", "My cousins are students, too."], "stem": "I am a student, and ___ my cousins.", "ans": "I am a student, and **so are** my cousins."}, {"tag": "否定＋助動詞 can", "sents": ["Ken can't swim.", "His sister can't swim, either."], "stem": "Ken can't swim, and ___ his sister.", "ans": "Ken can't swim, and **neither can** his sister."}], "expl": ["句型：肯定句, and so + 助動詞/be + S（…也是）；否定句, and neither + 助動詞/be + S。", "ordered 是過去式一般動詞 → 助動詞用 did：so did Sue。", "類似題：likes → so does（Amy 單數）；are → so are（cousins 複數）；can't → neither can。", "易錯：寫成 so Sue did 或 so ordered Sue；否定句不可用 so。"]}]}, {"name": "but 否定簡答 isn't／doesn't", "sets": [{"id": "C009", "src": "附件2 Q9", "q": {"sents": ["Eric is my classmate.", "Emily is not my classmate."], "stem": "___, but ___."}, "ans": "**Eric is my classmate**, but **Emily isn't**.", "variants": [{"tag": "過去式", "sents": ["Tom was at school yesterday.", "Jerry was not at school yesterday."], "stem": "___, but ___.", "ans": "**Tom was at school yesterday**, but **Jerry wasn't**."}, {"tag": "複數＋單數主詞", "sents": ["My cousins are students.", "My sister is not a student."], "stem": "___, but ___.", "ans": "**My cousins are students**, but **my sister isn't**."}, {"tag": "未來式", "sents": ["Mr. Lin will be at the meeting.", "Ms. Wang will not be at the meeting."], "stem": "___, but ___.", "ans": "**Mr. Lin will be at the meeting**, but **Ms. Wang won't**."}], "expl": ["句型：肯定句, but + S + be not／助動詞 not.（簡答）", "but 連接相反的情況，後半句省略重複部分，只留 be 動詞否定：過去 wasn't、單數 isn't、未來 won't。", "易錯：but Emily isn't, too.（否定不用 too）"]}, {"id": "C010", "src": "附件2 Q10", "q": {"sents": ["Eric plays the piano.", "Emily doesn't play the piano."], "stem": "___, but ___."}, "ans": "**Eric plays the piano**, but **Emily doesn't**.", "variants": [{"tag": "過去式", "sents": ["I finished my homework.", "My brother didn't finish his homework."], "stem": "___, but ___.", "ans": "**I finished my homework**, but **my brother didn't**."}, {"tag": "複數主詞＋現在式", "sents": ["My parents drink coffee.", "My grandma doesn't drink coffee."], "stem": "___, but ___.", "ans": "**My parents drink coffee**, but **my grandma doesn't**."}, {"tag": "未來式", "sents": ["Amy will go to the night market.", "Her friends won't go to the night market."], "stem": "___, but ___.", "ans": "**Amy will go to the night market**, but **her friends won't**."}], "expl": ["句型：S1 + 一般動詞…, but + S2 + don't／doesn't／didn't.", "一般動詞的否定簡答用助動詞：Emily（單數現在）→ doesn't；過去 → didn't；未來 → won't。", "易錯：but Emily isn't.（一般動詞不可用 be 動詞代替）"]}]}, {"name": "and 連接動詞片語", "sets": [{"id": "C047", "src": "模擬試題第1回 Q6", "q": {"sents": ["Peggy likes to read.", "Peggy also likes to play the guitar."], "stem": "Peggy likes to ___ ."}, "ans": "Peggy likes to **read and play the guitar**.", "variants": [{"tag": "複數主詞", "sents": ["My brothers like to swim.", "They also like to ride bikes."], "stem": "My brothers like to ___ .", "ans": "My brothers like to **swim and ride bikes**."}, {"tag": "第三人稱單數＋過去式", "sents": ["Tim wanted to eat stinky tofu.", "He also wanted to drink bubble tea."], "stem": "Tim wanted to ___ .", "ans": "Tim wanted to **eat stinky tofu and drink bubble tea**."}, {"tag": "第一人稱複數＋未來式（be going to）", "sents": ["We are going to visit Grandma.", "We are also going to watch a movie."], "stem": "We are going to ___ .", "ans": "We are going to **visit Grandma and watch a movie**."}], "expl": ["句型：S + V + to + V1 + and + V2（and 連接兩個原形動詞，共用 to）。", "兩句主詞和 likes to 相同，用 and 把 read 與 play the guitar 連起來。", "類似題：My brothers 複數 → like；過去式 wanted to、be going to 之後動詞都用原形。", "易錯：and 後面的動詞不可加 s 或 ing（如 and plays／and playing）。"]}, {"id": "C057", "src": "模擬試題第3回 Q6", "q": {"sents": ["Jack fixed the computer today.", "Jack also painted the living room today."], "stem": "Jack fixed ___ the living room today."}, "ans": "Jack fixed **the computer and painted** the living room today.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Mom cooks dinner every day.", "Mom also cleans the kitchen every day."], "stem": "Mom cooks ___ the kitchen every day.", "ans": "Mom cooks **dinner and cleans** the kitchen every day."}, {"tag": "第一人稱複數＋未來式", "sents": ["We will buy snacks tomorrow.", "We will also wash the car tomorrow."], "stem": "We will buy ___ the car tomorrow.", "ans": "We will buy **snacks and wash** the car tomorrow."}, {"tag": "複數主詞＋過去式", "sents": ["The students cleaned the classroom yesterday.", "They also watered the plants yesterday."], "stem": "The students cleaned ___ the plants yesterday.", "ans": "The students cleaned **the classroom and watered** the plants yesterday."}], "expl": ["句型：S + V1 + O1 + and + V2 + O2（and 連接兩個時態相同的動詞片語）。", "fixed 與 painted 都是過去式，用 and 連接，省略重複的主詞 Jack 和 today。", "類似題：Mom 單數 → cooks and cleans；will 之後兩個動詞都用原形 buy and wash。", "易錯：and 後動詞時態不一致（如 fixed…and paint）。"]}]}]}, {"name": "時間副詞子句（when／before／after／until）", "subs": [{"name": "when／until 時間子句", "sets": [{"id": "C026", "src": "附件8 Q6", "q": {"sents": ["We were in New York last Christmas.", "We went to several plays."], "stem": "When ___, ___."}, "ans": "When **we were in New York last Christmas**, **we went to several plays**.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["Lisa was in Tainan last summer.", "She ate a lot of snacks."], "stem": "When ___, ___.", "ans": "When **Lisa was in Tainan last summer**, **she ate a lot of snacks**."}, {"tag": "複數主詞＋現在式", "sents": ["My cousins visit us.", "We go to the night market."], "stem": "When ___, ___.", "ans": "When **my cousins visit us**, **we go to the night market**."}, {"tag": "未來式", "sents": ["I will get home.", "I will call you."], "stem": "When ___, ___.", "ans": "When **I get home**, **I will call you**."}], "expl": ["句型：When + S + V, S + V.（When 子句放句首要加逗號）", "時間點（在紐約時）放 When 子句，發生的事放主要子句。未來式時，When 子句要用現在式代替未來（I get home），主要子句才用 will。", "易錯：When I will get home, …（時間副詞子句不用 will）。"]}, {"id": "C060", "src": "模擬試題第3回 Q9", "q": {"sents": ["We waited.", "The store opened."], "stem": "___ until ___ ."}, "ans": "**We waited** until **the store opened**.", "variants": [{"tag": "第三人稱單數＋現在式（習慣）", "sents": ["Every day, Amy waits at the MRT station.", "Then, her mom picks her up."], "stem": "Every day, ___ until ___ .", "ans": "Every day, **Amy waits at the MRT station** until **her mom picks her up**."}, {"tag": "複數主詞＋過去式", "sents": ["The kids played outside.", "Then, it got dark."], "stem": "___ until ___ .", "ans": "**The kids played outside** until **it got dark**."}, {"tag": "第一人稱＋未來式", "sents": ["I will stay here.", "You will come back later."], "stem": "___ until ___ .", "ans": "**I will stay here** until **you come back**."}], "expl": ["句型：S + V（持續動作）+ until + S + V（動作停止的時間點）。", "一直等到商店開門：We waited until the store opened。", "類似題：Amy 單數 → waits／picks；未來式主要子句 will stay，until 子句用現在式 come back。", "易錯：until 子句用 will（until you will come back）；或 until 前後順序放反。"]}]}, {"name": "after 先後順序", "sets": [{"id": "C034", "src": "附件9 Q9", "q": {"sents": ["We had breakfast at home.", "Then we went to school."], "stem": "We ___ after ___."}, "ans": "We **went to school** after **we had breakfast at home**.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Amy does her homework.", "Then she watches TV."], "stem": "Amy ___ after ___.", "ans": "Amy **watches TV** after **she does her homework**."}, {"tag": "複數主詞＋過去式", "sents": ["The students cleaned the classroom.", "Then they went home."], "stem": "The students ___ after ___.", "ans": "The students **went home** after **they cleaned the classroom**."}, {"tag": "第一人稱＋未來式", "sents": ["I will finish dinner.", "Then I will take a shower."], "stem": "I ___ after ___.", "ans": "I **will take a shower** after **I finish dinner**."}], "expl": ["句型：S + V（後發生）+ after + S + V（先發生）。", "after 後放先做的事；也可寫 after having breakfast。未來式時 after 子句用現在式代未來：after I finish dinner。", "易錯：We had breakfast after we went to school（先後顛倒）；after I will finish。"]}, {"id": "C053", "src": "模擬試題第2回 Q7", "q": {"sents": ["Nick took a shower.", "Then, Nick called his mother."], "stem": "Nick ___ after ___ ."}, "ans": "Nick **called his mother** after **he took a shower**.", "variants": [{"tag": "第三人稱單數＋現在式（習慣）", "sents": ["Every day, Lily does her homework.", "Then, she watches TV."], "stem": "Every day, Lily ___ after ___ .", "ans": "Every day, Lily **watches TV** after **she does her homework**."}, {"tag": "複數主詞＋過去式", "sents": ["The players ate dinner.", "Then, they took the MRT home."], "stem": "The players ___ after ___ .", "ans": "The players **took the MRT home** after **they ate dinner**."}, {"tag": "第一人稱＋未來式", "sents": ["I will get home.", "Then, I will call you."], "stem": "I ___ after ___ .", "ans": "I **will call you** after **I get home**."}], "expl": ["句型：S + V（後發生）+ after + S + V（先發生）。", "先洗澡、再打電話，所以 after 後接先發生的 he took a shower（也可寫 taking a shower）。", "類似題：Lily 單數 → watches／does；未來式主要子句 will call，after 子句用現在式 get。", "易錯：與 before 相反，after 後面放「先發生」的動作。"]}, {"id": "C074", "src": "模擬試題第6回 Q8", "q": {"sents": ["Bill took the medicine.", "Then he felt much better."], "stem": "Bill ___ after he ___ ."}, "ans": "Bill **felt much better** after he **took the medicine**.", "variants": [{"tag": "複數主詞＋過去式", "sents": ["The kids finished their homework.", "Then they went to the night market."], "stem": "The kids ___ after they ___ .", "ans": "The kids **went to the night market** after they **finished their homework**."}, {"tag": "第三人稱單數＋現在式（習慣）", "sents": ["Grandma eats dinner.", "Then she takes a walk."], "stem": "Grandma ___ after she ___ .", "ans": "Grandma **takes a walk** after she **eats dinner**."}, {"tag": "第一人稱＋未來式", "sents": ["I will graduate.", "Then I will travel to Japan."], "stem": "I ___ after I ___ .", "ans": "I **will travel to Japan** after I **graduate**."}], "expl": ["句型：S + V（後發生）+ after + S + V（先發生）。", "先吃藥、後覺得好多了：after 後接 took the medicine。", "類似題：Grandma 單數 → takes／eats；未來式主要子句 will travel，after 子句用現在式 graduate。", "易錯：after 子句誤用 will（after I will graduate ✗）。"]}]}, {"name": "before 先後順序", "sets": [{"id": "C042", "src": "附件18 Q6", "q": {"sents": ["Kent showered.", "Then, Kent went to work."], "stem": "Kent ___ before ___."}, "ans": "Kent **showered** before **he went to work**.", "variants": [{"tag": "第一人稱＋現在式（習慣）", "sents": ["I brush my teeth.", "Then, I go to bed."], "stem": "I ___ before ___.", "ans": "I **brush my teeth** before **I go to bed**."}, {"tag": "複數主詞＋過去式", "sents": ["The students cleaned the classroom.", "Then, they went home."], "stem": "The students ___ before ___.", "ans": "The students **cleaned the classroom** before **they went home**."}, {"tag": "第三人稱單數＋未來式", "sents": ["Mom will buy some fruit.", "Then, she will take the MRT home."], "stem": "Mom ___ before ___.", "ans": "Mom **will buy some fruit** before **she takes the MRT home**."}], "expl": ["句型：S + V（先發生）+ before + S + V（後發生）。", "Kent 先洗澡、再上班，所以 before 後面接後發生的 he went to work（也可寫 going to work）。", "類似題：未來式時，主要子句用 will buy，但 before 子句用現在式 takes（時間副詞子句以現在式代替未來式）。", "易錯：before 後接的是「後發生」的動作，不要把順序寫反。"]}, {"id": "C050", "src": "模擬試題第1回 Q9", "q": {"sents": ["Julie fed her cat.", "Then, she went to work."], "stem": "Julie ___ before ___ ."}, "ans": "Julie **fed her cat** before **she went to work**.", "variants": [{"tag": "第三人稱單數＋現在式（習慣）", "sents": ["Every morning, Dad reads the newspaper.", "Then, he drinks coffee."], "stem": "Every morning, Dad ___ before ___ .", "ans": "Every morning, Dad **reads the newspaper** before **he drinks coffee**."}, {"tag": "複數主詞＋過去式", "sents": ["The kids washed their hands.", "Then, they ate lunch."], "stem": "The kids ___ before ___ .", "ans": "The kids **washed their hands** before **they ate lunch**."}, {"tag": "第一人稱＋未來式", "sents": ["I will finish my homework.", "Then, I will play video games."], "stem": "I ___ before ___ .", "ans": "I **will finish my homework** before **I play video games**."}], "expl": ["句型：S + V（先）+ before + S + V（後）。", "先餵貓、再上班，before 後接後發生的 she went to work（也可寫 going to work）。", "類似題：Dad 單數 → reads／drinks；未來式主要子句用 will finish，before 子句用現在式 play。", "易錯：before 子句用 will play 是錯的（時間副詞子句不用 will）。"]}, {"id": "C068", "src": "模擬試題第5回 Q7", "q": {"sents": ["The leaves turned yellow.", "Then they fell off."], "stem": "___ before they ___ ."}, "ans": "**The leaves turned yellow** before they **fell off**.", "variants": [{"tag": "複數主詞＋現在式（習慣）", "sents": ["The kids wash their hands.", "Then they eat lunch."], "stem": "___ before they ___ .", "ans": "**The kids wash their hands** before they **eat lunch**."}, {"tag": "第三人稱單數＋過去式", "sents": ["Ben looked both ways.", "Then he crossed the street."], "stem": "___ before he ___ .", "ans": "**Ben looked both ways** before he **crossed the street**."}, {"tag": "第一人稱複數＋未來式", "sents": ["We will buy tickets.", "Then we will take the MRT."], "stem": "___ before we ___ .", "ans": "**We will buy tickets** before we **take the MRT**."}], "expl": ["句型：S + V（先）+ before + S + V（後）。", "葉子先變黃、後掉落：fall 的過去式是 fell。", "類似題：he → crossed；未來式主要子句 will buy，before 子句用現在式 take。", "易錯：fall 過去式寫成 falled；before 子句誤用 will。"]}]}]}, {"name": "原因・結果・讓步（because／so／although／due to）", "subs": [{"name": "because／due to 原因", "sets": [{"id": "C014", "src": "附件3 Q9", "q": {"sents": ["I missed the train.", "I was late for work today."], "stem": "___ because ___."}, "ans": "**I was late for work today** because **I missed the train**.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["Tina got up late.", "She missed the school bus."], "stem": "___ because ___.", "ans": "**Tina missed the school bus** because **she got up late**."}, {"tag": "複數主詞＋現在式", "sents": ["There is no school today.", "The students are very happy."], "stem": "___ because ___.", "ans": "**The students are very happy** because **there is no school today**."}, {"tag": "未來式", "sents": ["A typhoon is coming tomorrow.", "We will stay at home tomorrow."], "stem": "___ because ___.", "ans": "**We will stay at home tomorrow** because **a typhoon is coming**."}], "expl": ["句型：結果 + because + 原因。", "先判斷因果：missed the train 是原因，所以放在 because 後面；兩個子句各自保留原本時態。", "易錯：because 和 so 不可同時使用；也別把因果顛倒（I missed the train because I was late）。"]}, {"id": "C017", "src": "附件5 Q7", "q": {"sents": ["It was windy.", "We couldn't play badminton."], "stem": "___ because ___."}, "ans": "**We couldn't play badminton** because **it was windy**.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["It is raining.", "Tom can't ride his bike."], "stem": "___ because ___.", "ans": "**Tom can't ride his bike** because **it is raining**."}, {"tag": "複數主詞＋過去式", "sents": ["The MRT was crowded.", "My friends didn't get a seat."], "stem": "___ because ___.", "ans": "**My friends didn't get a seat** because **the MRT was crowded**."}, {"tag": "未來式", "sents": ["It will be very cold tomorrow.", "I will wear a coat."], "stem": "___ because ___.", "ans": "**I will wear a coat tomorrow** because **it will be very cold**."}], "expl": ["句型：結果 + because + 原因。", "天氣（windy／raining／cold）是原因，放在 because 之後；兩子句時態各自保留。", "易錯：Because it was windy, so we couldn't…（because 與 so 不可並用）。"]}, {"id": "C020", "src": "附件5 Q10", "q": {"sents": ["Danny had a car accident.", "Danny had to go to the hospital."], "stem": "___ due to ___."}, "ans": "**Danny had to go to the hospital** due to **a car accident**.", "variants": [{"tag": "複數主詞＋現在式", "sents": ["There is a typhoon today.", "The schools are closed today."], "stem": "___ due to ___.", "ans": "**The schools are closed today** due to **the typhoon**."}, {"tag": "第一人稱＋過去式", "sents": ["I had a bad cold.", "I missed the English test."], "stem": "___ due to ___.", "ans": "**I missed the English test** due to **a bad cold**."}, {"tag": "第三人稱單數＋未來式", "sents": ["There will be heavy traffic.", "My dad will be late."], "stem": "___ due to ___.", "ans": "**My dad will be late** due to **heavy traffic**."}], "expl": ["句型：結果子句 + due to + 名詞片語（原因）。", "due to 是介系詞片語，後面只能接名詞，不能接完整句子，所以把 Danny had a car accident 縮成 a car accident；結果子句保留原時態。", "易錯：due to he had a car accident（接子句要改用 because）。"]}, {"id": "C058", "src": "模擬試題第3回 Q7", "q": {"sents": ["Danny hurt his knee.", "Danny has to stay in bed."], "stem": "Danny ___ because he ___ ."}, "ans": "Danny **has to stay in bed** because he **hurt his knee**.", "variants": [{"tag": "複數主詞＋過去式", "sents": ["The kids ate too much candy.", "They had a stomachache."], "stem": "The kids ___ because they ___ .", "ans": "The kids **had a stomachache** because they **ate too much candy**."}, {"tag": "第一人稱＋現在式", "sents": ["I have a test tomorrow.", "I need to study tonight."], "stem": "I ___ because I ___ .", "ans": "I **need to study tonight** because I **have a test tomorrow**."}, {"tag": "第三人稱單數＋未來式", "sents": ["Lisa missed the bus.", "She will be late for school."], "stem": "Lisa ___ because she ___ .", "ans": "Lisa **will be late for school** because she **missed the bus**."}], "expl": ["句型：S + V（結果）+ because + S + V（原因）。", "膝蓋受傷是原因，所以放在 because 後面；hurt 的過去式仍是 hurt。", "類似題：主詞 I → have／need（不加 s）；Lisa → will be（結果在未來，原因在過去）。", "易錯：把原因和結果放反；或寫 has to stays（has to 後接原形）。"]}]}, {"name": "Although 讓步", "sets": [{"id": "C035", "src": "附件9 Q10", "q": {"sents": ["The old man is rich.", "He feels lonely."], "stem": "Although ___, ___."}, "ans": "Although **the old man is rich**, **he feels lonely**.", "variants": [{"tag": "過去式", "sents": ["It rained hard.", "We still went to school."], "stem": "Although ___, ___.", "ans": "Although **it rained hard**, **we still went to school**."}, {"tag": "複數主詞", "sents": ["The students are tired.", "They keep studying."], "stem": "Although ___, ___.", "ans": "Although **the students are tired**, **they keep studying**."}, {"tag": "未來式", "sents": ["It may rain tomorrow.", "We will go hiking."], "stem": "Although ___, ___.", "ans": "Although **it may rain tomorrow**, **we will go hiking**."}], "expl": ["句型：Although + S + V, S + V.（雖然…，但…）", "Although 已表讓步，主要子句不可再加 but；各子句保留原時態：rained／are／will go。", "易錯：Although the old man is rich, but he feels lonely."]}, {"id": "C076", "src": "模擬試題第6回 Q10", "q": {"sents": ["It is cold.", "The boy is only wearing a T-shirt."], "stem": "Although ___ , ___ ."}, "ans": "Although **it is cold**, **the boy is only wearing a T-shirt**.", "variants": [{"tag": "過去式", "sents": ["It rained hard.", "We still went to the night market."], "stem": "Although ___ , ___ .", "ans": "Although **it rained hard**, **we still went to the night market**."}, {"tag": "第三人稱單數＋現在式", "sents": ["Amy is tired.", "She keeps studying."], "stem": "Although ___ , ___ .", "ans": "Although **Amy is tired**, **she keeps studying**."}, {"tag": "複數主詞＋未來式", "sents": ["The tickets are expensive.", "My parents will buy them."], "stem": "Although ___ , ___ .", "ans": "Although **the tickets are expensive**, **my parents will buy them**."}], "expl": ["句型：Although + S + V, S + V（雖然…，但…）。", "天氣冷卻只穿 T 恤，前後語意相反，用 although 連接。", "類似題：過去 rained／went；Amy 單數 → keeps；tickets 複數 → are，parents → will buy。", "易錯：although 和 but 不可同時使用（Although it is cold, but…✗）。"]}]}, {"name": "so 結果／if 條件", "sets": [{"id": "C059", "src": "模擬試題第3回 Q8", "q": {"sents": ["You eat too much.", "You get fat."], "stem": "You ___ if ___ ."}, "ans": "You **will get fat** if **you eat too much**.", "variants": [{"tag": "第三人稱單數", "sents": ["Tom stays up late.", "He feels tired the next day."], "stem": "Tom ___ if ___ .", "ans": "Tom **will feel tired** if **he stays up late**."}, {"tag": "複數主詞＋否定", "sents": ["The students don't study.", "They fail the test."], "stem": "The students ___ if ___ .", "ans": "The students **will fail the test** if **they don't study**."}, {"tag": "第一人稱複數＋天氣", "sents": ["It may rain tomorrow.", "We will stay home then."], "stem": "We ___ if ___ tomorrow.", "ans": "We **will stay home** if **it rains** tomorrow."}], "expl": ["句型：S + will + V（結果）+ if + S + V 現在式（條件）。", "吃太多是條件、變胖是結果，主要子句用 will get，if 子句用現在式 eat。", "類似題：Tom → stays（第三人稱單數加 s）；複數否定 → don't study；天氣 it → rains。", "易錯：if 子句寫 will（if you will eat）是錯的；if 子句用現在式代替未來式。"]}, {"id": "C071", "src": "模擬試題第5回 Q10", "q": {"sents": ["It's raining heavily now.", "The kids have to stay home."], "stem": "___ , so ___ ."}, "ans": "**It's raining heavily now**, so **the kids have to stay home**.", "variants": [{"tag": "過去式", "sents": ["The typhoon came yesterday.", "We had no school."], "stem": "___ , so ___ .", "ans": "**The typhoon came yesterday**, so **we had no school**."}, {"tag": "第三人稱單數＋現在式", "sents": ["Tom is sick today.", "He can't go to school."], "stem": "___ , so ___ .", "ans": "**Tom is sick today**, so **he can't go to school**."}, {"tag": "未來式", "sents": ["It will be hot tomorrow.", "We will go swimming."], "stem": "___ , so ___ .", "ans": "**It will be hot tomorrow**, so **we will go swimming**."}], "expl": ["句型：原因 + , so + 結果。", "下大雨是原因、待在家是結果，so 放在結果前；kids 複數 → have to。", "類似題：過去 came／had；Tom 單數 → is；未來 will be／will go。", "易錯：because 和 so 不可同時用在一句（Because it's raining, so…✗）。"]}]}]}, {"name": "so…that／such…that／too…to／enough to", "subs": [{"name": "such + a + N + that", "sets": [{"id": "C015", "src": "附件3 Q10", "q": {"sents": ["Jessie is a very generous girl.", "All of her friends like her."], "stem": "Jessie is ___.（用 such…that）"}, "ans": "Jessie is **such a generous girl that all of her friends like her**.", "variants": [{"tag": "過去式", "sents": ["It was a very hot day.", "We went swimming."], "stem": "It was ___.（用 such…that）", "ans": "It was **such a hot day that we went swimming**."}, {"tag": "複數主詞", "sents": ["They are very kind students.", "Everyone likes them."], "stem": "They are ___.（用 such…that）", "ans": "They are **such kind students that everyone likes them**."}, {"tag": "未來式", "sents": ["It will be a very interesting movie.", "Many people will go to see it."], "stem": "It will be ___.（用 such…that）", "ans": "It will be **such an interesting movie that many people will go to see it**."}], "expl": ["句型：such + a／an + adj. + 單數 N + that 子句；複數名詞前不加 a。", "去掉 very，換成 such；interesting 開頭母音 → an；kind students 為複數 → 不加 a。", "易錯：so a generous girl／such generous girl（漏 a）。"]}, {"id": "C023", "src": "附件6 Q8", "q": {"sents": ["There is a loud noise.", "I cannot sleep well at night."], "stem": "It is such ___ that ___ at night."}, "ans": "It is such **a loud noise** that **I cannot sleep well** at night.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["It was a very hot day.", "Tom could not sleep well at night."], "stem": "It was such ___ that ___ at night.", "ans": "It was such **a hot day** that **Tom could not sleep well** at night."}, {"tag": "複數主詞", "sents": ["They are very noisy dogs.", "The neighbors cannot sleep well at night."], "stem": "They are such ___ that ___ at night.", "ans": "They are such **noisy dogs** that **the neighbors cannot sleep well** at night."}, {"tag": "未來式", "sents": ["It will be a very long trip.", "We will arrive late at night."], "stem": "It will be such ___ that ___ at night.", "ans": "It will be such **a long trip** that **we will arrive late** at night."}], "expl": ["句型：S + be + such + (a／an) + adj. + N + that + S + V。", "such 修飾「形容詞＋名詞」；單數加 a，複數 noisy dogs 不加 a。that 子句保留原時態（cannot／could not／will arrive）。", "易錯：such loud noise（漏 a）／so a loud noise。原題 There is 改寫為 It is，屬題目指定。"]}, {"id": "C064", "src": "模擬試題第4回 Q8", "q": {"sents": ["It is a lovely day.", "We can have a picnic by the river."], "stem": "It is such ___ that ___ by the river."}, "ans": "It is such **a lovely day** that **we can have a picnic** by the river.", "variants": [{"tag": "過去式", "sents": ["It was a hot day.", "The kids went swimming in the river."], "stem": "It was such ___ that ___ in the river.", "ans": "It was such **a hot day** that **the kids went swimming** in the river."}, {"tag": "複數名詞（不加 a）", "sents": ["They are nice students.", "Everyone likes them."], "stem": "They are such ___ that ___ .", "ans": "They are such **nice students** that **everyone likes them**."}, {"tag": "第三人稱單數＋過去式＋一般動詞", "sents": ["Tom told a funny story.", "We laughed a lot."], "stem": "Tom told such ___ that ___ .", "ans": "Tom told such **a funny story** that **we laughed a lot**."}], "expl": ["句型：such + a/an + adj. + 單數名詞 + that + S + V（如此…以致於…）。", "such 後接名詞片語 a lovely day（so 後只接形容詞）。", "類似題：複數名詞 nice students 前不加 a；everyone 視為單數 → likes。", "易錯：寫成 such lovely day（漏 a）或 so a lovely day。"]}]}, {"name": "so + adj + that", "sets": [{"id": "C016", "src": "附件5 Q6", "q": {"sents": ["Jason was very tired.", "He fell asleep soon."], "stem": "Jason was so ___."}, "ans": "Jason was so **tired that he fell asleep soon**.", "variants": [{"tag": "第一人稱＋現在式", "sents": ["I am very hungry.", "I can eat two bowls of rice."], "stem": "I am so ___.", "ans": "I am so **hungry that I can eat two bowls of rice**."}, {"tag": "複數主詞＋過去式", "sents": ["The kids were very excited.", "They couldn't stop talking."], "stem": "The kids were so ___.", "ans": "The kids were so **excited that they couldn't stop talking**."}, {"tag": "未來式", "sents": ["The test will be very easy.", "Everyone will pass it."], "stem": "The test will be so ___.", "ans": "The test will be so **easy that everyone will pass it**."}], "expl": ["句型：S + be + so + adj. + that + S + V（如此…以致於…）。", "去掉 very，換成 so…that；that 子句保留原時態：fell／can／couldn't／will pass。", "易錯：so very tired／such tired that。"]}, {"id": "C033", "src": "附件9 Q8", "q": {"sents": ["Alice is very excited.", "Alice can't sleep."], "stem": "Alice is so ___ that ___."}, "ans": "Alice is so **excited** that **she can't sleep**.", "variants": [{"tag": "過去式", "sents": ["Tom was very tired.", "Tom couldn't walk."], "stem": "Tom was so ___ that ___.", "ans": "Tom was so **tired** that **he couldn't walk**."}, {"tag": "複數主詞", "sents": ["The kids are very happy.", "The kids can't stop singing."], "stem": "The kids are so ___ that ___.", "ans": "The kids are so **happy** that **they can't stop singing**."}, {"tag": "未來式", "sents": ["I will be very busy.", "I won't have time for lunch."], "stem": "I will be so ___ that ___.", "ans": "I will be so **busy** that **I won't have time for lunch**."}], "expl": ["句型：S + be + so + adj. + that + S + V。", "去掉 very；that 子句主詞用代名詞避免重複（Alice → she、the kids → they）；時態跟原句：can't／couldn't／won't。", "易錯：so very excited／so excited that can't sleep（漏主詞）。"]}, {"id": "C055", "src": "模擬試題第2回 Q9", "q": {"sents": ["The dog is very smart.", "It can answer the door."], "stem": "The dog is so ___ that ___ ."}, "ans": "The dog is so **smart** that **it can answer the door**.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["Amy was very tired.", "She fell asleep on the MRT."], "stem": "Amy was so ___ that ___ .", "ans": "Amy was so **tired** that **she fell asleep on the MRT**."}, {"tag": "複數主詞＋現在式", "sents": ["The students are very excited.", "They can't sit still."], "stem": "The students are so ___ that ___ .", "ans": "The students are so **excited** that **they can't sit still**."}, {"tag": "未來式", "sents": ["The typhoon will be very strong.", "We will have no school tomorrow."], "stem": "The typhoon will be so ___ that ___ .", "ans": "The typhoon will be so **strong** that **we will have no school tomorrow**."}], "expl": ["句型：S + be + so + adj. + that + S + V（如此…以致於…）。", "very 改成 so，that 後接完整句子 it can answer the door。", "類似題：過去式 was／fell；複數 are；未來 will be／will have。", "易錯：so 後面還保留 very（so very smart），或 that 後面漏主詞。"]}]}, {"name": "too + adj + to V", "sets": [{"id": "C045", "src": "附件18 Q9", "q": {"sents": ["The soup is very hot.", "Do not eat it now."], "stem": "The soup is ___ to ___."}, "ans": "The soup is **too hot** to **eat now**.", "variants": [{"tag": "過去式＋for 人", "sents": ["The box was very heavy.", "Lily couldn't carry it."], "stem": "The box was ___ for Lily to ___.", "ans": "The box was **too heavy** for Lily to **carry**."}, {"tag": "複數主詞＋現在式", "sents": ["These shoes are very small.", "I can't wear them."], "stem": "These shoes are ___ for me to ___.", "ans": "These shoes are **too small** for me to **wear**."}, {"tag": "人當主詞＋過去式", "sents": ["Grandpa was very tired.", "He couldn't walk to the MRT station."], "stem": "Grandpa was ___ to ___.", "ans": "Grandpa was **too tired** to **walk to the MRT station**."}], "expl": ["句型：S + be + too + adj. + (for 人) + to + V（太…而不能…）。", "too…to 本身已含否定，所以 to 後面直接用原形 eat，不再加 not。", "類似題：主詞是物時，to V 後不再加 it／them（不寫 too heavy to carry it）；be 動詞隨時態變 was／are。", "易錯：寫成 too hot to not eat 或 too hot to eat it。"]}]}]}, {"name": "比較級與同級比較", "subs": [{"name": "同級比較 as…as", "sets": [{"id": "C018", "src": "附件5 Q8", "q": {"sents": ["The chair is NT$ 500.", "The bed is NT$ 2000."], "stem": "___.（用 as expensive as 合併）"}, "ans": "**The chair is not as expensive as the bed.**", "variants": [{"tag": "過去式", "sents": ["The red shirt was NT$ 300.", "The blue shirt was NT$ 300."], "stem": "___.（用 as cheap as 合併）", "ans": "**The red shirt was as cheap as the blue shirt.**"}, {"tag": "複數主詞", "sents": ["These apples are NT$ 50.", "Those mangoes are NT$ 120."], "stem": "___.（用 as expensive as 合併）", "ans": "**These apples are not as expensive as those mangoes.**"}, {"tag": "未來式", "sents": ["Tomorrow will be 30°C.", "Today is 30°C."], "stem": "___.（用 as hot as 合併）", "ans": "**Tomorrow will be as hot as today.**"}], "expl": ["句型：A + be + (not) as + 原級 adj. + as + B。", "500 < 2000，所以椅子「沒有」床貴 → not as expensive as；價錢相同則用肯定 as…as。複數 apples → are；過去 → was；未來 → will be。", "易錯：as more expensive as（中間要用原級）；The bed is not as expensive as the chair（比較方向錯）。"]}, {"id": "C049", "src": "模擬試題第1回 Q8", "q": {"sents": ["Ivy is 150 cm tall.", "Alice is 150 cm tall, too."], "stem": "Ivy ___ as Alice."}, "ans": "Ivy **is as tall** as Alice.", "variants": [{"tag": "過去式", "sents": ["Last year, Ivy was 140 cm tall.", "Her brother was 140 cm tall, too."], "stem": "Last year, Ivy ___ as her brother.", "ans": "Last year, Ivy **was as tall** as her brother."}, {"tag": "複數主詞", "sents": ["These apples are NT$30 each.", "Those oranges are NT$30 each, too."], "stem": "These apples ___ as those oranges.", "ans": "These apples **are as expensive** as those oranges."}, {"tag": "否定＋第三人稱單數一般動詞", "sents": ["Ken runs fast.", "Ben runs faster than Ken."], "stem": "Ken ___ as Ben.", "ans": "Ken **doesn't run as fast** as Ben."}], "expl": ["句型：A + be + as + 形容詞原級 + as + B（A 和 B 一樣…）。", "兩人都是 150 公分，用同級比較 as tall as。", "類似題：過去 was；複數 apples → are；一般動詞否定 Ken → doesn't run as fast as（副詞原級）。", "易錯：as…as 中間用原級，不可寫 as taller as；否定句 doesn't 後動詞用原形 run。"]}]}, {"name": "副詞比較級 faster than", "sets": [{"id": "C025", "src": "附件6 Q10", "q": {"sents": ["George runs fast.", "Mary runs slowly."], "stem": "George ___ than Mary."}, "ans": "George **runs faster** than Mary.", "variants": [{"tag": "過去式", "sents": ["Kevin got up early.", "His brother got up late."], "stem": "Kevin ___ than his brother.", "ans": "Kevin **got up earlier** than his brother."}, {"tag": "複數主詞", "sents": ["My parents walk slowly.", "I walk fast."], "stem": "My parents ___ than I do.", "ans": "My parents **walk more slowly** than I do."}, {"tag": "未來式", "sents": ["Amy will study hard.", "Ben will not study hard."], "stem": "Amy ___ than Ben.", "ans": "Amy **will study harder** than Ben."}], "expl": ["句型：S + V + 副詞比較級 + than + O。", "fast → faster、early → earlier、hard → harder；-ly 副詞用 more：more slowly。動詞隨主詞時態：runs／got up／walk／will study。", "易錯：more faster／runs fast than。"]}]}, {"name": "形容詞比較級 -er than", "sets": [{"id": "C044", "src": "附件18 Q8", "q": {"sents": ["Angela's dress is size S.", "Betty's dress is size M."], "stem": "Betty's dress is ___ than Angela's."}, "ans": "Betty's dress is **bigger** than Angela's.", "variants": [{"tag": "複數主詞＋現在式", "sents": ["Tom's shoes are size 8.", "Ben's shoes are size 10."], "stem": "Ben's shoes are ___ than Tom's.", "ans": "Ben's shoes are **bigger** than Tom's."}, {"tag": "過去式", "sents": ["Yesterday's typhoon was very strong.", "Last week's typhoon was not so strong."], "stem": "Yesterday's typhoon was ___ than last week's.", "ans": "Yesterday's typhoon was **stronger** than last week's."}, {"tag": "未來式", "sents": ["Tomorrow will be 30°C.", "Today is 25°C."], "stem": "Tomorrow will be ___ than today.", "ans": "Tomorrow will be **hotter** than today."}], "expl": ["句型：A + be + 形容詞比較級 + than + B。", "M 號比 S 號大，所以用 bigger（也可用 larger）；Angela's 後省略 dress。", "類似題：複數主詞 shoes → are；過去 → was；未來 → will be，形容詞比較級不變。", "易錯：big → bigger、hot → hotter 要重複字尾子音；不可寫 more big。"]}, {"id": "C054", "src": "模擬試題第2回 Q8", "q": {"sents": ["Alice's bag cost NT$200.", "Susan's bag cost NT$500."], "stem": "Alice's bag ___ than Susan's."}, "ans": "Alice's bag **was cheaper** than Susan's.", "variants": [{"tag": "複數主詞＋現在式", "sents": ["Tom's sneakers are NT$1,500.", "Jim's sneakers are NT$900."], "stem": "Tom's sneakers ___ than Jim's.", "ans": "Tom's sneakers **are more expensive** than Jim's."}, {"tag": "第一人稱所有格＋現在式", "sents": ["My bike costs NT$3,000.", "My brother's bike costs NT$5,000."], "stem": "My bike ___ than my brother's.", "ans": "My bike **is cheaper** than my brother's."}, {"tag": "未來式", "sents": ["The new MRT line will be 20 km long.", "The old MRT line is 15 km long."], "stem": "The new MRT line ___ than the old one.", "ans": "The new MRT line **will be longer** than the old one."}], "expl": ["句型：A + be + 比較級 + than + B。", "200 元比 500 元便宜，cost 在此為過去式，所以 be 動詞用 was：was cheaper（也可寫 cost less）。", "類似題：sneakers 複數 → are more expensive（多音節形容詞用 more）；未來 → will be longer。", "易錯：寫成 more cheap；或時態寫成 is（原題 cost 為過去式）。"]}, {"id": "C062", "src": "模擬試題第4回 Q6", "q": {"sents": ["West Road is wide.", "Main Street is narrow."], "stem": "West Road ___ than Main Street."}, "ans": "West Road **is wider** than Main Street.", "variants": [{"tag": "過去式", "sents": ["The old park was small.", "The new park is big."], "stem": "The old park ___ than the new one.", "ans": "The old park **was smaller** than the new one."}, {"tag": "複數主詞", "sents": ["Taipei summers are hot.", "Taipei winters are cool."], "stem": "Taipei summers ___ than Taipei winters.", "ans": "Taipei summers **are hotter** than Taipei winters."}, {"tag": "第三人稱單數＋一般動詞＋副詞", "sents": ["Kevin runs fast.", "His brother runs slowly."], "stem": "Kevin ___ than his brother.", "ans": "Kevin **runs faster** than his brother."}], "expl": ["句型：A + be + 形容詞比較級 + than + B。", "wide 字尾是 e，比較級直接加 r：wider。", "類似題：過去 was smaller；複數 are hotter；一般動詞 runs + 副詞比較級 faster。", "易錯：漏掉 be 動詞（West Road wider than…）或寫 more wide。"]}]}]}, {"name": "關係代名詞與關係副詞（who／which／that／whose／where）", "subs": [{"name": "where／介系詞 + which", "sets": [{"id": "C004", "src": "附件1 Q9", "q": {"sents": ["This is the shop.", "I bought the phone here."], "stem": "This is ___ where ___ phone."}, "ans": "This is **the shop** where **I bought the** phone.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["That is the park.", "My grandpa walks his dog there every morning."], "stem": "That is ___ where ___ every morning.", "ans": "That is **the park** where **my grandpa walks his dog** every morning."}, {"tag": "複數主詞＋過去式", "sents": ["These are the classrooms.", "We studied in the classrooms last year."], "stem": "These are ___ where ___ last year.", "ans": "These are **the classrooms** where **we studied** last year."}, {"tag": "未來式", "sents": ["This is the hotel.", "My family will stay here during the trip."], "stem": "This is ___ where ___ during the trip.", "ans": "This is **the hotel** where **my family will stay** during the trip."}], "expl": ["句型：地方名詞 + where + S + V（where = in／at which）。", "where 已代替地點，所以要刪掉 here／there／in the classrooms。子句動詞依原句：grandpa → walks；過去 → studied；未來 → will stay。", "易錯：This is the shop where I bought the phone here.（地點重複）"]}, {"id": "C066", "src": "模擬試題第4回 Q10", "q": {"sents": ["The house is big.", "Mary lives in that house."], "stem": "The house in ___ is big."}, "ans": "The house in **which Mary lives** is big.", "variants": [{"tag": "複數主詞＋過去式", "sents": ["The rooms were clean.", "We stayed in those rooms."], "stem": "The rooms in ___ were clean.", "ans": "The rooms in **which we stayed** were clean."}, {"tag": "第三人稱單數＋現在式", "sents": ["The park is near my school.", "Tom plays basketball in that park."], "stem": "The park in ___ is near my school.", "ans": "The park in **which Tom plays basketball** is near my school."}, {"tag": "複數主詞＋未來式", "sents": ["The hotel is by the sea.", "They will stay in that hotel next week."], "stem": "The hotel in ___ is by the sea.", "ans": "The hotel in **which they will stay next week** is by the sea."}], "expl": ["句型：先行詞 + 介系詞 + which + S + V（= where + S + V）。", "in that house 的 that house 改成 which，介系詞 in 移到 which 前面。", "類似題：Tom → plays；They → will stay；先行詞 rooms 複數 → 主要動詞 were。", "易錯：介系詞後不可用 that（in that Mary lives ✗），也不可再重複 in（in which Mary lives in ✗）。"]}]}, {"name": "that 受格關代", "sets": [{"id": "C022", "src": "附件6 Q7", "q": {"sents": ["The dress is beautiful.", "Jenny is wearing that dress."], "stem": "The dress that ___ is beautiful."}, "ans": "The dress that **Jenny is wearing** is beautiful.", "variants": [{"tag": "過去式", "sents": ["The cake was delicious.", "My mom made the cake."], "stem": "The cake that ___ was delicious.", "ans": "The cake that **my mom made** was delicious."}, {"tag": "複數主詞", "sents": ["The books are interesting.", "We borrowed the books from the library."], "stem": "The books that ___ are interesting.", "ans": "The books that **we borrowed from the library** are interesting."}, {"tag": "未來式", "sents": ["The bike is expensive.", "My brother will buy the bike."], "stem": "The bike that ___ is expensive.", "ans": "The bike that **my brother will buy** is expensive."}], "expl": ["句型：N + that + S + V（that 當受詞的關係代名詞）。", "that 已代替 the dress，子句中要刪掉重複的受詞 that dress／the cake；主要動詞與先行詞一致：books → are。", "易錯：The dress that Jenny is wearing it is beautiful.（受詞重複）"]}]}, {"name": "whose 所有格", "sets": [{"id": "C030", "src": "附件8 Q10", "q": {"sents": ["I know a man.", "The man's sister is a pianist."], "stem": "I ___.（形容詞子句）"}, "ans": "I **know a man whose sister is a pianist**.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["She met a boy.", "The boy's father was a doctor."], "stem": "She ___.（形容詞子句）", "ans": "She **met a boy whose father was a doctor**."}, {"tag": "複數主詞", "sents": ["We have a teacher.", "The teacher's dog is very cute."], "stem": "We ___.（形容詞子句）", "ans": "We **have a teacher whose dog is very cute**."}, {"tag": "未來式", "sents": ["They will visit a girl.", "The girl's house is near the MRT station."], "stem": "They ___.（形容詞子句）", "ans": "They **will visit a girl whose house is near the MRT station**."}], "expl": ["句型：N + whose + N + V（whose 代替所有格 the man's）。", "The man's 換成 whose，後面緊接名詞 sister；子句動詞依原句：was／is。", "易錯：a man who his sister／a man whose the sister。"]}, {"id": "C032", "src": "附件9 Q7", "q": {"sents": ["I have a friend.", "My friend's father is a lawyer."], "stem": "I have ___ lawyer.（用 whose 連接）"}, "ans": "I have **a friend whose father is a** lawyer.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["Tom had a neighbor.", "His neighbor's son was a police officer."], "stem": "Tom had ___ police officer.（用 whose 連接）", "ans": "Tom had **a neighbor whose son was a** police officer."}, {"tag": "複數名詞", "sents": ["We have classmates.", "Our classmates' parents are teachers."], "stem": "We have ___ teachers.（用 whose 連接）", "ans": "We have **classmates whose parents are** teachers."}, {"tag": "未來式", "sents": ["She will meet a girl.", "The girl's mother is a singer."], "stem": "She will meet ___ singer.（用 whose 連接）", "ans": "She will meet **a girl whose mother is a** singer."}], "expl": ["句型：N + whose + N + V…", "My friend's 換成 whose；whose 後名詞決定動詞：father → is、parents → are、son（過去）→ was。", "易錯：a friend whose his father／複數 parents 仍寫 is a teacher。"]}]}]}, {"name": "名詞子句（whether／if／間接問句）", "subs": [{"name": "if／whether 是否", "sets": [{"id": "C019", "src": "附件5 Q9", "q": {"sents": ["Is the sofa comfortable to them?", "I'm not sure."], "stem": "I'm not sure ___."}, "ans": "I'm not sure **if the sofa is comfortable to them**.", "variants": [{"tag": "過去式", "sents": ["Was the movie interesting to Tom?", "I don't know."], "stem": "I don't know ___.", "ans": "I don't know **if the movie was interesting to Tom**."}, {"tag": "第三人稱＋複數名詞", "sents": ["Are the shoes too small for her?", "She isn't sure."], "stem": "She isn't sure ___.", "ans": "She isn't sure **if the shoes are too small for her**."}, {"tag": "複數主詞＋未來式", "sents": ["Will it rain tomorrow?", "We are not sure."], "stem": "We are not sure ___.", "ans": "We are not sure **if it will rain tomorrow**."}], "expl": ["句型：S + V + if／whether + S + V（間接問句用直述句語序）。", "Yes/No 問句改間接問句：加 if／whether，把 be／will 移回主詞後面：the sofa is／the movie was／the shoes are／it will rain。", "易錯：I'm not sure if is the sofa comfortable.（保留疑問句語序）"]}, {"id": "C021", "src": "附件6 Q6", "q": {"sents": ["Will Michael study English tonight?", "I wonder."], "stem": "I wonder whether ___ tonight."}, "ans": "I wonder whether **Michael will study English** tonight.", "variants": [{"tag": "過去式", "sents": ["Did Amy finish her homework last night?", "I wonder."], "stem": "I wonder whether ___ last night.", "ans": "I wonder whether **Amy finished her homework** last night."}, {"tag": "複數主詞＋現在式", "sents": ["Do your parents watch TV every night?", "I wonder."], "stem": "I wonder whether ___ every night.", "ans": "I wonder whether **your parents watch TV** every night."}, {"tag": "第三人稱＋現在完成式", "sents": ["Has he eaten dinner yet?", "She wonders."], "stem": "She wonders whether ___ yet.", "ans": "She wonders whether **he has eaten dinner** yet."}], "expl": ["句型：wonder whether + S + V（間接問句，直述句語序）。", "Will 移回主詞後：Michael will study；Did 問句去掉 did、動詞改過去式 finished；Do 問句去掉 do；Has 移到主詞後 he has eaten。", "易錯：whether will Michael study／whether did Amy finish。"]}, {"id": "C056", "src": "模擬試題第2回 Q10", "q": {"sents": ["Will Ted come?", "We are not sure."], "stem": "We are not sure whether ___ or not."}, "ans": "We are not sure whether **Ted will come** or not.", "variants": [{"tag": "過去式", "sents": ["Did Amy finish her homework?", "Her mother is not sure."], "stem": "Her mother is not sure whether ___ or not.", "ans": "Her mother is not sure whether **Amy finished her homework** or not."}, {"tag": "複數主詞＋現在式", "sents": ["Do the kids like stinky tofu?", "I am not sure."], "stem": "I am not sure whether ___ or not.", "ans": "I am not sure whether **the kids like stinky tofu** or not."}, {"tag": "be 動詞＋第三人稱主句", "sents": ["Is the MRT station far from here?", "Tom isn't sure."], "stem": "Tom isn't sure whether ___ or not.", "ans": "Tom isn't sure whether **the MRT station is far from here** or not."}], "expl": ["句型：S + be not sure + whether + S + V + or not。", "Yes/No 問句改名詞子句：Will Ted come → whether Ted will come（直述句語序）。", "類似題：Did Amy finish → Amy finished；Do the kids like → the kids like；Is the station → the station is。", "易錯：保留疑問句語序寫成 whether will Ted come。"]}, {"id": "C065", "src": "模擬試題第4回 Q9", "q": {"sents": ["Will Mark go to the concert tonight?", "I wonder."], "stem": "I wonder whether ___ tonight."}, "ans": "I wonder whether **Mark will go to the concert** tonight.", "variants": [{"tag": "過去式＋第三人稱主句", "sents": ["Did Amy take the MRT this morning?", "Her dad wonders."], "stem": "Her dad wonders whether ___ this morning.", "ans": "Her dad wonders whether **Amy took the MRT** this morning."}, {"tag": "複數主詞＋現在式", "sents": ["Are the kids at home now?", "We wonder."], "stem": "We wonder whether ___ now.", "ans": "We wonder whether **the kids are at home** now."}, {"tag": "第三人稱主句＋未來式", "sents": ["Will the students like the new teacher?", "Ms. Chen wonders."], "stem": "Ms. Chen wonders whether ___ .", "ans": "Ms. Chen wonders whether **the students will like the new teacher**."}], "expl": ["句型：S + wonder + whether + S + V（間接問句用直述句語序）。", "Will Mark go → Mark will go。", "類似題：Did Amy take → Amy took；Are the kids → the kids are；主句主詞單數 → wonders。", "易錯：寫成 whether will Mark go 或 whether Mark go。"]}, {"id": "C072", "src": "模擬試題第6回 Q6", "q": {"sents": ["Is the map useful to them?", "I'm not sure."], "stem": "I'm not sure if ___ to them."}, "ans": "I'm not sure if **the map is useful** to them.", "variants": [{"tag": "複數主詞＋過去式", "sents": ["Were the books helpful to Amy?", "Her teacher isn't sure."], "stem": "Her teacher isn't sure if ___ to Amy.", "ans": "Her teacher isn't sure if **the books were helpful** to Amy."}, {"tag": "一般動詞＋第三人稱單數", "sents": ["Does Ken like the gift?", "We're not sure."], "stem": "We're not sure if ___ .", "ans": "We're not sure if **Ken likes the gift**."}, {"tag": "未來式", "sents": ["Will the new MRT line be open next year?", "Dad isn't sure."], "stem": "Dad isn't sure if ___ next year.", "ans": "Dad isn't sure if **the new MRT line will be open** next year."}], "expl": ["句型：S + be not sure + if + S + V（if = whether，表「是否」）。", "Is the map useful → the map is useful（直述句語序）。", "類似題：Were the books → the books were；Does Ken like → Ken likes（去掉 does，動詞加 s）；Will…be → will be。", "易錯：寫成 if is the map useful 或 if Ken does like。"]}]}, {"name": "疑問詞間接問句 how", "sets": [{"id": "C051", "src": "模擬試題第1回 Q10", "q": {"sents": ["How well did John do on the test?", "I don't know."], "stem": "I don't know how ___ on the test."}, "ans": "I don't know how **well John did** on the test.", "variants": [{"tag": "複數主詞＋第三人稱主句", "sents": ["How well did the students do on the test?", "Ms. Lee doesn't know."], "stem": "Ms. Lee doesn't know how ___ on the test.", "ans": "Ms. Lee doesn't know how **well the students did** on the test."}, {"tag": "現在式＋第三人稱單數", "sents": ["How well does Amy sing?", "I don't know."], "stem": "I don't know how ___ .", "ans": "I don't know how **well Amy sings**."}, {"tag": "未來式", "sents": ["How well will our team play tomorrow?", "We don't know."], "stem": "We don't know how ___ tomorrow.", "ans": "We don't know how **well our team will play** tomorrow."}], "expl": ["句型：S + V + how well + S + V（間接問句用直述句語序）。", "did John do → 去掉助動詞 did，動詞改過去式 did：how well John did。", "類似題：does Amy sing → Amy sings；will our team play → our team will play。", "易錯：寫成 how well did John do（保留疑問句語序）。"]}, {"id": "C067", "src": "模擬試題第5回 Q6", "q": {"sents": ["How far is the hotel?", "We have no idea."], "stem": "We have no idea how far ___ ."}, "ans": "We have no idea how far **the hotel is**.", "variants": [{"tag": "第三人稱主句＋過去式", "sents": ["How far did Tom walk?", "His mom has no idea."], "stem": "His mom has no idea how far ___ .", "ans": "His mom has no idea how far **Tom walked**."}, {"tag": "複數主詞＋現在式", "sents": ["How old are those trees?", "I have no idea."], "stem": "I have no idea how old ___ .", "ans": "I have no idea how old **those trees are**."}, {"tag": "未來式", "sents": ["How long will the typhoon stay?", "Nobody has any idea."], "stem": "Nobody has any idea how long ___ .", "ans": "Nobody has any idea how long **the typhoon will stay**."}], "expl": ["句型：have no idea + 疑問詞 + S + V（直述句語序）。", "is the hotel → the hotel is，be 動詞移到句尾。", "類似題：did Tom walk → Tom walked；are those trees → those trees are；will the typhoon stay → the typhoon will stay。", "易錯：寫成 how far is the hotel（保留疑問句語序）。"]}]}]}, {"name": "動名詞與不定詞（enjoy Ving／forget to V／by Ving／without Ving／prefer）", "subs": [{"name": "介系詞 + Ving (by/for)", "sets": [{"id": "C005", "src": "附件1 Q10", "q": {"sents": ["Sam went to bed.", "He didn't take a shower."], "stem": "Sam went ___ without ___."}, "ans": "Sam went **to bed** without **taking a shower**.", "variants": [{"tag": "第一人稱＋現在式", "sents": ["I often go to school.", "I don't eat breakfast."], "stem": "I often go ___ without ___.", "ans": "I often go **to school** without **eating breakfast**."}, {"tag": "複數主詞＋過去式", "sents": ["They left the classroom.", "They didn't say goodbye."], "stem": "They left ___ without ___.", "ans": "They left **the classroom** without **saying goodbye**."}, {"tag": "第三人稱單數＋未來式", "sents": ["She will go out.", "She won't bring an umbrella."], "stem": "She will go ___ without ___.", "ans": "She will go **out** without **bringing an umbrella**."}], "expl": ["句型：S + V… + without + Ving（沒有做…就…）。", "without 本身已含否定，後接動名詞；時態只看主要動詞（went／go／left／will go），without 後永遠是 Ving。", "易錯：without take／without didn't take a shower。"]}, {"id": "C012", "src": "附件3 Q7", "q": {"sents": ["Sandy has to study English.", "Sandy has to study Spanish."], "stem": "In addition to ___, ___."}, "ans": "In addition to **studying English**, **Sandy has to study Spanish**.", "variants": [{"tag": "過去式", "sents": ["Ken had to clean the classroom.", "Ken had to wash the windows."], "stem": "In addition to ___, ___.", "ans": "In addition to **cleaning the classroom**, **Ken had to wash the windows**."}, {"tag": "複數主詞", "sents": ["My parents sell fruit at the night market.", "My parents sell drinks at the night market."], "stem": "In addition to ___, ___.", "ans": "In addition to **selling fruit**, **my parents sell drinks at the night market**."}, {"tag": "第一人稱＋未來式", "sents": ["I will visit my grandma this weekend.", "I will visit my uncle this weekend."], "stem": "In addition to ___, ___.", "ans": "In addition to **visiting my grandma**, **I will visit my uncle this weekend**."}], "expl": ["句型：In addition to + Ving／N, S + V…（除了…之外，還…）。", "in addition to 的 to 是介系詞，後接動名詞；主要子句保留原時態：has to／had to／sell／will visit。", "易錯：In addition to study English…（to 後誤用原形）"]}, {"id": "C070", "src": "模擬試題第5回 Q9", "q": {"sents": ["Sam got a good grade.", "Sam prepared for the test early."], "stem": "Sam got a good grade by ___ early."}, "ans": "Sam got a good grade by **preparing for the test** early.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Amy saves money.", "She takes the MRT to school."], "stem": "Amy saves money by ___ to school.", "ans": "Amy saves money by **taking the MRT** to school."}, {"tag": "複數主詞＋過去式", "sents": ["The kids learned English.", "They watched cartoons."], "stem": "The kids learned English by ___ .", "ans": "The kids learned English by **watching cartoons**."}, {"tag": "第一人稱＋未來式", "sents": ["I will stay healthy.", "I will jog every morning."], "stem": "I will stay healthy by ___ every morning.", "ans": "I will stay healthy by **jogging** every morning."}], "expl": ["句型：S + V + by + Ving（藉由…方法）。", "介系詞 by 後接動名詞：prepared → preparing。", "類似題：主要動詞 saves／learned／will stay 隨主詞時態變，by 後一律 Ving（take → taking，jog → jogging 重複 g）。", "易錯：寫成 by prepared 或 by prepare。"]}, {"id": "C073", "src": "模擬試題第6回 Q7", "q": {"sents": ["You came to my party.", "Thank you."], "stem": "Thank you for ___ to my party."}, "ans": "Thank you for **coming** to my party.", "variants": [{"tag": "第三人稱主詞＋過去式", "sents": ["Amy helped her friend.", "Her friend thanked her."], "stem": "Her friend thanked Amy for ___ her.", "ans": "Her friend thanked Amy for **helping** her."}, {"tag": "複數受詞＋過去式", "sents": ["The students cleaned the park.", "The mayor thanked them."], "stem": "The mayor thanked the students for ___ the park.", "ans": "The mayor thanked the students for **cleaning** the park."}, {"tag": "第一人稱＋未來式", "sents": ["Ben gave me a ride.", "I will thank him."], "stem": "I will thank Ben for ___ me a ride.", "ans": "I will thank Ben for **giving** me a ride."}], "expl": ["句型：thank + 人 + for + Ving（感謝某人做了某事）。", "介系詞 for 後接動名詞：came → coming（去 e 加 ing）。", "類似題：thanked／will thank 隨時態變，for 後一律 Ving（give → giving）。", "易錯：寫成 for came／for come／for to come。"]}]}, {"name": "enjoy／prefer + Ving", "sets": [{"id": "C011", "src": "附件3 Q6", "q": {"sents": ["I like to swim.", "I don't like to play baseball."], "stem": "I prefer ___."}, "ans": "I prefer **swimming to playing baseball**.", "variants": [{"tag": "第三人稱單數", "sents": ["My sister likes to read comic books.", "She doesn't like to watch TV."], "stem": "My sister prefers ___.", "ans": "My sister prefers **reading comic books to watching TV**."}, {"tag": "複數主詞＋過去式", "sents": ["They liked to take the MRT.", "They didn't like to take the bus."], "stem": "They preferred ___.", "ans": "They preferred **taking the MRT to taking the bus**."}, {"tag": "第三人稱單數＋現在完成式", "sents": ["He has always liked to ride a bike.", "He has never liked to walk."], "stem": "He has always preferred ___.", "ans": "He has always preferred **riding a bike to walking**."}], "expl": ["句型：prefer + Ving + to + Ving（比較喜歡 A 勝過 B）。", "to 在此是介系詞，兩邊都用 Ving；也可說 I prefer to swim rather than play baseball。prefer 本身隨主詞時態變化：prefers／preferred／has preferred。", "易錯：prefer swimming than playing（than 錯）；prefer swimming to play（to 後不接原形）。"]}, {"id": "C028", "src": "附件8 Q8", "q": {"sents": ["He enjoys something.", "He has a cup of coffee in the afternoon."], "stem": "He enjoys ___."}, "ans": "He enjoys **having a cup of coffee in the afternoon**.", "variants": [{"tag": "第一人稱＋過去式", "sents": ["I enjoyed something.", "I rode a bike by the river last Sunday."], "stem": "I enjoyed ___.", "ans": "I enjoyed **riding a bike by the river last Sunday**."}, {"tag": "複數主詞", "sents": ["My grandparents enjoy something.", "They take a walk in the park every morning."], "stem": "My grandparents enjoy ___.", "ans": "My grandparents enjoy **taking a walk in the park every morning**."}, {"tag": "未來式", "sents": ["She will enjoy something.", "She will visit the night market in Taipei."], "stem": "She will enjoy ___.", "ans": "She will enjoy **visiting the night market in Taipei**."}], "expl": ["句型：enjoy + Ving。", "S2 的動詞改成動名詞代替 something：has → having、rode → riding、take → taking；時態只表現在 enjoy 上。", "易錯：enjoys to have／enjoys has。"]}]}, {"name": "forget to V", "sets": [{"id": "C024", "src": "附件6 Q9", "q": {"sents": ["Alice does her homework every day.", "Alice didn't do her homework yesterday."], "stem": "Alice forgot ___ yesterday."}, "ans": "Alice forgot **to do her homework** yesterday.", "variants": [{"tag": "第一人稱＋過去式", "sents": ["I usually bring my lunch.", "I didn't bring my lunch today."], "stem": "I forgot ___ today.", "ans": "I forgot **to bring my lunch** today."}, {"tag": "複數主詞＋過去式", "sents": ["The students lock the door every day.", "They didn't lock the door last night."], "stem": "The students forgot ___ last night.", "ans": "The students forgot **to lock the door** last night."}, {"tag": "第三人稱單數＋現在式", "sents": ["My sister should take her umbrella.", "She often doesn't take it."], "stem": "My sister often forgets ___.", "ans": "My sister often forgets **to take her umbrella**."}], "expl": ["句型：forget + to V（忘記去做，事情沒做）。", "「沒做」用 forget to V；forget + Ving 是「忘記做過某事」。forget 隨主詞時態變化：forgot／forgets，to V 不變。", "易錯：Alice forgot doing her homework（意思變成忘了做過）。"]}, {"id": "C063", "src": "模擬試題第4回 Q7", "q": {"sents": ["Steve feeds his dog every day.", "Steve didn't feed his dog yesterday."], "stem": "Steve forgot ___ his dog yesterday."}, "ans": "Steve forgot **to feed** his dog yesterday.", "variants": [{"tag": "第一人稱＋過去式", "sents": ["I bring my lunch every day.", "I didn't bring my lunch this morning."], "stem": "I forgot ___ my lunch this morning.", "ans": "I forgot **to bring** my lunch this morning."}, {"tag": "複數主詞＋過去式", "sents": ["The students do their homework every day.", "They didn't do their homework last night."], "stem": "The students forgot ___ their homework last night.", "ans": "The students forgot **to do** their homework last night."}, {"tag": "第三人稱單數＋現在完成式", "sents": ["Dad usually turns off the lights.", "Dad hasn't turned off the lights today."], "stem": "Dad has forgotten ___ the lights today.", "ans": "Dad has forgotten **to turn off** the lights today."}], "expl": ["句型：forget + to V（忘記去做，事情沒做）／forget + Ving（忘記做過）。", "Steve 昨天沒餵狗 → 忘了去做 → forgot to feed。", "類似題：forgot／has forgotten 隨時態變，但 to 後一律原形。", "易錯：寫成 forgot feeding（意思變成「忘了已經餵過」）。"]}]}, {"name": "teach + 人 + how to V", "sets": [{"id": "C061", "src": "模擬試題第3回 Q10", "q": {"sents": ["Lisa made cookies.", "Her mother taught Lisa how."], "stem": "Lisa's mother taught her ___ cookies."}, "ans": "Lisa's mother taught her **how to make** cookies.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Tom rides a bike.", "His father teaches Tom how."], "stem": "Tom's father teaches him ___ a bike.", "ans": "Tom's father teaches him **how to ride** a bike."}, {"tag": "複數受詞＋未來式", "sents": ["The kids will swim.", "Mr. Lin will teach the kids how."], "stem": "Mr. Lin will teach them ___ .", "ans": "Mr. Lin will teach them **how to swim**."}, {"tag": "第一人稱受詞＋過去式", "sents": ["I cooked fried rice.", "My grandma taught me how."], "stem": "My grandma taught me ___ fried rice.", "ans": "My grandma taught me **how to cook** fried rice."}], "expl": ["句型：S + teach + 人 + how + to V（教某人如何…）。", "made 是 make 的過去式，how to 後面一定用原形 make。", "類似題：teaches／will teach／taught 隨主詞與時態變化，但 how to 後的動詞永遠用原形。", "易錯：寫成 how to made 或 how making。"]}]}]}, {"name": "感官動詞・使役動詞・ask sb to V", "subs": [{"name": "感官動詞 see + O + Ving", "sets": [{"id": "C002", "src": "附件1 Q7", "q": {"sents": ["I saw him.", "He was cheating on the test."], "stem": "I saw him ___ test."}, "ans": "I saw him **cheating on the** test.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["She heard her brother.", "Her brother was singing in the bathroom."], "stem": "She heard her brother ___ bathroom.", "ans": "She heard her brother **singing in the** bathroom."}, {"tag": "複數受詞＋現在式", "sents": ["We often see the students.", "The students are playing basketball after school."], "stem": "We often see the students ___ after school.", "ans": "We often see the students **playing basketball** after school."}, {"tag": "未來式", "sents": ["You will see the dancers.", "The dancers will be dancing on the stage."], "stem": "You will see the dancers ___ stage.", "ans": "You will see the dancers **dancing on the** stage."}], "expl": ["句型：感官動詞 see／hear／watch + O + Ving（強調正在進行）。", "合併時刪去 be 動詞（was／are／will be），保留 Ving；時態只表現在感官動詞上（saw／see／will see）。", "易錯：I saw him was cheating.／I saw him to cheat.（感官動詞後不接 to V）"]}]}, {"name": "ask／advise + O + to V", "sets": [{"id": "C013", "src": "附件3 Q8", "q": {"sents": ["My mother advises me.", "I should do my homework well."], "stem": "My mother advises me ___."}, "ans": "My mother advises me **to do my homework well**.", "variants": [{"tag": "過去式", "sents": ["The teacher told us.", "We should be quiet in the library."], "stem": "The teacher told us ___.", "ans": "The teacher told us **to be quiet in the library**."}, {"tag": "複數主詞", "sents": ["My parents ask my brother.", "He should go to bed early."], "stem": "My parents ask my brother ___.", "ans": "My parents ask my brother **to go to bed early**."}, {"tag": "未來式", "sents": ["Dad will ask me.", "I should take an umbrella."], "stem": "Dad will ask me ___.", "ans": "Dad will ask me **to take an umbrella**."}], "expl": ["句型：advise／ask／tell + O + to V。", "把 should 去掉，改成 to + 原形動詞；時態只表現在 advises／told／ask／will ask 上，to V 不變。", "易錯：advises me do my homework／advises me to doing。"]}, {"id": "C031", "src": "附件9 Q6", "q": {"sents": ["Peter took out the trash.", "I asked him to do it."], "stem": "I asked Peter ___ trash."}, "ans": "I asked Peter **to take out the** trash.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["My brother washes the dishes.", "Mom asks him to do it."], "stem": "Mom asks my brother ___ dishes.", "ans": "Mom asks my brother **to wash the** dishes."}, {"tag": "複數受詞＋過去式", "sents": ["The students cleaned the classroom.", "The teacher asked them to do it."], "stem": "The teacher asked the students ___ classroom.", "ans": "The teacher asked the students **to clean the** classroom."}, {"tag": "未來式", "sents": ["Amy will feed the cat.", "I will ask her to do it."], "stem": "I will ask Amy ___ cat.", "ans": "I will ask Amy **to feed the** cat."}], "expl": ["句型：ask + O + to V（要求某人去做…）。", "do it 指的是 S1 的動作，換成 to + 原形（to take out）；時態只在 ask 上：asked／asks／will ask。", "易錯：asked Peter took out／asked Peter taking out。"]}]}]}, {"name": "現在完成式", "subs": [{"name": "現在完成式 for 一段時間", "sets": [{"id": "C046", "src": "附件18 Q10", "q": {"sents": ["George started learning English two years ago.", "George is still learning English now."], "stem": "___.（用現在完成式）"}, "ans": "**George has learned English for two years**.", "variants": [{"tag": "複數主詞＋for", "sents": ["My parents moved to Taipei ten years ago.", "They still live in Taipei now."], "stem": "___.（用現在完成式）", "ans": "**My parents have lived in Taipei for ten years**."}, {"tag": "第一人稱＋since", "sents": ["I started playing the piano in 2020.", "I still play the piano now."], "stem": "___.（用現在完成式）", "ans": "**I have played the piano since 2020**."}, {"tag": "第三人稱單數＋be 動詞（has been）＋since", "sents": ["Amy got sick last Monday.", "She is still sick now."], "stem": "___.（用現在完成式）", "ans": "**Amy has been sick since last Monday**."}], "expl": ["句型：S + have/has + Vpp + for + 一段時間／since + 過去時間點。", "從兩年前開始到現在仍在學，用現在完成式 has learned（也可用 has been learning）+ for two years。", "類似題：複數 My parents、I → have；Amy → has；be 動詞的 p.p. 是 been。", "易錯：for 接一段時間、since 接時間點，不可寫 for two years ago。"]}]}]}, {"name": "五大句型與介系詞片語合併（call／find／believe／with／for）", "subs": [{"name": "後位修飾 with／in", "sets": [{"id": "C003", "src": "附件1 Q8", "q": {"sents": ["He likes a girl.", "A girl has long hair."], "stem": "He likes ___ with ___."}, "ans": "He likes **a girl** with **long hair**.", "variants": [{"tag": "第一人稱＋過去式", "sents": ["I met a boy.", "The boy had a big smile."], "stem": "I met ___ with ___.", "ans": "I met **a boy** with **a big smile**."}, {"tag": "複數主詞＋現在式", "sents": ["They live in a house.", "The house has a small garden."], "stem": "They live in ___ with ___.", "ans": "They live in **a house** with **a small garden**."}, {"tag": "第三人稱單數＋未來式", "sents": ["She will buy a bag.", "The bag has two pockets."], "stem": "She will buy ___ with ___.", "ans": "She will buy **a bag** with **two pockets**."}], "expl": ["句型：N + with + N（with 表「帶有…」，= who／which has…）。", "with 是介系詞，後面直接接名詞，不需動詞 has／had，所以主要動詞時態改變（met／live／will buy）不影響 with 片語。", "原題 S2 寫作 A girl，依句意應為 The girl（指同一個女孩）。易錯：with has long hair。"]}, {"id": "C038", "src": "附件16 Q3", "q": {"sents": ["I hate something in that restaurant.", "The thing which I hate is its loud music."], "stem": "I hate the ___."}, "ans": "I hate the **loud music in that restaurant**.", "variants": [{"tag": "第三人稱單數＋過去式", "sents": ["She loved something in that hotel.", "The thing which she loved was its big pool."], "stem": "She loved the ___.", "ans": "She loved the **big pool in that hotel**."}, {"tag": "複數主詞", "sents": ["We like something in this park.", "The thing which we like is its tall trees."], "stem": "We like the ___.", "ans": "We like the **tall trees in this park**."}, {"tag": "未來式", "sents": ["You will enjoy something at the night market.", "The thing which you will enjoy is its delicious food."], "stem": "You will enjoy the ___.", "ans": "You will enjoy the **delicious food at the night market**."}], "expl": ["句型：S + V + the + N + 介系詞片語（in／at + 地點）。", "把 something 換成 S2 的具體名詞（loud music），its 改成 the，再接 in that restaurant 說明地點；動詞時態依 S1：hate／loved／will enjoy。", "易錯：I hate the its loud music（the 與 its 並用）。"]}]}, {"name": "V + 物 + for + 人", "sets": [{"id": "C029", "src": "附件8 Q9", "q": {"sents": ["John bought a book.", "The book is for his mother."], "stem": "___."}, "ans": "**John bought a book for his mother.**", "variants": [{"tag": "第一人稱＋現在式", "sents": ["I make breakfast.", "The breakfast is for my family."], "stem": "___.", "ans": "**I make breakfast for my family.**"}, {"tag": "複數主詞＋過去式", "sents": ["The students made a card.", "The card was for their teacher."], "stem": "___.", "ans": "**The students made a card for their teacher.**"}, {"tag": "未來式", "sents": ["My dad will cook dinner.", "The dinner is for us."], "stem": "___.", "ans": "**My dad will cook dinner for us.**"}], "expl": ["句型：S + buy／make／cook + 物 + for + 人（= S + V + 人 + 物）。", "把 S2 的「for + 人」接到 S1 後面即可，時態依 S1：bought／make／made／will cook。", "易錯：John bought a book to his mother（buy／make／cook 用 for，不用 to）。"]}, {"id": "C037", "src": "附件16 Q2", "q": {"sents": ["My aunt will choose a pink dress.", "Little Jenny wants one."], "stem": "My aunt will ___.（用介系詞 for 合併）"}, "ans": "My aunt will **choose a pink dress for little Jenny**.", "variants": [{"tag": "過去式", "sents": ["My mom bought a new bike.", "My brother wanted one."], "stem": "My mom ___.（用介系詞 for 合併）", "ans": "My mom **bought a new bike for my brother**."}, {"tag": "複數主詞＋現在式", "sents": ["My parents make a cake every year.", "My sister wants one."], "stem": "My parents ___.（用介系詞 for 合併）", "ans": "My parents **make a cake for my sister every year**."}, {"tag": "第一人稱＋現在完成式", "sents": ["I have made a card.", "My teacher wants one."], "stem": "I ___.（用介系詞 for 合併）", "ans": "I **have made a card for my teacher**."}], "expl": ["句型：S + V + 物 + for + 人（choose／buy／make sth for sb）。", "S2 只說明「為誰」，用 for + 人接在受詞後；動詞依 S1 時態：will choose／bought／make／have made。", "易錯：choose a pink dress to little Jenny（choose／buy／make 搭 for）。"]}]}, {"name": "介系詞片語 at／from／of", "sets": [{"id": "C036", "src": "附件16 Q1", "q": {"sents": ["Mandy met her childhood friend yesterday.", "Mandy met her at the party."], "stem": "Mandy ___."}, "ans": "Mandy **met her childhood friend at the party yesterday**.", "variants": [{"tag": "第一人稱＋現在式", "sents": ["I see my best friend every day.", "I see her at school."], "stem": "I ___.", "ans": "I **see my best friend at school every day**."}, {"tag": "複數主詞＋過去式", "sents": ["They watched a movie last night.", "They watched it at the theater."], "stem": "They ___.", "ans": "They **watched a movie at the theater last night**."}, {"tag": "未來式", "sents": ["My uncle will meet us tomorrow.", "He will meet us at the MRT station."], "stem": "My uncle ___.", "ans": "My uncle **will meet us at the MRT station tomorrow**."}], "expl": ["句型：S + V + O + 地方介系詞片語 + 時間副詞。", "把 S2 的地點片語（at the party）插入受詞之後，時間（yesterday）放句尾；英文順序「先地方、後時間」。", "易錯：met her childhood friend yesterday at the party（時地顛倒）／重複寫 met her。"]}, {"id": "C048", "src": "模擬試題第1回 Q7", "q": {"sents": ["Tommy has friends.", "Ben is Tommy's friend."], "stem": "Ben ___ one of ___ ."}, "ans": "Ben **is** one of **Tommy's friends**.", "variants": [{"tag": "過去式", "sents": ["Mr. Lin had students.", "Kevin was Mr. Lin's student."], "stem": "Kevin ___ one of ___ .", "ans": "Kevin **was** one of **Mr. Lin's students**."}, {"tag": "未來式", "sents": ["Our school will have new teachers.", "Ms. Wu will be a new teacher at our school."], "stem": "Ms. Wu ___ one of ___ .", "ans": "Ms. Wu **will be** one of **the new teachers at our school**."}, {"tag": "複數主詞（two of）", "sents": ["Mrs. Chen has many students.", "Tom and Joe are Mrs. Chen's students."], "stem": "Tom and Joe ___ two of ___ .", "ans": "Tom and Joe **are** two of **Mrs. Chen's students**."}], "expl": ["句型：S + be + one of + 所有格 + 複數名詞（…之一）。", "Ben 是 Tommy 眾多朋友之一，one of 後面要接複數 friends。", "類似題：過去式 was；未來式 will be；主詞 Tom and Joe 為複數 → are two of。", "易錯：寫成 one of Tommy's friend（名詞沒加 s）。"]}, {"id": "C075", "src": "模擬試題第6回 Q9", "q": {"sents": ["Jay borrowed the book.", "The book is his brother's."], "stem": "Jay borrowed ___ his brother."}, "ans": "Jay borrowed **the book from** his brother.", "variants": [{"tag": "複數主詞＋現在式", "sents": ["The students borrow books.", "The books are the library's."], "stem": "The students borrow ___ the library.", "ans": "The students borrow **books from** the library."}, {"tag": "第一人稱＋未來式", "sents": ["I will borrow the umbrella.", "The umbrella is Amy's."], "stem": "I will borrow ___ Amy.", "ans": "I will borrow **the umbrella from** Amy."}, {"tag": "第三人稱單數＋過去式（lend…to 對比）", "sents": ["Tom lent a pen.", "He gave it to me for a short time."], "stem": "Tom lent ___ me.", "ans": "Tom lent **a pen to** me."}], "expl": ["句型：borrow + 物 + from + 人（向某人借入）；lend + 物 + to + 人（借出給某人）。", "書是哥哥的，所以 Jay 向哥哥借：borrowed the book from his brother。", "類似題：複數 students → borrow；未來 will borrow；lend 的過去式是 lent，介系詞用 to。", "易錯：borrow 後用 to（borrowed the book to ✗），或把 borrow／lend 用反。"]}]}, {"name": "受詞補語 call／find／believe", "sets": [{"id": "C039", "src": "附件16 Q4", "q": {"sents": ["Our big dog's name is Bear.", "We always call him so."], "stem": "We ___.（用 call 合併）"}, "ans": "We **always call our big dog Bear**.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Her cat's name is Mimi.", "Amy always calls it so."], "stem": "Amy ___.（用 call 合併）", "ans": "Amy **always calls her cat Mimi**."}, {"tag": "複數主詞＋過去式", "sents": ["Their class leader's nickname was Big Ben.", "The students called him so last year."], "stem": "The students ___ last year.（用 call 合併）", "ans": "The students **called their class leader Big Ben** last year."}, {"tag": "第三人稱單數＋未來式", "sents": ["The baby's name will be Lucky.", "Mr. Wang will call the baby so."], "stem": "Mr. Wang ___.（用 call 合併）", "ans": "Mr. Wang **will call the baby Lucky**."}], "expl": ["句型：S + call + O（受詞）+ OC（名詞補語），即「稱呼某人／某物為…」。", "原題題幹被「© COSMOS CULTURE LTD」浮水印遮住，只看得到 We，依句意補為 We always call our big dog Bear.；S2 的 him 即 our big dog，so 要換成名字 Bear。", "類似題：Amy 為第三人稱單數 → calls；過去式 → called；未來式 → will call。", "易錯：不要寫 call our dog as Bear（call 後不加 as），也不可漏掉受詞寫成 call Bear。"]}, {"id": "C040", "src": "附件16 Q5", "q": {"sents": ["I found something boring.", "It was the movie we just watched."], "stem": "I found ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）"}, "ans": "I found **the movie we just watched boring**.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Kevin finds something interesting.", "It is the English book on his desk."], "stem": "Kevin finds ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "Kevin finds **the English book on his desk interesting**."}, {"tag": "複數主詞＋過去式", "sents": ["My parents found something delicious.", "It was the beef noodles at the night market."], "stem": "My parents found ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "My parents found **the beef noodles at the night market delicious**."}, {"tag": "第一人稱複數＋未來式", "sents": ["We will find something exciting.", "It is the school trip next week."], "stem": "We will find ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "We will find **the school trip next week exciting**."}], "expl": ["句型：S + find + O + OC（形容詞），表示「覺得某物…」。", "把 something 換成 S2 的 the movie we just watched（省略關代 that），形容詞 boring 放在受詞之後。", "類似題：Kevin 單數 → finds；過去式 → found；未來式 → will find。", "易錯：電影「令人」無聊用 boring，不是 bored；也不要把形容詞放在受詞前（found boring the movie）。"]}, {"id": "C041", "src": "附件16 Q6", "q": {"sents": ["We believe something.", "Jack is the best candidate for this position."], "stem": "We believe ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）"}, "ans": "We believe **Jack to be the best candidate** for this position.", "variants": [{"tag": "第三人稱單數＋現在式", "sents": ["Ms. Lin believes something.", "Amy is the best singer in our class."], "stem": "Ms. Lin believes ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "Ms. Lin believes **Amy to be the best singer** in our class."}, {"tag": "複數主詞＋過去式", "sents": ["The students believed something.", "Mr. Chen was a kind teacher."], "stem": "The students believed ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "The students believed **Mr. Chen to be a kind teacher**."}, {"tag": "第三人稱單數＋過去式＋複數受詞", "sents": ["Tom believed something.", "His friends were honest."], "stem": "Tom believed ___.（用「主詞+及物動詞+受詞+受詞補語」的句型合併）", "ans": "Tom believed **his friends to be honest**."}], "expl": ["句型：S + believe + O + (to be) + OC，to be 可省略（We believe Jack the best candidate…）。", "S2 的主詞 Jack 變成受詞，is 改成 to be（或省略），後面接補語。", "類似題：Ms. Lin 單數 → believes；過去式 → believed，但 to be 不隨時態改變。", "易錯：to 後面一定用原形 be，不可寫 to is／to was。"]}]}]}]}, "3": {"title": "Part 3 句子重組 Building", "blocks": [{"name": "現在完成式（since／for）", "subs": [{"name": "疑問句 Has + S + Vpp?", "sets": [{"id": "R010", "src": "附件5 Q15", "q": {"stem": "Has the museum ___?", "chunks": ["born", "since", "here", "you were", "been"]}, "ans": "Has the museum **been here since you were born**?", "variants": [{"tag": "複數主詞", "stem": "Have your parents ___?", "chunks": ["got married", "since", "in Taipei", "they", "lived"], "ans": "Have your parents **lived in Taipei since they got married**?"}, {"tag": "第三人稱單數", "stem": "Has your sister ___?", "chunks": ["graduated", "since", "at the bank", "she", "worked"], "ans": "Has your sister **worked at the bank since she graduated**?"}, {"tag": "第二人稱", "stem": "Have you ___?", "chunks": ["were in first grade", "since", "Amy", "you", "known"], "ans": "Have you **known Amy since you were in first grade**?"}], "expl": ["句型：Has／Have + S + p.p. + since + S + 過去式V？", "since 後面接「過去的時間點」，子句用過去式（you were born）；主要句用現在完成式。", "易錯：since 子句不可用現在完成式。主詞 your parents／you → Have；your sister → Has；動詞用 p.p.（lived, worked, known）。"]}, {"id": "R018", "src": "附件8 Q13", "q": {"stem": "Has ___?", "chunks": ["Sam", "since", "Monday", "been", "last", "sick"]}, "ans": "Has **Sam been sick since last Monday**?", "variants": [{"tag": "複數主詞", "stem": "Have ___?", "chunks": ["the kids", "since", "week", "been", "last", "busy"], "ans": "Have **the kids been busy since last week**?"}, {"tag": "第三人稱單數＋地點", "stem": "Has ___?", "chunks": ["your mother", "since", "month", "been", "last", "in Japan"], "ans": "Has **your mother been in Japan since last month**?"}, {"tag": "第二人稱", "stem": "Have ___?", "chunks": ["you", "since", "o'clock", "been", "seven", "at school"], "ans": "Have **you been at school since seven o'clock**?"}], "expl": ["句型：Has／Have + S + been + adj.／地點 + since + 時間點？", "since last Monday（從上週一起），用現在完成式 has been。", "易錯：last Monday 前不加 the 或 on。複數 the kids／you → Have；單數 Sam／your mother → Has。"]}, {"id": "R065", "src": "模擬試題第6回 Q14", "q": {"stem": "Has the tree ___ were six?", "chunks": ["since", "here", "you", "been"]}, "ans": "Has the tree **been here since you** were six?", "variants": [{"tag": "複數主詞", "stem": "Have your parents ___ were born?", "chunks": ["since", "in Tainan", "you", "lived"], "ans": "Have your parents **lived in Tainan since you** were born?"}, {"tag": "第三人稱單數（he）", "stem": "Has he ___ was a child?", "chunks": ["since", "this cat", "he", "had"], "ans": "Has he **had this cat since he** was a child?"}, {"tag": "第二人稱＋for", "stem": "Have you ___ a long time?", "chunks": ["for", "her", "known"], "ans": "Have you **known her for** a long time?"}], "expl": ["句型：Have/Has + S + Vpp + since + S + V-ed ...?", "the tree／he 第三人稱單數 → Has；your parents／you → Have。since 子句用過去式（were six、was a child）。", "易錯：Has the tree be here、Has the tree was here。"]}]}, {"name": "肯定句 has + Vpp + for", "sets": [{"id": "R013", "src": "附件6 Q13", "q": {"stem": "Emily ___ 10 years.", "chunks": ["for", "Japanese", "more than", "has studied"]}, "ans": "Emily **has studied Japanese for more than** 10 years.", "variants": [{"tag": "複數主詞", "stem": "My parents ___ 20 years.", "chunks": ["for", "in Kaohsiung", "more than", "have lived"], "ans": "My parents **have lived in Kaohsiung for more than** 20 years."}, {"tag": "第一人稱", "stem": "I ___ three years.", "chunks": ["for", "the piano", "more than", "have played"], "ans": "I **have played the piano for more than** three years."}, {"tag": "單數主詞＋be 動詞完成式", "stem": "The shop ___ ten years.", "chunks": ["for", "open", "more than", "has been"], "ans": "The shop **has been open for more than** ten years."}], "expl": ["句型：S + have／has + p.p. + for + (more than) + 一段時間", "for 接「一段時間」；more than 10 years = 超過十年。", "易錯：for 接一段時間、since 接時間點，勿混用。複數 parents／I → have；單數 Emily／the shop → has；be 動詞的 p.p. 是 been。"]}, {"id": "R037", "src": "模擬試題第1回 Q11", "q": {"stem": "My family ___ twenty years.", "chunks": ["lived", "has", "for", "here"]}, "ans": "My family **has lived here for** twenty years.", "variants": [{"tag": "複數主詞（they）", "stem": "They ___ ten years.", "chunks": ["known", "have", "for", "each other"], "ans": "They **have known each other for** ten years."}, {"tag": "第一人稱＋since", "stem": "I ___ 2020.", "chunks": ["studied", "have", "since", "English"], "ans": "I **have studied English since** 2020."}, {"tag": "第三人稱單數＋否定", "stem": "Mr. Lin ___ three months.", "chunks": ["visited", "hasn't", "for", "his hometown"], "ans": "Mr. Lin **hasn't visited his hometown for** three months."}], "expl": ["句型：S + have/has + Vpp + for + 一段時間／since + 時間點。", "family 視為單一整體 → has lived。they／I → have；Mr. Lin 第三人稱單數否定 → hasn't。", "易錯：for 接一段時間（twenty years），since 接時間點（2020），不可混用。"]}, {"id": "R043", "src": "模擬試題第2回 Q12", "q": {"stem": "Ms. Wu ___ ten years.", "chunks": ["taught", "has", "for", "English"]}, "ans": "Ms. Wu **has taught English for** ten years.", "variants": [{"tag": "複數主詞", "stem": "My parents ___ twenty years.", "chunks": ["been", "have", "for", "married"], "ans": "My parents **have been married for** twenty years."}, {"tag": "第一人稱＋since", "stem": "I ___ I was five.", "chunks": ["played", "have", "since", "the piano"], "ans": "I **have played the piano since** I was five."}, {"tag": "第三人稱單數＋否定", "stem": "Ben ___ two weeks.", "chunks": ["eaten", "hasn't", "for", "fast food"], "ans": "Ben **hasn't eaten fast food for** two weeks."}], "expl": ["句型：S + have/has + Vpp + O + for + 一段時間。", "Ms. Wu 第三人稱單數 → has taught（teach-taught-taught）。My parents／I → have；since 後可接子句 I was five（過去式）。", "易錯：寫成 has teach／has taughted，或把 English 放在 for 後面。"]}, {"id": "R048", "src": "模擬試題第3回 Q12", "q": {"stem": "Alice ___.", "chunks": ["a long time", "hasn't seen", "for", "her brother"]}, "ans": "Alice **hasn't seen her brother for a long time**.", "variants": [{"tag": "複數主詞", "stem": "My grandparents ___.", "chunks": ["two years", "haven't visited", "for", "Japan"], "ans": "My grandparents **haven't visited Japan for two years**."}, {"tag": "第一人稱＋since", "stem": "I ___.", "chunks": ["last summer", "haven't talked to", "since", "Jason"], "ans": "I **haven't talked to Jason since last summer**."}, {"tag": "第三人稱單數＋肯定", "stem": "Mike ___.", "chunks": ["three hours", "has played", "for", "video games"], "ans": "Mike **has played video games for three hours**."}], "expl": ["句型：S + have/has + (not) + Vpp + O + for／since + 時間。", "Alice 第三人稱單數 → hasn't seen；My grandparents／I → haven't。for + 一段時間，since + 時間點。", "易錯：把 for a long time 放在受詞前面，或用 didn't see 搭配 for a long time。"]}]}, {"name": "肯定句 since + 過去式子句", "sets": [{"id": "R055", "src": "模擬試題第4回 Q14", "q": {"stem": "Eric ___ moved here.", "chunks": ["since", "many friends", "he", "has made"]}, "ans": "Eric **has made many friends since he** moved here.", "variants": [{"tag": "複數主詞", "stem": "My parents ___ retired.", "chunks": ["since", "many places", "they", "have visited"], "ans": "My parents **have visited many places since they** retired."}, {"tag": "第一人稱", "stem": "I ___ was ten.", "chunks": ["since", "in Taipei", "I", "have lived"], "ans": "I **have lived in Taipei since I** was ten."}, {"tag": "第三人稱單數＋否定", "stem": "Sarah ___ left Taiwan.", "chunks": ["since", "bubble tea", "she", "hasn't had"], "ans": "Sarah **hasn't had bubble tea since she** left Taiwan."}], "expl": ["句型：S + have/has + Vpp + since + S + V-ed（主句現在完成式，since 子句過去式）。", "Eric／Sarah → has／hasn't；My parents／I → have。since 子句說明起點，用過去式（moved、retired、was）。", "易錯：since 子句也寫成現在完成式，或主句用過去式 made。"]}]}]}, {"name": "不定詞句型（want/tell sb to V／remember to V／It takes…to V）", "subs": [{"name": "be able to／目的 to V", "sets": [{"id": "R016", "src": "附件8 Q11", "q": {"stem": "I ___ last night.", "chunks": ["able", "play", "to", "the", "was", "piano", "well"]}, "ans": "I **was able to play the piano well** last night.", "variants": [{"tag": "未來式＋第三人稱單數", "stem": "She ___ next year.", "chunks": ["able", "ride", "to", "a", "will be", "bike"], "ans": "She **will be able to ride a bike** next year."}, {"tag": "現在式＋複數主詞", "stem": "They ___ now.", "chunks": ["able", "speak", "to", "English", "are", "well"], "ans": "They **are able to speak English well** now."}, {"tag": "過去否定＋第三人稱單數", "stem": "He ___ yesterday.", "chunks": ["able", "finish", "to", "the", "wasn't", "test"], "ans": "He **wasn't able to finish the test** yesterday."}], "expl": ["句型：S + be able to + 原形V（能夠…）", "I + 過去式 → was able to；play the piano（樂器前加 the）；well 修飾動詞放句尾。", "易錯：to 後面用原形，不可寫 to played。未來式 will be able to；they → are；否定 wasn't able to。"]}, {"id": "R029", "src": "附件16 Q4", "q": {"stem": "I will ___.", "chunks": ["to", "close", "the windows", "keep the room", "warm"]}, "ans": "I will **close the windows to keep the room warm**.", "variants": [{"tag": "過去式＋第三人稱單數", "stem": "She ___.", "chunks": ["to", "closed", "the door", "keep the dog", "inside"], "ans": "She **closed the door to keep the dog inside**."}, {"tag": "現在式＋複數主詞", "stem": "They ___.", "chunks": ["to", "turn on", "the fan", "keep the classroom", "cool"], "ans": "They **turn on the fan to keep the classroom cool**."}, {"tag": "現在進行式＋第三人稱單數", "stem": "He ___.", "chunks": ["to", "is wearing", "a coat", "keep himself", "warm"], "ans": "He **is wearing a coat to keep himself warm**."}], "expl": ["句型：S + V + O + to + 原形V（表目的：為了…）；keep + O + adj.", "close the windows to keep the room warm = 關窗戶讓房間保持溫暖。", "易錯：to 後用原形 keep。she 過去式 → closed；they → turn on；反身代名詞 himself 要配合 he。"]}]}, {"name": "人 + to V (want／tell)", "sets": [{"id": "R017", "src": "附件8 Q12", "q": {"stem": "Nancy's father ___.", "chunks": ["to", "told", "take", "before", "8:00", "her", "shower", "a"]}, "ans": "Nancy's father **told her to take a shower before 8:00**.", "variants": [{"tag": "現在式＋受詞 us", "stem": "My teacher ___.", "chunks": ["to", "tells", "hand in", "on time", "us", "our homework"], "ans": "My teacher **tells us to hand in our homework on time**."}, {"tag": "未來式＋受詞 them", "stem": "Mom ___.", "chunks": ["to", "will tell", "clean", "before", "dinner", "them", "the room"], "ans": "Mom **will tell them to clean the room before dinner**."}, {"tag": "複數主詞＋受詞 him", "stem": "The doctors ___.", "chunks": ["to", "told", "stay", "for", "three days", "him", "in bed"], "ans": "The doctors **told him to stay in bed for three days**."}], "expl": ["句型：S + tell + 人 + to + 原形V（叫某人去做…）", "told her to take a shower；before 8:00 時間片語放句尾。", "易錯：tell 後面受詞用受格（her, us, them, him），不用 she／we。第三人稱單數現在式 → tells；未來式 → will tell。"]}, {"id": "R044", "src": "模擬試題第2回 Q13", "q": {"stem": "Gary's father ___ a doctor.", "chunks": ["to", "him", "wanted", "become"]}, "ans": "Gary's father **wanted him to become** a doctor.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "My mom ___ my room.", "chunks": ["to", "me", "wants", "clean"], "ans": "My mom **wants me to clean** my room."}, {"tag": "複數主詞＋過去式（tell）", "stem": "The teachers ___ quiet.", "chunks": ["to", "us", "told", "be"], "ans": "The teachers **told us to be** quiet."}, {"tag": "第一人稱＋未來式（ask）", "stem": "I ___ with my homework.", "chunks": ["to", "my brother", "will ask", "help me"], "ans": "I **will ask my brother to help me** with my homework."}], "expl": ["句型：S + want／tell／ask + 人(受格) + to V。", "人要用受格（him／me／us），to 後接原形動詞。My mom → wants；過去式 told；未來 will ask。", "易錯：寫成 wanted he to、wanted him become（漏 to）或 to became。"]}]}, {"name": "remember to V", "sets": [{"id": "R021", "src": "附件9 Q11", "q": {"stem": "Did ___ laundry?", "chunks": ["the", "do", "remember", "you", "to"]}, "ans": "Did **you remember to do the** laundry?", "variants": [{"tag": "現在式＋第三人稱單數", "stem": "Does ___ door?", "chunks": ["the", "lock", "remember", "he", "to"], "ans": "Does **he remember to lock the** door?"}, {"tag": "未來式＋複數主詞", "stem": "Will ___ trash?", "chunks": ["the", "take out", "remember", "they", "to"], "ans": "Will **they remember to take out the** trash?"}, {"tag": "過去式＋第三人稱單數", "stem": "Did ___ medicine?", "chunks": ["her", "take", "remember", "your sister", "to"], "ans": "Did **your sister remember to take her** medicine?"}], "expl": ["句型：remember + to + 原形V（記得要去做，事情還沒做）", "Did you remember to do the laundry? = 你有記得洗衣服嗎？do the laundry = 洗衣服。", "易錯：remember V-ing 是「記得做過」，意思不同。Did／Does／Will 後面 remember 用原形。"]}, {"id": "R038", "src": "模擬試題第1回 Q12", "q": {"stem": "Please remember ___ leave.", "chunks": ["lock the door", "when", "you", "to"]}, "ans": "Please remember **to lock the door when you** leave.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "Mom always remembers ___ goes out.", "chunks": ["to", "when", "turn off the lights", "she"], "ans": "Mom always remembers **to turn off the lights when she** goes out."}, {"tag": "第一人稱＋過去式否定", "stem": "I didn't remember ___ left.", "chunks": ["to", "when", "close the window", "I"], "ans": "I didn't remember **to close the window when I** left."}, {"tag": "複數主詞＋未來式", "stem": "We will remember ___ get home.", "chunks": ["to", "call you", "when", "we"], "ans": "We will remember **to call you when we** get home."}], "expl": ["句型：remember to V（記得要去做）＋ when + S + V。", "remember to V 指「還沒做、要記得做」；remember V-ing 是「記得做過」。主詞 Mom → remembers / goes；過去式 → left；未來事件的 when 子句仍用現在式（we get home）。", "易錯：寫成 remember locking，或在 when 子句用 will。"]}]}, {"name": "It takes 人 時間 to V", "sets": [{"id": "R050", "src": "模擬試題第3回 Q14", "q": {"stem": "It took ___.", "chunks": ["finish the report", "several days", "me", "to"]}, "ans": "It took **me several days to finish the report**.", "variants": [{"tag": "第三人稱單數受詞＋現在式", "stem": "It takes ___.", "chunks": ["get to school", "thirty minutes", "my sister", "to"], "ans": "It takes **my sister thirty minutes to get to school**."}, {"tag": "複數受詞＋未來式", "stem": "It will take ___.", "chunks": ["clean the classroom", "an hour", "us", "to"], "ans": "It will take **us an hour to clean the classroom**."}, {"tag": "複數受詞＋過去式", "stem": "It took ___.", "chunks": ["build the house", "two years", "them", "to"], "ans": "It took **them two years to build the house**."}], "expl": ["句型：It + take + 人(受格) + 時間 + to V。", "主詞是虛主詞 It，動詞只隨時態變：takes（現在）／took（過去）／will take（未來），不隨人變。人用受格 me／us／them。", "易錯：寫成 I took several days to...，或人和時間順序顛倒。"]}]}]}, {"name": "too…to／enough to／so…that", "subs": [{"name": "too + adj + for 人 to V", "sets": [{"id": "R006", "src": "附件5 Q11", "q": {"stem": "The car was ___.", "chunks": ["all of us", "to", "for", "get in", "too small"]}, "ans": "The car was **too small for all of us to get in**.", "variants": [{"tag": "現在式＋單數主詞", "stem": "The box is ___.", "chunks": ["my sister", "to", "for", "carry", "too heavy"], "ans": "The box is **too heavy for my sister to carry**."}, {"tag": "複數主詞＋過去式", "stem": "The questions were ___.", "chunks": ["the students", "to", "for", "answer", "too difficult"], "ans": "The questions were **too difficult for the students to answer**."}, {"tag": "未來式", "stem": "The soup will be ___.", "chunks": ["the kids", "to", "for", "eat", "too hot"], "ans": "The soup will be **too hot for the kids to eat**."}], "expl": ["句型：S + be + too + adj. + for + 人 + to + 原形V", "太…以致於某人不能…；for 後面接「做動作的人」，to 後面接原形動詞。", "易錯：句尾不要再加 it（✗ too heavy for my sister to carry it），因為主詞就是受詞。主詞 questions 複數 → were；未來式 → will be。"]}, {"id": "R062", "src": "模擬試題第6回 Q11", "q": {"stem": "The bus was ___ get on.", "chunks": ["crowded", "for us", "to", "too"]}, "ans": "The bus was **too crowded for us to** get on.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "The box is ___ carry.", "chunks": ["heavy", "for her", "to", "too"], "ans": "The box is **too heavy for her to** carry."}, {"tag": "複數主詞＋現在式", "stem": "These questions are ___ answer.", "chunks": ["difficult", "for me", "to", "too"], "ans": "These questions are **too difficult for me to** answer."}, {"tag": "未來式＋複數受格", "stem": "The water will be ___ swim in.", "chunks": ["cold", "for them", "to", "too"], "ans": "The water will be **too cold for them to** swim in."}], "expl": ["句型：S + be + too + adj. + for + 人(受格) + to V（太……以致於某人不能……）。", "for 後面用受格 us／her／me／them。動詞隨主詞時態：was／is／are／will be。", "易錯：句尾再加 it（too heavy for her to carry it）或加 not。"]}]}, {"name": "adj + enough to V", "sets": [{"id": "R060", "src": "模擬試題第5回 Q14", "q": {"stem": "The water ___ drink.", "chunks": ["to", "clean", "is", "enough"]}, "ans": "The water **is clean enough to** drink.", "variants": [{"tag": "過去式＋人當主詞", "stem": "Tom ___ ride a bike.", "chunks": ["to", "old", "was", "enough"], "ans": "Tom **was old enough to** ride a bike."}, {"tag": "複數主詞", "stem": "These boxes ___ carry.", "chunks": ["to", "light", "are", "enough"], "ans": "These boxes **are light enough to** carry."}, {"tag": "第一人稱＋未來式", "stem": "I ___ join the team.", "chunks": ["to", "tall", "will be", "enough"], "ans": "I **will be tall enough to** join the team."}], "expl": ["句型：S + be + adj. + enough + to V（夠……可以……）。", "enough 放在形容詞後面。be 動詞隨主詞時態：was（過去）、are（複數）、will be（未來）。", "易錯：寫成 enough clean to drink（enough 放錯位置）。"]}]}]}, {"name": "比較級・最高級・同級比較", "subs": [{"name": "同級 as…as (No one)", "sets": [{"id": "R007", "src": "附件5 Q12", "q": {"stem": "No one ___.", "chunks": ["sing", "Mary", "as beautifully as", "can"]}, "ans": "No one **can sing as beautifully as Mary**.", "variants": [{"tag": "過去式", "stem": "Nobody in my class ___.", "chunks": ["run", "Tom", "as fast as", "could"], "ans": "Nobody in my class **could run as fast as Tom**."}, {"tag": "現在式＋第三人稱單數", "stem": "No one ___.", "chunks": ["my brother", "swims", "as well as"], "ans": "No one **swims as well as my brother**."}, {"tag": "複數主詞＋否定", "stem": "My classmates can't ___.", "chunks": ["speak", "English", "Jenny", "as fluently as"], "ans": "My classmates can't **speak English as fluently as Jenny**."}], "expl": ["句型：No one + V + as + 副詞 + as + B（= B 最…）", "sing 是動詞，修飾動詞要用副詞 beautifully；No one can sing as beautifully as Mary = Mary 唱得最好聽。", "易錯：as…as 中間用原級，不可用 more beautifully。No one 視為單數 → swims；過去式 can → could；as well as 用副詞 well 不用 good。"]}, {"id": "R057", "src": "模擬試題第5回 Q11", "q": {"stem": "The boy ___.", "chunks": ["his father", "as much as", "does", "eats"]}, "ans": "The boy **eats as much as his father does**.", "variants": [{"tag": "複數主詞", "stem": "The twins ___.", "chunks": ["their parents", "as much as", "do", "eat"], "ans": "The twins **eat as much as their parents do**."}, {"tag": "過去式", "stem": "Amy ___.", "chunks": ["her brother", "as hard as", "did", "studied"], "ans": "Amy **studied as hard as her brother did**."}, {"tag": "第一人稱主詞", "stem": "I ___.", "chunks": ["my sister", "as early as", "does", "get up"], "ans": "I **get up as early as my sister does**."}], "expl": ["句型：S + V + as + 副詞 + as + S + 助動詞(do/does/did)。", "句尾助動詞依比較對象和時態：his father／my sister → does；their parents → do；過去式 → did。主句動詞依主詞：The boy eats、I get up。", "易錯：as much as his father eats does（重複），或助動詞與比較對象不一致。"]}, {"id": "R064", "src": "模擬試題第6回 Q13", "q": {"stem": "No one ___.", "chunks": ["run", "Mary", "as fast as", "can"]}, "ans": "No one **can run as fast as Mary**.", "variants": [{"tag": "過去式", "stem": "No one ___.", "chunks": ["sing", "Lily", "as well as", "could"], "ans": "No one **could sing as well as Lily**."}, {"tag": "比較對象為複數名詞", "stem": "No other team ___.", "chunks": ["play", "the Brothers", "as well as", "can"], "ans": "No other team **can play as well as the Brothers**."}, {"tag": "第三人稱單數現在式", "stem": "Nobody in my class ___.", "chunks": ["studies", "Jason", "as hard as"], "ans": "Nobody in my class **studies as hard as Jason**."}], "expl": ["句型：No one + V + as + 副詞 + as + N（以同級比較表達最高級意思）。", "No one／Nobody 視為第三人稱單數 → studies；助動詞 can → 過去式 could，後接原形。", "易錯：No one can runs、as faster as。"]}]}, {"name": "最高級 + I've ever Vpp", "sets": [{"id": "R011", "src": "附件6 Q11", "q": {"stem": "This is ___.", "chunks": ["interesting novel", "read", "the most", "I've ever"]}, "ans": "This is **the most interesting novel I've ever read**.", "variants": [{"tag": "過去式＋過去完成式", "stem": "That was ___.", "chunks": ["delicious cake", "eaten", "the most", "I had ever"], "ans": "That was **the most delicious cake I had ever eaten**."}, {"tag": "子句複數主詞", "stem": "She is ___.", "chunks": ["teacher", "had", "the kindest", "we have ever"], "ans": "She is **the kindest teacher we have ever had**."}, {"tag": "複數主詞＋子句第三人稱單數", "stem": "These are ___.", "chunks": ["beautiful photos", "taken", "the most", "he has ever"], "ans": "These are **the most beautiful photos he has ever taken**."}], "expl": ["句型：the + 最高級 + N + (that) + S + have／has ever + p.p.", "the most interesting novel 後面接省略 that 的形容詞子句 I've ever read（我讀過的）。", "易錯：read 的 p.p. 仍是 read。主要句過去式 → 子句用 had ever；子句主詞 he → has；短形容詞用 -est（kindest），長形容詞用 the most。"]}, {"id": "R054", "src": "模擬試題第4回 Q13", "q": {"stem": "This is ___.", "chunks": ["the", "heard", "funniest joke", "I've ever"]}, "ans": "This is **the funniest joke I've ever heard**.", "variants": [{"tag": "第三人稱單數主詞", "stem": "Ken is ___.", "chunks": ["the", "met", "kindest person", "I've ever"], "ans": "Ken is **the kindest person I've ever met**."}, {"tag": "複數主詞", "stem": "These are ___.", "chunks": ["the", "eaten", "most delicious cookies", "I've ever"], "ans": "These are **the most delicious cookies I've ever eaten**."}, {"tag": "過去式＋第三人稱單數（had ever）", "stem": "That was ___.", "chunks": ["the", "seen", "scariest movie", "she had ever"], "ans": "That was **the scariest movie she had ever seen**."}], "expl": ["句型：S + be + the + 最高級 + N + (that) + S + have ever + Vpp。", "最高級前加 the；長形容詞用 most（most delicious）。主句過去式 was → 子句用過去完成式 she had ever seen。", "易錯：漏 the，或寫成 I've ever hear／I ever heard。"]}]}, {"name": "比較級 much + -er than", "sets": [{"id": "R024", "src": "附件9 Q14", "q": {"stem": "An ___ a tiger.", "chunks": ["than", "is", "heavier", "much", "elephant"]}, "ans": "An **elephant is much heavier than** a tiger.", "variants": [{"tag": "複數主詞", "stem": "Elephants ___ tigers.", "chunks": ["than", "are", "heavier", "much"], "ans": "Elephants **are much heavier than** tigers."}, {"tag": "過去式", "stem": "My brother ___ my father.", "chunks": ["than", "was", "taller", "much"], "ans": "My brother **was much taller than** my father."}, {"tag": "未來式", "stem": "This typhoon ___ the last one.", "chunks": ["than", "will be", "stronger", "much"], "ans": "This typhoon **will be much stronger than** the last one."}], "expl": ["句型：A + be + much + 比較級 + than + B", "much 放在比較級前面加強語氣（…得多）；An 後接母音開頭的 elephant。", "易錯：不可寫 very heavier 或 more heavier。複數 elephants → are；過去式 → was；未來式 → will be。"]}]}]}, {"name": "副詞子句（when／if／although／as soon as／even though）", "subs": [{"name": "時間 when／as soon as", "sets": [{"id": "R002", "src": "附件3 Q12", "q": {"stem": "Don't ___.", "chunks": ["it", "cola", "drink", "shake", "you", "the", "before"]}, "ans": "Don't **drink the cola before you shake it**.", "variants": [{"tag": "子句主詞第三人稱單數", "stem": "Don't ___.", "chunks": ["comes", "the door", "before", "home", "open", "your mother"], "ans": "Don't **open the door before your mother comes home**."}, {"tag": "過去式＋第三人稱單數", "stem": "Tom didn't ___.", "chunks": ["he", "dinner", "finished", "eat", "before", "his homework"], "ans": "Tom didn't **eat dinner before he finished his homework**."}, {"tag": "未來式＋複數主詞", "stem": "We won't ___.", "chunks": ["the rain", "go out", "stops", "before"], "ans": "We won't **go out before the rain stops**."}], "expl": ["句型：Don't + 原形V… + before + S + V（時間副詞子句）", "before 後面接完整子句 you shake it；shake 是及物動詞，要有受詞 it（指 cola）。", "易錯：時間子句用現在式代替未來式（before the rain stops，不寫 will stop）；主詞 your mother 第三人稱單數 → comes；主要子句過去式 → 子句也用過去式 finished。"]}, {"id": "R041", "src": "模擬試題第1回 Q15", "q": {"stem": "I called ___.", "chunks": ["I heard", "as soon as", "the good news", "my parents"]}, "ans": "I called **my parents as soon as I heard the good news**.", "variants": [{"tag": "第三人稱單數＋過去式", "stem": "Kevin ran ___.", "chunks": ["home", "school", "as soon as", "was over"], "ans": "Kevin ran **home as soon as school was over**."}, {"tag": "複數主詞＋未來式", "stem": "We will leave ___.", "chunks": ["as soon as", "stops", "the rain", "the house"], "ans": "We will leave **the house as soon as the rain stops**."}, {"tag": "第三人稱單數＋現在式", "stem": "My sister texts ___.", "chunks": ["she", "as soon as", "gets home", "me"], "ans": "My sister texts **me as soon as she gets home**."}], "expl": ["句型：S + V + O + as soon as + S + V（一……就……）。", "主要子句與 as soon as 子句時態一致（called／heard）。未來式時 as soon as 子句用現在式代替未來（the rain stops）；第三人稱單數 → texts／gets。", "易錯：子句寫成 will stop，或把受詞 my parents 放到句尾。"]}, {"id": "R045", "src": "模擬試題第2回 Q14", "q": {"stem": "Many people enjoy ___ cold.", "chunks": ["it's", "a hot bath", "when", "taking"]}, "ans": "Many people enjoy **taking a hot bath when it's** cold.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "My grandpa enjoys ___ sunny.", "chunks": ["it's", "a walk", "when", "taking"], "ans": "My grandpa enjoys **taking a walk when it's** sunny."}, {"tag": "第一人稱＋過去式", "stem": "I enjoyed ___ young.", "chunks": ["I was", "kites", "when", "flying"], "ans": "I enjoyed **flying kites when I was** young."}, {"tag": "複數主詞＋否定", "stem": "My friends don't enjoy ___ hot.", "chunks": ["it's", "outside", "when", "playing"], "ans": "My friends don't enjoy **playing outside when it's** hot."}], "expl": ["句型：enjoy + V-ing ＋ when + S + V。", "enjoy 後面接動名詞（taking），不接 to V。過去式子句 I was；天氣用 it's。主詞 My grandpa → enjoys；My friends 否定 → don't enjoy。", "易錯：寫成 enjoy to take，或 when 子句漏掉主詞 it。"]}]}, {"name": "讓步 although／though", "sets": [{"id": "R014", "src": "附件6 Q14", "q": {"stem": "Mike ___ tired.", "chunks": ["he was", "even though", "late", "stayed up"]}, "ans": "Mike **stayed up late even though he was** tired.", "variants": [{"tag": "複數主詞＋過去式", "stem": "The students ___ tired.", "chunks": ["they were", "even though", "running", "kept"], "ans": "The students **kept running even though they were** tired."}, {"tag": "第一人稱＋未來式", "stem": "I ___ hungry.", "chunks": ["I am", "even though", "my homework first", "will finish"], "ans": "I **will finish my homework first even though I am** hungry."}, {"tag": "現在式＋第三人稱單數", "stem": "My sister ___ sick.", "chunks": ["she is", "even though", "to school", "goes"], "ans": "My sister **goes to school even though she is** sick."}], "expl": ["句型：S + V… + even though + S + V（雖然…）", "stay up late = 熬夜；even though 後接完整子句 he was tired。", "易錯：even though 不可再和 but 連用。they → were；I → am；my sister 第三人稱單數現在式 → goes／is。"]}, {"id": "R053", "src": "模擬試題第4回 Q12", "q": {"stem": "Jim ___.", "chunks": ["was warm", "it", "although", "wore a jacket"]}, "ans": "Jim **wore a jacket although it was warm**.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "My brother ___.", "chunks": ["is sick", "he", "although", "goes to school"], "ans": "My brother **goes to school although he is sick**."}, {"tag": "複數主詞＋過去式", "stem": "They ___.", "chunks": ["was raining", "it", "although", "played basketball"], "ans": "They **played basketball although it was raining**."}, {"tag": "第一人稱＋現在式", "stem": "I ___.", "chunks": ["am full", "I", "although", "want some dessert"], "ans": "I **want some dessert although I am full**."}], "expl": ["句型：S + V + although + S + V（雖然……）。", "although 不可與 but 連用。主詞 My brother → goes／he is；I → am；過去事件兩邊都用過去式。", "易錯：寫成 Although ..., but ...，或子句漏主詞（although was warm）。"]}]}, {"name": "條件 if + 現在式", "sets": [{"id": "R061", "src": "模擬試題第5回 Q15", "q": {"stem": "I'll ___ likes it.", "chunks": ["she", "buy the watch", "if", "for her"]}, "ans": "I'll **buy the watch for her if she** likes it.", "variants": [{"tag": "第三人稱單數", "stem": "He'll ___ rains.", "chunks": ["it", "take a taxi", "if", "to school"], "ans": "He'll **take a taxi to school if it** rains."}, {"tag": "複數主詞", "stem": "We'll ___ have time.", "chunks": ["we", "go to the night market", "if", "tonight"], "ans": "We'll **go to the night market tonight if we** have time."}, {"tag": "否定＋複數子句主詞", "stem": "I won't ___ don't come.", "chunks": ["they", "go to the party", "if"], "ans": "I won't **go to the party if they** don't come."}], "expl": ["句型：S + will + V + if + S + 現在式（條件句：主要子句未來式、if 子句現在式）。", "if 子句雖指未來，仍用現在式：she likes、it rains、we have、they don't come。", "易錯：if she will like it；或第三人稱單數漏 s（she like）。"]}]}]}, {"name": "關係子句與後位修飾", "subs": [{"name": "介系詞片語後位修飾", "sets": [{"id": "R022", "src": "附件9 Q12", "q": {"stem": "Nobody ___ this question.", "chunks": ["knows", "answer", "the", "to"]}, "ans": "Nobody **knows the answer to** this question.", "variants": [{"tag": "過去式", "stem": "Nobody ___ this problem.", "chunks": ["knew", "solution", "the", "to"], "ans": "Nobody **knew the solution to** this problem."}, {"tag": "複數主詞＋現在式", "stem": "All of my classmates ___ the math test.", "chunks": ["know", "answers", "the", "to"], "ans": "All of my classmates **know the answers to** the math test."}, {"tag": "未來式", "stem": "Nobody ___ the museum.", "chunks": ["will know", "way", "the", "to"], "ans": "Nobody **will know the way to** the museum."}], "expl": ["句型：the answer／solution／way + to + N（介系詞片語後位修飾名詞）", "the answer to this question = 這個問題的答案；介系詞用 to，不用 of。", "易錯：Nobody 視為單數 → knows；All of my classmates 複數 → know；過去式 know → knew。"]}, {"id": "R040", "src": "模擬試題第1回 Q14", "q": {"stem": "I bought ___.", "chunks": ["at the bookstore", "this book", "the restaurant", "next to"]}, "ans": "I bought **this book at the bookstore next to the restaurant**.", "variants": [{"tag": "第三人稱單數＋過去式", "stem": "Lisa bought ___.", "chunks": ["near", "these shoes", "the MRT station", "at the store"], "ans": "Lisa bought **these shoes at the store near the MRT station**."}, {"tag": "複數主詞＋未來式", "stem": "We will eat ___.", "chunks": ["across from", "dinner", "our school", "at the restaurant"], "ans": "We will eat **dinner at the restaurant across from our school**."}, {"tag": "第三人稱單數＋現在式", "stem": "My dad buys ___.", "chunks": ["behind", "fruit", "the park", "at the market"], "ans": "My dad buys **fruit at the market behind the park**."}], "expl": ["句型：S + V + O + at + 地點N + 介系詞片語（後位修飾地點）。", "next to the restaurant 修飾前面的 the bookstore，要緊跟在後。類似題：Lisa 過去式 bought；We will eat；My dad 第三人稱單數 → buys。", "易錯：把 this book 放在地點後面，或把 next to the restaurant 放在 bookstore 前面。"]}]}, {"name": "關係代名詞 who／that／which", "sets": [{"id": "R036", "src": "附件18 Q15", "q": {"stem": "I bought ___.", "chunks": ["apple pie", "a slice of", "which is", "dessert", "my favorite"]}, "ans": "I bought **a slice of apple pie, which is my favorite dessert**.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "My brother often drinks ___.", "chunks": ["bubble tea", "a cup of", "which is", "drink", "his favorite"], "ans": "My brother often drinks **a cup of bubble tea, which is his favorite drink**."}, {"tag": "複數主詞＋過去式", "stem": "We ate ___.", "chunks": ["stinky tofu", "a plate of", "which is", "snack", "our favorite"], "ans": "We ate **a plate of stinky tofu, which is our favorite snack**."}, {"tag": "第三人稱單數＋未來式＋複數先行詞", "stem": "Mom will buy ___.", "chunks": ["cookies", "a box of", "which are", "snack", "my favorite"], "ans": "Mom will buy **a box of cookies, which are my favorite snack**."}], "expl": ["句型：量詞 a slice of + N，, which + be + 補語（非限定關係子句，前面加逗號）。", "which 指 apple pie（不可數→is）。所有格隨主詞變：my／his／our；先行詞 cookies 為複數 → which are。", "易錯：漏掉逗號，或把 my favorite dessert 拆開寫成 dessert my favorite。"]}, {"id": "R046", "src": "模擬試題第2回 Q15", "q": {"stem": "I ___ lent me last week.", "chunks": ["my friend", "the umbrella", "that", "lost"]}, "ans": "I **lost the umbrella that my friend** lent me last week.", "variants": [{"tag": "第三人稱單數＋現在完成式", "stem": "Amy ___ gave her.", "chunks": ["her aunt", "the bag", "that", "has lost"], "ans": "Amy **has lost the bag that her aunt** gave her."}, {"tag": "複數主詞＋過去式", "stem": "We ___ recommended.", "chunks": ["our teacher", "the movie", "that", "watched"], "ans": "We **watched the movie that our teacher** recommended."}, {"tag": "第三人稱單數＋未來式", "stem": "Tom ___ bought yesterday.", "chunks": ["his dad", "the shoes", "that", "will wear"], "ans": "Tom **will wear the shoes that his dad** bought yesterday."}], "expl": ["句型：S + V + 先行詞 + that + S + V（that 作受格關係代名詞）。", "that 代替 the umbrella，當 lent 的受詞，所以子句不再出現 it。主句時態可變（has lost／will wear），子句仍依事件時間用過去式。", "易錯：在子句末多加 it（that my friend lent me it）。"]}, {"id": "R051", "src": "模擬試題第3回 Q15", "q": {"stem": "My father ___ five languages.", "chunks": ["speaks", "who", "a friend", "has"]}, "ans": "My father **has a friend who speaks** five languages.", "variants": [{"tag": "第一人稱＋過去式", "stem": "I ___ in Kaohsiung.", "chunks": ["lived", "who", "a cousin", "had"], "ans": "I **had a cousin who lived** in Kaohsiung."}, {"tag": "複數主詞", "stem": "We ___ three cats.", "chunks": ["has", "who", "a neighbor", "have"], "ans": "We **have a neighbor who has** three cats."}, {"tag": "第三人稱單數＋複數先行詞", "stem": "Linda ___ in Canada.", "chunks": ["live", "who", "two uncles", "has"], "ans": "Linda **has two uncles who live** in Canada."}], "expl": ["句型：S + have/has + 先行詞(人) + who + V。", "who 子句的動詞依先行詞決定：a friend 單數 → speaks；two uncles 複數 → live。主句依主詞：My father／Linda → has；We → have。", "易錯：把 who 子句動詞跟主句主詞一致（We have a neighbor who have）。"]}]}]}, {"name": "疑問句與 There is／are", "subs": [{"name": "問句 Will／Has／Why not", "sets": [{"id": "R003", "src": "附件3 Q13", "q": {"stem": "Will ___?", "chunks": ["a", "get", "desk", "from", "me", "you", "pencil", "the"]}, "ans": "Will **you get me a pencil from the desk**?", "variants": [{"tag": "過去式＋第三人稱單數", "stem": "Did ___?", "chunks": ["a", "bring", "bakery", "from", "you", "she", "cake", "the"], "ans": "Did **she bring you a cake from the bakery**?"}, {"tag": "複數主詞＋助動詞 can", "stem": "Can ___?", "chunks": ["some", "buy", "night market", "from", "us", "they", "snacks", "the"], "ans": "Can **they buy us some snacks from the night market**?"}, {"tag": "現在式＋第三人稱單數", "stem": "Does ___?", "chunks": ["a", "make", "morning", "in", "you", "your father", "sandwich", "the"], "ans": "Does **your father make you a sandwich in the morning**?"}], "expl": ["句型：助動詞 + S + 原形V + 人 + 物 + 介系詞片語？", "Will 開頭的問句：Will + you + get（原形）+ me（間接受詞）+ a pencil（直接受詞）+ from the desk。", "易錯：a 接 pencil、the 接 desk，不要對調。Did／Can／Does 後面動詞一律用原形（bring, buy, make），不加 -s 或 -ed。"]}, {"id": "R023", "src": "附件9 Q13", "q": {"stem": "Why not ___?", "chunks": ["police officer", "directions", "the", "ask", "for"]}, "ans": "Why not **ask the police officer for directions**?", "variants": [{"tag": "過去式＋第三人稱單數", "stem": "Why didn't she ___?", "chunks": ["teacher", "help", "her", "ask", "for"], "ans": "Why didn't she **ask her teacher for help**?"}, {"tag": "現在式＋複數主詞", "stem": "Why don't they ___?", "chunks": ["clerk", "a bigger size", "the", "ask", "for"], "ans": "Why don't they **ask the clerk for a bigger size**?"}, {"tag": "現在式＋第三人稱單數", "stem": "Why doesn't he ___?", "chunks": ["parents", "advice", "his", "ask", "for"], "ans": "Why doesn't he **ask his parents for advice**?"}], "expl": ["句型：Why not + 原形V…?（= Why don't you + 原形V…?）；ask + 人 + for + 東西", "ask the police officer for directions = 向警察問路。", "易錯：Why not 後面直接接原形，不加 to。she → didn't／doesn't 後面仍用原形 ask。"]}, {"id": "R058", "src": "模擬試題第5回 Q12", "q": {"stem": "Has ___ that restaurant?", "chunks": ["else", "heard", "of", "anyone"]}, "ans": "Has **anyone else heard of** that restaurant?", "variants": [{"tag": "過去式", "stem": "Did ___ the news?", "chunks": ["else", "hear", "about", "anyone"], "ans": "Did **anyone else hear about** the news?"}, {"tag": "複數主詞＋現在完成式", "stem": "Have ___ that movie?", "chunks": ["all", "your friends", "heard", "of"], "ans": "Have **all your friends heard of** that movie?"}, {"tag": "現在式", "stem": "Does ___ that singer?", "chunks": ["else", "know", "about", "anyone"], "ans": "Does **anyone else know about** that singer?"}], "expl": ["句型：Has + anyone else + Vpp ...?；hear of＝聽說過。", "else 放在 anyone 後面（anyone else）；anyone 視為單數 → Has／Does；複數 your friends → Have。Did／Does 後接原形 hear／know。", "易錯：else anyone、Has anyone heard else of。"]}]}, {"name": "There is／are + N", "sets": [{"id": "R009", "src": "附件5 Q14", "q": {"stem": "There are restaurants on ___.", "chunks": ["each", "the department store", "floor", "of"]}, "ans": "There are restaurants on **each floor of the department store**.", "variants": [{"tag": "過去式＋單數名詞", "stem": "There was a water fountain on ___.", "chunks": ["each", "our old school", "floor", "of"], "ans": "There was a water fountain on **each floor of our old school**."}, {"tag": "未來式", "stem": "There will be posters on ___.", "chunks": ["each", "the classroom", "wall", "of"], "ans": "There will be posters on **each wall of the classroom**."}, {"tag": "現在式＋單數名詞", "stem": "There is a convenience store on ___.", "chunks": ["each", "this street", "corner", "of"], "ans": "There is a convenience store on **each corner of this street**."}], "expl": ["句型：There is／are + N + on + each + 單數N + of + 地方", "each 後面接單數名詞 floor；of the department store 表「…的」。", "易錯：不寫 each floors。There is／was 接單數名詞，There are／were 接複數；未來式一律 There will be。"]}, {"id": "R047", "src": "模擬試題第3回 Q11", "q": {"stem": "There ___.", "chunks": ["people", "aren't", "in the restaurant", "many"]}, "ans": "There **aren't many people in the restaurant**.", "variants": [{"tag": "複數＋過去式", "stem": "There ___.", "chunks": ["students", "weren't", "in the library", "many"], "ans": "There **weren't many students in the library**."}, {"tag": "不可數＋現在式", "stem": "There ___.", "chunks": ["water", "isn't", "in the bottle", "much"], "ans": "There **isn't much water in the bottle**."}, {"tag": "複數＋未來式", "stem": "There ___ tomorrow.", "chunks": ["cars", "won't be", "on the road", "many"], "ans": "There **won't be many cars on the road** tomorrow."}], "expl": ["句型：There + be + (not) + many/much + N + 地點。", "people 是複數 → aren't many；不可數 water → isn't much；過去 weren't；未來 won't be。", "易錯：many 放在名詞後（people many），或 water 搭配 many。"]}]}, {"name": "How much + N 問句", "sets": [{"id": "R032", "src": "附件18 Q11", "q": {"stem": "How much ___?", "chunks": ["you", "do", "have", "money"]}, "ans": "How much **money do you have**?", "variants": [{"tag": "現在式＋第三人稱單數", "stem": "How many ___?", "chunks": ["she", "does", "have", "books"], "ans": "How many **books does she have**?"}, {"tag": "過去式＋複數主詞", "stem": "How much ___?", "chunks": ["they", "did", "drink", "water"], "ans": "How much **water did they drink**?"}, {"tag": "未來式＋第一人稱複數", "stem": "How much ___?", "chunks": ["we", "will", "need", "time"], "ans": "How much **time will we need**?"}], "expl": ["句型：How much + 不可數N + do／does + S + V？／How many + 可數複數N…？", "money 不可數 → How much money；名詞緊跟在 How much 後面。", "易錯：不寫 How much do you have money。she → does have（不寫 does has）；過去式 did + 原形 drink。"]}, {"id": "R039", "src": "模擬試題第1回 Q13", "q": {"stem": "How much ___?", "chunks": ["in the bottle", "is", "milk", "there"]}, "ans": "How much **milk is there in the bottle**?", "variants": [{"tag": "可數複數＋How many", "stem": "How many ___?", "chunks": ["are", "in the classroom", "students", "there"], "ans": "How many **students are there in the classroom**?"}, {"tag": "不可數＋過去式", "stem": "How much ___?", "chunks": ["was", "in the fridge", "juice", "there"], "ans": "How much **juice was there in the fridge**?"}, {"tag": "可數複數＋過去式", "stem": "How many ___?", "chunks": ["were", "at the night market", "people", "there"], "ans": "How many **people were there at the night market**?"}], "expl": ["句型：How much + 不可數N + is there + 地點？／How many + 複數N + are there + 地點？", "milk 不可數 → How much ... is；students／people 複數 → How many ... are／were；過去式 is → was、are → were。", "易錯：How much milk there is（疑問句沒倒裝），或名詞沒緊跟在 How much／many 後面。"]}]}]}, {"name": "頻率・時間副詞與介系詞片語位置", "subs": [{"name": "動詞 + 介系詞片語", "sets": [{"id": "R001", "src": "附件3 Q11", "q": {"stem": "That ___.", "chunks": ["man", "from", "prison", "escaped"]}, "ans": "That **man escaped from prison**.", "variants": [{"tag": "複數主詞＋過去式＋時間副詞", "stem": "Those monkeys ___.", "chunks": ["the zoo", "escaped", "from", "last night"], "ans": "Those monkeys **escaped from the zoo last night**."}, {"tag": "未來式", "stem": "The bird ___.", "chunks": ["of", "will", "the cage", "fly", "out"], "ans": "The bird **will fly out of the cage**."}, {"tag": "現在簡單式＋第三人稱單數", "stem": "My cat often ___.", "chunks": ["of", "runs", "the house", "out"], "ans": "My cat often **runs out of the house**."}], "expl": ["句型：S + V + from／out of + 地點（介系詞片語放在動詞後面）", "escape from + 地方 = 從…逃出；That 後面先接名詞 man 當主詞。", "易錯：不要寫成 escaped prison from。類似題：未來式用 will + 原形；第三人稱單數現在式動詞加 -s（runs）。"]}, {"id": "R027", "src": "附件16 Q2", "q": {"stem": "We ___ English class.", "chunks": ["feel", "in", "excited", "our"]}, "ans": "We **feel excited in our** English class.", "variants": [{"tag": "過去式＋第三人稱單數", "stem": "She ___ math class.", "chunks": ["felt", "in", "nervous", "her"], "ans": "She **felt nervous in her** math class."}, {"tag": "複數主詞＋頻率副詞", "stem": "They ___ music class.", "chunks": ["always", "feel", "in", "happy", "their"], "ans": "They **always feel happy in their** music class."}, {"tag": "未來式＋第一人稱單數", "stem": "I ___ P.E. class.", "chunks": ["will feel", "in", "tired", "my"], "ans": "I **will feel tired in my** P.E. class."}], "expl": ["句型：S + feel + adj. + in + 所有格 + N", "feel 是連綴動詞，後面接形容詞 excited；in our English class 放在後面。", "易錯：所有格要配合主詞（we → our, she → her, they → their）。頻率副詞 always 放一般動詞前；過去式 felt。"]}, {"id": "R034", "src": "附件18 Q13", "q": {"stem": "I ___.", "chunks": ["got", "iPod", "my birthday", "for", "an"]}, "ans": "I **got an iPod for my birthday**.", "variants": [{"tag": "第三人稱單數＋過去式", "stem": "My sister ___.", "chunks": ["a new bike", "her birthday", "got", "for"], "ans": "My sister **got a new bike for her birthday**."}, {"tag": "複數主詞＋未來式", "stem": "They ___.", "chunks": ["will get", "for", "some books", "Christmas"], "ans": "They **will get some books for Christmas**."}, {"tag": "第三人稱單數＋現在式（習慣）", "stem": "Tom ___.", "chunks": ["gets", "every year", "a cake", "for", "his birthday"], "ans": "Tom **gets a cake for his birthday every year**."}], "expl": ["句型：S + get + 物品 + for + 場合（for my birthday＝當作生日禮物），介系詞片語放在受詞後面。", "iPod 以母音音 /aɪ/ 開頭，冠詞用 an。類似題：過去式 got 不隨人稱變；未來式 will get；第三人稱單數現在式 gets，時間 every year 放句尾。", "易錯：寫成 a iPod，或把 for my birthday 插到 got 和受詞之間。"]}]}, {"name": "句首副詞 Maybe", "sets": [{"id": "R004", "src": "附件3 Q14", "q": {"stem": "Maybe ___.", "chunks": ["will", "movies", "to", "she", "go", "the"]}, "ans": "Maybe **she will go to the movies**.", "variants": [{"tag": "過去式＋複數主詞", "stem": "Maybe ___.", "chunks": ["went", "night market", "to", "they", "the"], "ans": "Maybe **they went to the night market**."}, {"tag": "第一人稱＋未來式＋時間副詞", "stem": "Maybe ___.", "chunks": ["will", "home", "at", "I", "stay", "tomorrow"], "ans": "Maybe **I will stay at home tomorrow**."}, {"tag": "現在式＋第三人稱單數", "stem": "Maybe ___.", "chunks": ["is", "MRT station", "at", "he", "the", "now"], "ans": "Maybe **he is at the MRT station now**."}], "expl": ["句型：Maybe（副詞，放句首）+ S + V…", "Maybe 是副詞「也許」，後面接完整句子 she will go to the movies；go to the movies = 去看電影。", "易錯：Maybe 和 may be 不同，Maybe 後面要有主詞＋動詞。類似題：過去式 go → went；he 第三人稱單數 → is；時間副詞 tomorrow／now 放句尾。"]}]}, {"name": "次數頻率 once／times a", "sets": [{"id": "R005", "src": "附件3 Q15", "q": {"stem": "I ___.", "chunks": ["cat", "my", "bathe", "a", "week", "once"]}, "ans": "I **bathe my cat once a week**.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "She ___.", "chunks": ["dog", "her", "washes", "a", "week", "twice"], "ans": "She **washes her dog twice a week**."}, {"tag": "過去式＋複數主詞", "stem": "They ___ last year.", "chunks": ["grandparents", "their", "visited", "a", "month", "once"], "ans": "They **visited their grandparents once a month** last year."}, {"tag": "未來式＋第三人稱單數", "stem": "He ___.", "chunks": ["room", "his", "will clean", "a", "day", "once"], "ans": "He **will clean his room once a day**."}], "expl": ["句型：S + V + O + 次數（once／twice／three times）+ a + 時間單位", "頻率片語 once a week 放在句尾（受詞之後）。", "易錯：不要寫 once week（漏 a）或 a once week。She 第三人稱單數 → washes；過去式 → visited；未來式 will + 原形 clean。"]}, {"id": "R019", "src": "附件8 Q14", "q": {"stem": "Wendy ___.", "chunks": ["her", "grandparents", "once", "visits", "every year"]}, "ans": "Wendy **visits her grandparents once every year**.", "variants": [{"tag": "複數主詞＋現在式", "stem": "My cousins ___.", "chunks": ["us", "visit", "twice", "every year"], "ans": "My cousins **visit us twice every year**."}, {"tag": "過去式", "stem": "Last year, Tom ___.", "chunks": ["the dentist", "to", "once", "went", "every month"], "ans": "Last year, Tom **went to the dentist once every month**."}, {"tag": "第一人稱＋未來式", "stem": "I ___.", "chunks": ["my", "grandma", "once", "will call", "every week"], "ans": "I **will call my grandma once every week**."}], "expl": ["句型：S + V + O + 次數 + every + 時間", "頻率片語 once every year 放在受詞後面（句尾）；Wendy 第三人稱單數 → visits。", "易錯：不要把 once 放在動詞前。my cousins 複數 → visit；過去式 → went；未來式 → will call。"]}, {"id": "R028", "src": "附件16 Q3", "q": {"stem": "She ___.", "chunks": ["took", "the medicine", "day", "four times", "a"]}, "ans": "She **took the medicine four times a day**.", "variants": [{"tag": "現在式＋第三人稱單數", "stem": "He ___.", "chunks": ["brushes", "his teeth", "day", "three times", "a"], "ans": "He **brushes his teeth three times a day**."}, {"tag": "未來式＋複數主詞", "stem": "They ___.", "chunks": ["will practice", "basketball", "week", "twice", "a"], "ans": "They **will practice basketball twice a week**."}, {"tag": "現在式＋第一人稱", "stem": "I ___.", "chunks": ["feed", "my fish", "day", "two times", "a"], "ans": "I **feed my fish two times a day**."}], "expl": ["句型：S + V + O + 次數 + a + 時間單位", "take the medicine = 吃藥；four times a day = 一天四次，放在句尾。", "易錯：不寫 four time（要加 s）或 a four times day。he → brushes；I → feed；未來式 will + 原形。"]}]}, {"name": "進行式 + 地點片語", "sets": [{"id": "R008", "src": "附件5 Q13", "q": {"stem": "The flight ___.", "chunks": ["the airport", "o'clock", "is", "six", "leaving", "at"]}, "ans": "The flight **is leaving the airport at six o'clock**.", "variants": [{"tag": "複數主詞", "stem": "The trains ___.", "chunks": ["the station", "o'clock", "are", "ten", "leaving", "at"], "ans": "The trains **are leaving the station at ten o'clock**."}, {"tag": "過去式", "stem": "The bus ___.", "chunks": ["the school", "o'clock", "left", "four", "at"], "ans": "The bus **left the school at four o'clock**."}, {"tag": "第一人稱複數＋未來式", "stem": "We ___.", "chunks": ["Taipei", "o'clock", "will", "seven", "leave", "at", "tomorrow"], "ans": "We **will leave Taipei at seven o'clock tomorrow**."}], "expl": ["句型：S + be + V-ing + 地點 + at + 時刻（現在進行式表確定的未來計畫）", "leave + 地點（不加 from）；at six o'clock 放在地點之後。", "易錯：時間順序「小到大」：at seven o'clock tomorrow。複數 trains → are；過去式 leave → left；未來式 will + 原形 leave。"]}, {"id": "R042", "src": "模擬試題第2回 Q11", "q": {"stem": "___.", "chunks": ["in front of", "Tom", "the train station", "is standing"]}, "ans": "**Tom is standing in front of the train station**.", "variants": [{"tag": "複數主詞＋現在進行式", "stem": "___.", "chunks": ["are waiting", "the students", "in front of", "the school gate"], "ans": "**The students are waiting in front of the school gate**."}, {"tag": "第三人稱單數＋過去進行式", "stem": "___.", "chunks": ["was sitting", "my grandma", "next to", "the window"], "ans": "**My grandma was sitting next to the window**."}, {"tag": "第一人稱＋未來式", "stem": "___.", "chunks": ["will wait", "I", "in front of", "the MRT station"], "ans": "**I will wait in front of the MRT station**."}], "expl": ["句型：S + be + V-ing + 地方介系詞片語（in front of／next to + N）。", "in front of 是「在……前面」，後接名詞。主詞 the students → are；my grandma 過去 → was；未來 → will wait。", "易錯：句首字母要大寫；把 in front of 拆開或放在主詞前。"]}, {"id": "R063", "src": "模擬試題第6回 Q12", "q": {"stem": "The child is jumping ___ bed.", "chunks": ["and down", "his", "on", "up"]}, "ans": "The child is jumping **up and down on his** bed.", "variants": [{"tag": "複數主詞＋過去進行式", "stem": "The kids were running ___ hallway.", "chunks": ["and forth", "the", "in", "back"], "ans": "The kids were running **back and forth in the** hallway."}, {"tag": "第三人稱單數＋現在式", "stem": "My dog runs ___ yard every morning.", "chunks": ["and around", "the", "in", "around"], "ans": "My dog runs **around and around in the** yard every morning."}, {"tag": "第一人稱＋過去式", "stem": "I walked ___ street.", "chunks": ["and down", "the", "up"], "ans": "I walked **up and down the** street."}], "expl": ["句型：V + 方向副詞片語（up and down／back and forth）+ 地點介系詞片語。", "方向副詞緊跟動詞，地點片語放後面。The kids → were running；My dog 第三人稱單數 → runs；過去式 → walked。", "易錯：寫成 down and up，或把 on his bed 放在 up and down 前面。"]}]}, {"name": "先地方後時間", "sets": [{"id": "R026", "src": "附件16 Q1", "q": {"stem": "My friends ___ last month.", "chunks": ["took a trip", "Palau", "to", "and I"]}, "ans": "My friends **and I took a trip to Palau** last month.", "variants": [{"tag": "未來式", "stem": "My sister ___ next summer.", "chunks": ["will take a trip", "Japan", "to", "and I"], "ans": "My sister **and I will take a trip to Japan** next summer."}, {"tag": "現在式＋複數主詞", "stem": "Tom ___ every year.", "chunks": ["take a trip", "Hualien", "to", "and his family"], "ans": "Tom **and his family take a trip to Hualien** every year."}, {"tag": "現在進行式", "stem": "My parents ___ now.", "chunks": ["are taking a trip", "Kenting", "to", "and my aunt"], "ans": "My parents **and my aunt are taking a trip to Kenting** now."}], "expl": ["句型：A and I + V + take a trip to + 地點 + 時間", "主詞 My friends and I（禮貌上 I 放最後）；take a trip to + 地點 = 去…旅行。", "易錯：不寫 I and my friends。A and B 是複數 → take（不是 takes）／are taking；未來式 will take。"]}, {"id": "R030", "src": "附件16 Q5", "q": {"stem": "___.", "chunks": ["teach", "every evening", "has to", "his younger brother", "math", "Jerry"]}, "ans": "**Jerry has to teach his younger brother math every evening**.", "variants": [{"tag": "過去式＋複數主詞", "stem": "___.", "chunks": ["teach", "every weekend", "had to", "their cousin", "English", "Amy and Ben"], "ans": "**Amy and Ben had to teach their cousin English every weekend**."}, {"tag": "未來式＋第一人稱", "stem": "___.", "chunks": ["teach", "every Sunday", "will have to", "my grandmother", "computer skills", "I"], "ans": "**I will have to teach my grandmother computer skills every Sunday**."}, {"tag": "現在式＋複數主詞", "stem": "___.", "chunks": ["give", "every week", "have to", "our dog", "a bath", "My parents"], "ans": "**My parents have to give our dog a bath every week**."}], "expl": ["句型：S + has to + teach + 人 + 科目 + every + 時間", "teach 後面「人」在前、「科目」在後；every evening 放句尾。", "易錯：has to 後接原形 teach。複數主詞 → have to；過去式 → had to；未來式 → will have to。"]}, {"id": "R035", "src": "附件18 Q14", "q": {"stem": "They ___.", "chunks": ["in the park", "go picnicking", "every weekend"]}, "ans": "They **go picnicking in the park every weekend**.", "variants": [{"tag": "第三人稱單數＋現在式", "stem": "My uncle ___.", "chunks": ["every Sunday", "goes fishing", "at the river"], "ans": "My uncle **goes fishing at the river every Sunday**."}, {"tag": "複數主詞＋過去式", "stem": "We ___.", "chunks": ["last Saturday", "went hiking", "on Yangmingshan"], "ans": "We **went hiking on Yangmingshan last Saturday**."}, {"tag": "第三人稱單數＋未來式", "stem": "Amy ___.", "chunks": ["will go swimming", "tomorrow afternoon", "at the pool"], "ans": "Amy **will go swimming at the pool tomorrow afternoon**."}], "expl": ["句型：S + go + V-ing + 地點 + 時間（先地方、後時間）。", "go picnicking／fishing／hiking 是「去從事某活動」的固定說法。類似題：my uncle 第三人稱單數 → goes；last Saturday → went；tomorrow → will go。", "易錯：把時間放在地點前（every weekend in the park），或寫成 go to picnic。"]}]}]}, {"name": "慣用語與動詞片語（had better／would rather／mean to／help sb with／instead of／either…or）", "subs": [{"name": "mean to／had better", "sets": [{"id": "R012", "src": "附件6 Q12", "q": {"stem": "Bruce ___ angry.", "chunks": ["make you", "mean", "didn't", "to"]}, "ans": "Bruce **didn't mean to make you** angry.", "variants": [{"tag": "現在式＋第三人稱單數", "stem": "She ___ upset.", "chunks": ["make her friends", "mean", "doesn't", "to"], "ans": "She **doesn't mean to make her friends** upset."}, {"tag": "第一人稱單數＋過去式", "stem": "I ___ sad.", "chunks": ["make him", "mean", "didn't", "to"], "ans": "I **didn't mean to make him** sad."}, {"tag": "第一人稱複數＋過去式", "stem": "Sorry, we ___ worried.", "chunks": ["make you", "mean", "didn't", "to"], "ans": "Sorry, we **didn't mean to make you** worried."}], "expl": ["句型：S + didn't／doesn't + mean to + 原形V（不是故意要…）；make + 人 + adj.", "mean to = 有意要；didn't 後面用原形 mean，再接 to make。", "易錯：不要寫 didn't meant。主詞 she 現在式 → doesn't mean；make 後面受詞＋形容詞（make you angry），不加 to be。"]}, {"id": "R052", "src": "模擬試題第4回 Q11", "q": {"stem": "You ___ her.", "chunks": ["be", "with", "honest", "had better"]}, "ans": "You **had better be honest with** her.", "variants": [{"tag": "第三人稱單數", "stem": "He ___ his phone.", "chunks": ["stop", "playing", "had better", "with"], "ans": "He **had better stop playing with** his phone."}, {"tag": "複數主詞＋否定", "stem": "We ___.", "chunks": ["not", "be late", "had better", "for school"], "ans": "We **had better not be late for school**."}, {"tag": "第一人稱", "stem": "I ___ now.", "chunks": ["finish", "my homework", "had better"], "ans": "I **had better finish my homework** now."}], "expl": ["句型：S + had better (not) + V原形；be honest with + 人。", "had better 不隨人稱或時態變化（He had better，不是 has better），後面一定接原形動詞；否定 not 放在 better 之後。", "易錯：had better to be、had not better、had better is。"]}, {"id": "R056", "src": "模擬試題第4回 Q15", "q": {"stem": "Alice ___ your feelings.", "chunks": ["hurt", "mean", "didn't", "to"]}, "ans": "Alice **didn't mean to hurt** your feelings.", "variants": [{"tag": "第一人稱＋過去式", "stem": "I ___ your cup.", "chunks": ["break", "mean", "didn't", "to"], "ans": "I **didn't mean to break** your cup."}, {"tag": "第三人稱單數＋現在式", "stem": "He ___ rude.", "chunks": ["be", "mean", "doesn't", "to"], "ans": "He **doesn't mean to be** rude."}, {"tag": "複數主詞＋過去式", "stem": "They ___ you waiting.", "chunks": ["keep", "mean", "didn't", "to"], "ans": "They **didn't mean to keep** you waiting."}], "expl": ["句型：S + don't/doesn't/didn't + mean to + V原形（不是故意要……）。", "didn't 後接原形 mean；He 現在式 → doesn't mean。hurt 三態同形，這裡是 to 後的原形。", "易錯：didn't meant to、didn't mean hurt（漏 to）。"]}, {"id": "R059", "src": "模擬試題第5回 Q13", "q": {"stem": "Mom ___ rich.", "chunks": ["happy", "would rather", "than", "be"]}, "ans": "Mom **would rather be happy than** rich.", "variants": [{"tag": "第一人稱", "stem": "I ___ the bus.", "chunks": ["walk", "would rather", "than", "take"], "ans": "I **would rather walk than take** the bus."}, {"tag": "複數主詞", "stem": "My friends ___ watch TV.", "chunks": ["play basketball", "would rather", "than"], "ans": "My friends **would rather play basketball than** watch TV."}, {"tag": "第三人稱單數＋否定", "stem": "He ___ tonight.", "chunks": ["go out", "would rather", "not"], "ans": "He **would rather not go out** tonight."}], "expl": ["句型：S + would rather + V1 + than + (V2)（寧願 V1 也不 V2）。", "would rather 不隨人稱變化，後接原形動詞；than 前後對稱（be happy than (be) rich）；否定 not 放在 rather 之後。", "易錯：would rather to be、would rather being、would not rather。"]}]}, {"name": "instead of／either…or", "sets": [{"id": "R015", "src": "附件6 Q15", "q": {"stem": "You should ___ lying to her.", "chunks": ["with", "instead of", "be honest", "her"]}, "ans": "You should **be honest with her instead of** lying to her.", "variants": [{"tag": "第三人稱單數", "stem": "He should ___ cheating on the test.", "chunks": ["for help", "instead of", "ask", "the teacher"], "ans": "He should **ask the teacher for help instead of** cheating on the test."}, {"tag": "過去式＋複數主詞", "stem": "They ___ playing video games last night.", "chunks": ["their homework", "instead of", "did"], "ans": "They **did their homework instead of** playing video games last night."}, {"tag": "未來式＋第一人稱", "stem": "I will ___ taking a taxi.", "chunks": ["the MRT", "instead of", "take"], "ans": "I will **take the MRT instead of** taking a taxi."}], "expl": ["句型：S + V… + instead of + V-ing（而不是…）", "be honest with + 人 = 對某人誠實；instead of 是介系詞，後面接 V-ing（lying）。", "易錯：instead of 後不可接原形（✗ instead of lie）。should／will 後接原形（be, ask, take）；過去式 do → did。"]}, {"id": "R033", "src": "附件18 Q12", "q": {"stem": "Either ___.", "chunks": ["the movie", "going to", "or", "the karaoke", "is", "good"]}, "ans": "Either **going to the movie or the karaoke is good**.", "variants": [{"tag": "複數主詞（靠近動詞者）", "stem": "Either ___.", "chunks": ["my brother", "are", "or", "my parents", "going to pick you up"], "ans": "Either **my brother or my parents are going to pick you up**."}, {"tag": "過去式＋第三人稱單數", "stem": "Either ___.", "chunks": ["you", "was", "or", "Tom", "late for class", "yesterday"], "ans": "Either **you or Tom was late for class** yesterday."}, {"tag": "第一人稱", "stem": "Either ___.", "chunks": ["Mary", "am", "or", "I", "going to clean", "the room"], "ans": "Either **Mary or I am going to clean the room**."}], "expl": ["句型：Either A or B + V（動詞跟最靠近的 B 一致）", "原題 chunks 只能組成 Either going to the movie or the karaoke is good（去看電影或唱 KTV 都好）；較自然說法為 Going to either the movie or the karaoke is good.", "易錯：動詞看 B：my parents → are；Tom → was；I → am。"]}, {"id": "R066", "src": "模擬試題第6回 Q15", "q": {"stem": "There are tall buildings on ___.", "chunks": ["either", "the street", "side", "of"]}, "ans": "There are tall buildings on **either side of the street**.", "variants": [{"tag": "過去式", "stem": "There were many stores on ___.", "chunks": ["either", "the river", "side", "of"], "ans": "There were many stores on **either side of the river**."}, {"tag": "未來式", "stem": "There will be lanterns on ___.", "chunks": ["either", "the bridge", "side", "of"], "ans": "There will be lanterns on **either side of the bridge**."}, {"tag": "複數主詞＋過去式", "stem": "Two students sat on ___.", "chunks": ["either", "the teacher", "side", "of"], "ans": "Two students sat on **either side of the teacher**."}], "expl": ["句型：on either side of + N（在……的兩邊）。", "either 後接單數名詞 side（不是 sides）。There are → were（過去）→ will be（未來）。", "易錯：either sides of；或寫成 on the either side。"]}]}, {"name": "動詞片語 help／suggest", "sets": [{"id": "R020", "src": "附件8 Q15", "q": {"stem": "Can you ___?", "chunks": ["my", "homework", "with", "help", "me"]}, "ans": "Can you **help me with my homework**?", "variants": [{"tag": "過去式＋第三人稱單數", "stem": "Did your brother ___?", "chunks": ["your", "science project", "with", "help", "you"], "ans": "Did your brother **help you with your science project**?"}, {"tag": "未來式＋複數主詞", "stem": "Will they ___?", "chunks": ["the cooking", "with", "help", "us"], "ans": "Will they **help us with the cooking**?"}, {"tag": "現在式＋第三人稱單數", "stem": "Does Amy ___?", "chunks": ["her mother", "the housework", "with", "help"], "ans": "Does Amy **help her mother with the housework**?"}], "expl": ["句型：help + 人 + with + 事情", "help me with my homework = 幫我做功課；人在 help 後面，事情在 with 後面。", "易錯：不要寫 help my homework with me。Did／Will／Does 後面一律用原形 help。"]}, {"id": "R025", "src": "附件9 Q15", "q": {"stem": "We have to ___.", "chunks": ["today", "painting", "finish", "the walls", "by"]}, "ans": "We have to **finish painting the walls by today**.", "variants": [{"tag": "第三人稱單數", "stem": "She has to ___.", "chunks": ["Friday", "writing", "finish", "the report", "by"], "ans": "She has to **finish writing the report by Friday**."}, {"tag": "過去式＋複數主詞", "stem": "They had to ___.", "chunks": ["noon", "cleaning", "finish", "the classroom", "by"], "ans": "They had to **finish cleaning the classroom by noon**."}, {"tag": "未來式＋第一人稱", "stem": "I will have to ___.", "chunks": ["next Monday", "reading", "finish", "the book", "by"], "ans": "I will have to **finish reading the book by next Monday**."}], "expl": ["句型：have to + 原形V；finish + V-ing；by + 時間（在…之前）", "finish 後面接動名詞 painting；by today = 今天以前。", "易錯：不可寫 finish to paint。she → has to；過去式 → had to；未來式 → will have to。"]}, {"id": "R031", "src": "附件16 Q6", "q": {"stem": "___.", "chunks": ["smiled", "that girl", "at me,", "I", "smiled back", "and"]}, "ans": "**That girl smiled at me, and I smiled back**.", "variants": [{"tag": "複數主詞＋過去式", "stem": "___.", "chunks": ["waved", "The boys", "at us,", "we", "waved back", "and"], "ans": "**The boys waved at us, and we waved back**."}, {"tag": "現在式＋第三人稱單數", "stem": "___.", "chunks": ["says hi", "Tom", "to me every day,", "I", "say hi back", "and"], "ans": "**Tom says hi to me every day, and I say hi back**."}, {"tag": "未來式", "stem": "___.", "chunks": ["will smile", "The teacher", "at you,", "you", "should smile back", "and"], "ans": "**The teacher will smile at you, and you should smile back**."}], "expl": ["句型：S1 + V + at + 人, and + S2 + V + back", "smile at + 人 = 對某人微笑；smile back = 回以微笑；and 連接兩個子句。", "易錯：smile back 後面不再加 at her。Tom 第三人稱單數 → says；未來式 will smile；兩個子句時態要合理。（原題 chunk that girl 置句首時須大寫 That。）"]}, {"id": "R049", "src": "模擬試題第3回 Q13", "q": {"stem": "My aunt ___ the dog.", "chunks": ["take care of", "that", "I", "suggested"]}, "ans": "My aunt **suggested that I take care of** the dog.", "variants": [{"tag": "子句主詞第三人稱單數", "stem": "The doctor ___ more water.", "chunks": ["drink", "that", "my dad", "suggested"], "ans": "The doctor **suggested that my dad drink** more water."}, {"tag": "複數主詞＋現在式", "stem": "My parents ___ early.", "chunks": ["go to bed", "that", "we", "suggest"], "ans": "My parents **suggest that we go to bed** early."}, {"tag": "主詞 I＋子句主詞 she", "stem": "I ___ a raincoat.", "chunks": ["bring", "that", "she", "suggest"], "ans": "I **suggest that she bring** a raincoat."}], "expl": ["句型：S + suggest(ed) + that + S + (should) + V原形；take care of＝照顧。", "suggest 的 that 子句動詞用原形（省略 should），所以 my dad drink、she bring 不加 s，也不因主句過去式而變 took。", "易錯：寫成 suggested me to take care of，或子句用 drinks／took。（本題依 GEPT 初級歸入動詞片語 take care of 類。）"]}]}]}]}};
